void genTwiddle_shoup(uint64_t *twiddle, uint64_t *twiddle_shoup, int length) {
  for (int i = 0; i < length; i++) {
    __uint128_t temp = twiddle[i];
    temp <<= 64;
    twiddle_shoup[i] = temp / MOD;
  }
}

__forceinline__ __device__ void csub_q(uint64_t &operand,
                                       const uint64_t modulus) {
  const uint64_t tmp = operand - modulus;
  operand = tmp + (tmp >> 63) * modulus;
}

[[nodiscard]] __inline__ __device__ uint64_t multiply_and_reduce_shoup_lazy(
    const uint64_t &operand1, const uint64_t &operand2,
    const uint64_t &operand2_shoup, const uint64_t &modulus) {
  const uint64_t hi = __umul64hi(operand1, operand2_shoup);
  uint64_t result = operand1 * operand2 - hi * modulus >= modulus
                        ? operand1 * operand2 - hi * modulus - modulus
                        : operand1 * operand2 - hi * modulus;
  return result;
}

__forceinline__ __device__ uint64_t precompute_shoup(uint64_t b, uint64_t mod) {
  // 计算 b_shoup = floor((b << 64) / mod)
  uint64_t q = 0;
  uint64_t remainder =
      b;  // 初始余数 = b (因为 b << 64 等价于高位为 b，低位为 0)

  // 通过逐位除法模拟 128 位运算
  for (int i = 0; i < 64; i++) {
    remainder <<= 1;  // 左移一位（模拟 128 位左移）
    q <<= 1;          // 商左移一位

    if (remainder >= mod) {
      remainder -= mod;
      q |= 1;  // 当前位商为 1
    }
  }
  return q;
}

[[nodiscard]] __inline__ __device__ uint64_t
multiply_and_reduce_shoup_lazy_dotproduct(
    const uint64_t &operand1, const uint64_t &operand2,
    const uint64_t &
        modulus) { /*
                   uint64_t hi_1=operand2;
                   uint64_t lo=0;
                   uint64_t q_hi=hi_1/modulus;
                   uint64_t r_hi=hi_1%modulus;
                   uint64_t combined_lo=(r_hi<<32)|(lo>>32);
                   uint64_t q_lo=combined_lo/modulus;
                   uint64_t operand2_shoup=(q_hi<<32)+q_lo;
                   const uint64_t hi=__umul64hi(operand1,operand2_shoup);
                   uint64_t
                   result=operand1*operand2-hi*modulus>=modulus?operand1*operand2-hi*modulus-modulus:operand1*operand2-hi*modulus;
                   return result;
                   */
  uint64_t operand2_shoup = precompute_shoup(operand2, modulus);
  const uint64_t hi = __umul64hi(operand1, operand2_shoup);
  uint64_t result = operand1 * operand2 - hi * modulus >= modulus
                        ? operand1 * operand2 - hi * modulus - modulus
                        : operand1 * operand2 - hi * modulus;
  return result;
}

__global__ void multiply_dotproduct(uint64_t *inout, uint64_t *inoutA,
                                    uint64_t *result, int length, uint64_t mod);

__global__ void multiply_dotproduct(uint64_t *inout, uint64_t *inoutA,
                                    uint64_t *result, int length,
                                    uint64_t mod) {
  for (uint64_t i = blockIdx.x * blockDim.x + threadIdx.x; i < length;
       i += blockDim.x * gridDim.x) {
    result[i] =
        multiply_and_reduce_shoup_lazy_dotproduct(inout[i], inoutA[i], mod);
  }
}

