__device__ __forceinline__ void ct_butterfly(uint64_t &x, uint64_t &y,
                                             const uint64_t &tw,
                                             const uint64_t &tw_shoup,
                                             const uint64_t &mod) {
  const uint64_t tw_y = multiply_and_reduce_shoup_lazy(y, tw, tw_shoup, mod);
  // const uint64_t hi = __umul64hi(y, tw_shoup);
  // const uint64_t tw_y = y * tw - hi * mod;  //得到tw_y=tw*y % mod   [0,2*mod)
  // tw_y>=mod?tw_y-mod:tw_y;
  //  csub_q(x, mod2);
  // const uint64_t mod2 = 2 * mod;
  // const uint64_t tmp = x - mod2;
  // x = tmp + (tmp >> 63) * mod2;     //得到x=x-mod2 [0,2*mod)
  // y = x + mod2 - tw_y;     //y:[0,4*mod-1]
  y = x - tw_y + mod;
  x += tw_y;  // x:[0,4*mod-1]
  csub_q(x, mod);
  csub_q(y, mod);
}

__device__ __forceinline__ void gs_butterfly(uint64_t &x, uint64_t &y,
                                             const uint64_t &tw,
                                             const uint64_t &tw_shoup,
                                             const uint64_t &mod) {
  /*
  const uint64_t mod2 = 2 * mod;
  const uint64_t t = x + mod2 - y; // [0, 4q)
  uint64_t s = x + y; // [0, 4q)
  csub_q(s, mod2); // [0, 2q)
  x = s;
  y = multiply_and_reduce_shoup_lazy(t, tw, tw_shoup, mod);
  */
  uint64_t u = x + y;
  uint64_t v = x - y + mod;
  x = u;
  csub_q(x, mod);
  y = multiply_and_reduce_shoup_lazy(v, tw, tw_shoup, mod);
}

__device__ __forceinline__ void gs_butterfly_left(uint64_t &x, uint64_t y,
                                                  const uint64_t &tw,
                                                  const uint64_t &tw_shoup,
                                                  const uint64_t &mod) {
  /*
  const uint64_t mod2 = 2 * mod;
  const uint64_t t = x + mod2 - y; // [0, 4q)
  uint64_t s = x + y; // [0, 4q)
  csub_q(s, mod2); // [0, 2q)
  x = s;
  y = multiply_and_reduce_shoup_lazy(t, tw, tw_shoup, mod);
  */
  uint64_t u = x + y;
  // uint64_t v=x-y+mod;
  x = u;
  csub_q(x, mod);
  // y=multiply_and_reduce_shoup_lazy(v,tw,tw_shoup,mod);
}

__device__ __forceinline__ void gs_butterfly_right(uint64_t x, uint64_t &y,
                                                   const uint64_t &tw,
                                                   const uint64_t &tw_shoup,
                                                   const uint64_t &mod) {
  /*
  const uint64_t mod2 = 2 * mod;
  const uint64_t t = x + mod2 - y; // [0, 4q)
  uint64_t s = x + y; // [0, 4q)
  csub_q(s, mod2); // [0, 2q)
  x = s;
  y = multiply_and_reduce_shoup_lazy(t, tw, tw_shoup, mod);
  */
  // uint64_t u=x+y;
  uint64_t v = x - y + mod;
  // x=u;
  // csub_q(x,mod);
  y = multiply_and_reduce_shoup_lazy(v, tw, tw_shoup, mod);
}

/*
128线程的CT变换和NCT变换




*/

__global__ void Testctsample(uint64_t *inout, uint64_t n, uint64_t mod,
                             uint64_t *twiddle, uint64_t *twiddle_shoup);

__global__ void Testctsample(uint64_t *inout, uint64_t n, uint64_t mod,
                             uint64_t *twiddle, uint64_t *twiddle_shoup) {
  // extern __shared__ uint64_t s_twiddle[];

  __shared__ uint64_t buffer[256];
  //__shared__ uint64_t s_twiddle[256];

  for (uint64_t i = blockIdx.x * blockDim.x + threadIdx.x; i < n / 2;
       i += blockDim.x * gridDim.x) {
    uint64_t tid = i;

    register uint64_t pairsInGroup;
    register uint64_t k, j, glbIdx, glbIdxadd;  // k = psi_step
    register uint64_t samples[2];
    register uint64_t omgn, omgn_shoup;
    register uint64_t twiddleId;

    for (uint64_t numOfGroups = 1; numOfGroups <= n / 2;
         numOfGroups = numOfGroups << 1) {
      pairsInGroup = n / numOfGroups / 2;

      k = tid / pairsInGroup;  // numOfGroups是这一轮NTT变换中的分组数
      j = tid % pairsInGroup;
      // pairInGroup 是每个分组中多少对; k=psi_step?  k是组号；j是对号
      glbIdx = 2 * k * pairsInGroup + j;
      glbIdxadd = glbIdx + pairsInGroup;  // 计算全局内存的索引
      // blfIdx=glbIdx;

      twiddleId = pairsInGroup + j;
      omgn = twiddle[twiddleId];
      omgn_shoup = twiddle_shoup[twiddleId];

      // printf("pairsInGroup:%llu ",pairsInGroup);
      samples[0] = inout[glbIdx];
      samples[1] = inout[glbIdxadd];
      // printf("sample[glb]:%llu ",samples[0]);
      // printf("sample[glbIdxadd]:%llu ",samples[1]);
      if (numOfGroups == 1) {
        samples[0] = inout[glbIdx];
        samples[1] = inout[glbIdxadd];

      } else {
        samples[0] = buffer[glbIdx];
        samples[1] = buffer[glbIdxadd];
        // printf("sample[glb]:%llu ",samples[0]);
        // printf("sample[glbIdxadd]:%llu ",samples[1]);
      }
      // uuint64_t start=clock64();
      // GSbutter(samples[0],samples[1],mod,omgn);
      gs_butterfly(samples[0], samples[1], omgn, omgn_shoup, mod);
      // uuint64_t end=clock64();
      // d_clocktime[tid]=end-start;

      if (numOfGroups == (n / 2)) {
        inout[glbIdx] = samples[0];

        inout[glbIdxadd] = samples[1];

      } else {
        buffer[glbIdx] = samples[0];
        // printf("inout[glb]:%llu ",buffer[glbIdx]);
        buffer[glbIdxadd] = samples[1];
        __syncthreads();  // 线程同步
        // printf("inout[glb]:%llu ",inout[glbIdx]);
        // printf("inout[glbIdxadd]:%llu ",inout[glbIdxadd]);
      }
    }
  }
}

__global__ void TestInvctsample(uint64_t *inout, uint64_t n, uint64_t mod,
                                uint64_t *ICTTwiddle,
                                uint64_t *ICTTwiddle_shoup, uint64_t inv,
                                uint64_t inv_shoup);

__global__ void TestInvctsample(uint64_t *inout, uint64_t n, uint64_t mod,
                                uint64_t *ICTTwiddle,
                                uint64_t *ICTTwiddle_shoup, uint64_t inv,
                                uint64_t inv_shoup) {
  // extern __shared__ uint64_t s_twiddle[];

  __shared__ uint64_t buffer4[256];
  // uint64_t inv=ksm(n,mod-2,mod);
  //__shared__ uint64_t s_twiddle[256];

  // uint64_t invn=inv;
  // uint64_t invn_shoup=inv_shoup;
  for (uint64_t i = blockIdx.x * blockDim.x + threadIdx.x; i < n / 2;
       i += blockDim.x * gridDim.x) {
    uint64_t tid = i;
    uint64_t pairsInGroup;
    uint64_t k, j, glbIdx, glbIdxadd;  // k = psi_step
    register uint64_t samples[2];
    uint64_t omgn, omgn_shoup;
    uint64_t ICTtwiddleId;

    for (uint64_t numOfGroups = n / 2; numOfGroups >= 1;
         numOfGroups = numOfGroups / 2) {
      pairsInGroup = n / numOfGroups / 2;

      k = tid / pairsInGroup;  // numOfGroups是这一轮NTT变换中的分组数
      j = tid % pairsInGroup;
      // pairInGroup 是每个分组中多少对; k=psi_step?  k是组号；j是对号
      glbIdx = 2 * k * pairsInGroup + j;
      glbIdxadd = glbIdx + pairsInGroup;  // 计算全局内存的索引

      ICTtwiddleId = pairsInGroup + j;
      omgn = ICTTwiddle[ICTtwiddleId];
      omgn_shoup = ICTTwiddle_shoup[ICTtwiddleId];
      if (numOfGroups == (n / 2)) {
        samples[0] = inout[glbIdx];
        samples[1] = inout[glbIdxadd];

      }

      else {
        samples[0] = buffer4[glbIdx];
        samples[1] = buffer4[glbIdxadd];
      }

      // CTbutter(samples[0],samples[1],mod,omgn);
      ct_butterfly(samples[0], samples[1], omgn, omgn_shoup, mod);

      if (numOfGroups == 1) {
        // csub_q(samples[0],mod);
        // csub_q(samples[1],mod);
        inout[glbIdx] = samples[0];
        inout[glbIdxadd] = samples[1];

        // inout[glbIdx]=ksc(inout[glbIdx],inv,mod);
        inout[glbIdx] =
            multiply_and_reduce_shoup_lazy(inout[glbIdx], inv, inv_shoup, mod);
        // inout[glbIdxadd]=ksc(inout[glbIdxadd],inv,mod);
        inout[glbIdxadd] = multiply_and_reduce_shoup_lazy(inout[glbIdxadd], inv,
                                                          inv_shoup, mod);
        __syncthreads();

      } else {
        buffer4[glbIdx] = samples[0];

        buffer4[glbIdxadd] = samples[1];
        __syncthreads();  // 线程同步
        // printf("inout[glb]:%llu ",inout[glbIdx]);
        // printf("inout[glbIdxadd]:%llu ",inout[glbIdxadd]);
      }
    }
  }
}

__global__ void XYfixWarp(uint64_t *inout, uint64_t *inoutA, uint64_t *negmodn,
                          uint64_t *negmodn_shoup, uint64_t *modn,
                          uint64_t *modn_shoup, uint64_t n, uint64_t mod,
                          uint64_t *twiddle, uint64_t *twiddle_shoup,
                          uint64_t *ICTTwiddle, uint64_t *ICTTwiddle_shoup,
                          uint64_t *NCTtwiddle, uint64_t *NCTtwiddle_shoup,
                          uint64_t *InvNCTtwiddle,
                          uint64_t *InvNCTtwiddle_shoup, uint64_t inv,
                          uint64_t inv_shoup, uint64_t *sample);

__global__ void XYfixWarp(uint64_t *inout, uint64_t *inoutA, uint64_t *negmodn,
                          uint64_t *negmodn_shoup, uint64_t *modn,
                          uint64_t *modn_shoup, uint64_t n, uint64_t mod,
                          uint64_t *twiddle, uint64_t *twiddle_shoup,
                          uint64_t *ICTTwiddle, uint64_t *ICTTwiddle_shoup,
                          uint64_t *NCTtwiddle, uint64_t *NCTtwiddle_shoup,
                          uint64_t *InvNCTtwiddle,
                          uint64_t *InvNCTtwiddle_shoup, uint64_t inv,
                          uint64_t inv_shoup, uint64_t *sample) {
  for (uint64_t i = blockIdx.x * blockDim.x + threadIdx.x; i < 32;
       i += blockDim.x * gridDim.x) {
    // printf("tid:%llu ",i);
    // ct x fix
    /*
    if (i == 0) {
    printf(">>> [GPU 接收数据检查] <<<\n");
    printf("inout[0] = %llu\n", (unsigned long long)inout[0]);
    printf("inoutA[0] = %llu\n", (unsigned long long)inoutA[0]);
    printf("modn[0] = %llu\n", (unsigned long long)modn[0]);
    printf("negmodn[0] = %llu\n", (unsigned long long)negmodn[0]);
    printf("twiddle[3] = %llu\n", (unsigned long long)twiddle[3]);
    printf("mod = %llu\n", (unsigned long long)mod);
    }
    */
    register uint64_t CTinout[8];
    register uint64_t CTinoutA[8];

    register uint64_t NCTinout[8];
    register uint64_t NCTinoutA[8];

    register uint64_t regs[8];
    register uint64_t new_regs[8];

    // uint64_t numIdx[8];
    register uint64_t C;
    register uint64_t omegnIdx[8];
    register uint64_t left[8];
    register uint64_t right[8];

    // __shared__ uint64_t s_tile[8][32];
    /*
    #pragma unroll
        for (int j = 0; j < 8; j++) {

            s_tile[j][i] = inout[i*8+j];
        }
        __syncwarp();
    #pragma unroll
        for (int j = 0; j < 8; j++) {

            regs[j] = s_tile[j][i];
        }
    */

    regs[0] = inout[8 * i];
    regs[1] = inout[8 * i + 1];
    regs[2] = inout[8 * i + 2];
    regs[3] = inout[8 * i + 3];
    regs[4] = inout[8 * i + 4];
    regs[5] = inout[8 * i + 5];
    regs[6] = inout[8 * i + 6];
    regs[7] = inout[8 * i + 7];

    // printf("inout[8*i]:%llu ",regs[0]);
    // uint64_t nums=log2(n);
    for (size_t log_m = 0; log_m < 5; log_m++) {
      size_t log_step = 4 - log_m;
      uint64_t pairsInGroup = 1 << (log_step + 3);
      new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
      new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
      new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
      new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
      new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
      new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
      new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
      new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

      // printf("new_regs[0]:%llu ",new_regs[0]);

      C = (i >> log_step) & 1;
      // printf("C:%llu ",C);
      omegnIdx[0] = (8 * i) % pairsInGroup + pairsInGroup;
      omegnIdx[1] = pairsInGroup + ((8 * i + 1) % pairsInGroup);
      omegnIdx[2] = pairsInGroup + ((8 * i + 2) % pairsInGroup);
      omegnIdx[3] = pairsInGroup + ((8 * i + 3) % pairsInGroup);
      omegnIdx[4] = pairsInGroup + ((8 * i + 4) % pairsInGroup);
      omegnIdx[5] = pairsInGroup + ((8 * i + 5) % pairsInGroup);
      omegnIdx[6] = pairsInGroup + ((8 * i + 6) % pairsInGroup);
      omegnIdx[7] = pairsInGroup + ((8 * i + 7) % pairsInGroup);
      // printf("omegnIdx[0]:%llu ",omegnIdx[0]);

      left[0] = (1 - C) * (regs[0] - new_regs[0]) + new_regs[0];
      left[1] = (1 - C) * (regs[1] - new_regs[1]) + new_regs[1];
      left[2] = (1 - C) * (regs[2] - new_regs[2]) + new_regs[2];
      left[3] = (1 - C) * (regs[3] - new_regs[3]) + new_regs[3];
      left[4] = (1 - C) * (regs[4] - new_regs[4]) + new_regs[4];
      left[5] = (1 - C) * (regs[5] - new_regs[5]) + new_regs[5];
      left[6] = (1 - C) * (regs[6] - new_regs[6]) + new_regs[6];
      left[7] = (1 - C) * (regs[7] - new_regs[7]) + new_regs[7];

      right[0] = C * (regs[0] - new_regs[0]) + new_regs[0];
      right[1] = C * (regs[1] - new_regs[1]) + new_regs[1];
      right[2] = C * (regs[2] - new_regs[2]) + new_regs[2];
      right[3] = C * (regs[3] - new_regs[3]) + new_regs[3];
      right[4] = C * (regs[4] - new_regs[4]) + new_regs[4];
      right[5] = C * (regs[5] - new_regs[5]) + new_regs[5];
      right[6] = C * (regs[6] - new_regs[6]) + new_regs[6];
      right[7] = C * (regs[7] - new_regs[7]) + new_regs[7];

      gs_butterfly(left[0], right[0], twiddle[omegnIdx[0]],
                   twiddle_shoup[omegnIdx[0]], mod);
      gs_butterfly(left[1], right[1], twiddle[omegnIdx[1]],
                   twiddle_shoup[omegnIdx[1]], mod);
      gs_butterfly(left[2], right[2], twiddle[omegnIdx[2]],
                   twiddle_shoup[omegnIdx[2]], mod);
      gs_butterfly(left[3], right[3], twiddle[omegnIdx[3]],
                   twiddle_shoup[omegnIdx[3]], mod);
      gs_butterfly(left[4], right[4], twiddle[omegnIdx[4]],
                   twiddle_shoup[omegnIdx[4]], mod);
      gs_butterfly(left[5], right[5], twiddle[omegnIdx[5]],
                   twiddle_shoup[omegnIdx[5]], mod);
      gs_butterfly(left[6], right[6], twiddle[omegnIdx[6]],
                   twiddle_shoup[omegnIdx[6]], mod);
      gs_butterfly(left[7], right[7], twiddle[omegnIdx[7]],
                   twiddle_shoup[omegnIdx[7]], mod);

      regs[0] = (1 - C) * (left[0] - right[0]) + right[0];
      regs[1] = (1 - C) * (left[1] - right[1]) + right[1];
      regs[2] = (1 - C) * (left[2] - right[2]) + right[2];
      regs[3] = (1 - C) * (left[3] - right[3]) + right[3];
      regs[4] = (1 - C) * (left[4] - right[4]) + right[4];
      regs[5] = (1 - C) * (left[5] - right[5]) + right[5];
      regs[6] = (1 - C) * (left[6] - right[6]) + right[6];
      regs[7] = (1 - C) * (left[7] - right[7]) + right[7];
      /*
      omegnIdx[0]=(8*i)%pairsInGroup+pairsInGroup;
      omegnIdx[1]=pairsInGroup+((8*i+1)%pairsInGroup);
      omegnIdx[2]=pairsInGroup+((8*i+2)%pairsInGroup);
      omegnIdx[3]=pairsInGroup+((8*i+3)%pairsInGroup);
      omegnIdx[4]=pairsInGroup+((8*i+4)%pairsInGroup);
      omegnIdx[5]=pairsInGroup+((8*i+5)%pairsInGroup);
      omegnIdx[6]=pairsInGroup+((8*i+6)%pairsInGroup);
      omegnIdx[7]=pairsInGroup+((8*i+7)%pairsInGroup);
      //printf("omegnIdx[0]:%llu ",omegnIdx[0]);

      left[0]=(1-C)*(regs[0]-new_regs[0])+new_regs[0];
      left[1]=(1-C)*(regs[1]-new_regs[1])+new_regs[1];
      left[2]=(1-C)*(regs[2]-new_regs[2])+new_regs[2];
      left[3]=(1-C)*(regs[3]-new_regs[3])+new_regs[3];
      left[4]=(1-C)*(regs[4]-new_regs[4])+new_regs[4];
      left[5]=(1-C)*(regs[5]-new_regs[5])+new_regs[5];
      left[6]=(1-C)*(regs[6]-new_regs[6])+new_regs[6];
      left[7]=(1-C)*(regs[7]-new_regs[7])+new_regs[7];



      right[0]=C*(regs[0]-new_regs[0])+new_regs[0];
      right[1]=C*(regs[1]-new_regs[1])+new_regs[1];
      right[2]=C*(regs[2]-new_regs[2])+new_regs[2];
      right[3]=C*(regs[3]-new_regs[3])+new_regs[3];
      right[4]=C*(regs[4]-new_regs[4])+new_regs[4];
      right[5]=C*(regs[5]-new_regs[5])+new_regs[5];
      right[6]=C*(regs[6]-new_regs[6])+new_regs[6];
      right[7]=C*(regs[7]-new_regs[7])+new_regs[7];


      gs_butterfly(left[0],right[0],twiddle[omegnIdx[0]],twiddle_shoup[omegnIdx[0]],mod);
      gs_butterfly(left[1],right[1],twiddle[omegnIdx[1]],twiddle_shoup[omegnIdx[1]],mod);
      gs_butterfly(left[2],right[2],twiddle[omegnIdx[2]],twiddle_shoup[omegnIdx[2]],mod);
      gs_butterfly(left[3],right[3],twiddle[omegnIdx[3]],twiddle_shoup[omegnIdx[3]],mod);
      gs_butterfly(left[4],right[4],twiddle[omegnIdx[4]],twiddle_shoup[omegnIdx[4]],mod);
      gs_butterfly(left[5],right[5],twiddle[omegnIdx[5]],twiddle_shoup[omegnIdx[5]],mod);
      gs_butterfly(left[6],right[6],twiddle[omegnIdx[6]],twiddle_shoup[omegnIdx[6]],mod);
      gs_butterfly(left[7],right[7],twiddle[omegnIdx[7]],twiddle_shoup[omegnIdx[7]],mod);



      regs[0]=(1-C)*(left[0]-right[0])+right[0];
      regs[1]=(1-C)*(left[1]-right[1])+right[1];
      regs[2]=(1-C)*(left[2]-right[2])+right[2];
      regs[3]=(1-C)*(left[3]-right[3])+right[3];
      regs[4]=(1-C)*(left[4]-right[4])+right[4];
      regs[5]=(1-C)*(left[5]-right[5])+right[5];
      regs[6]=(1-C)*(left[6]-right[6])+right[6];
      regs[7]=(1-C)*(left[7]-right[7])+right[7];
      //printf("regs[0]:%llu ",regs[0]);
      */
    }

    gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
    gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
    gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
    gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

    gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
    gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
    gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
    gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

    gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
    gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
    gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
    gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);
    /*
    inout[8*i]=regs[0];
    inout[8*i+1]=regs[1];
    inout[8*i+2]=regs[2];
    inout[8*i+3]=regs[3];
    inout[8*i+4]=regs[4];
    inout[8*i+5]=regs[5];
    inout[8*i+6]=regs[6];
    inout[8*i+7]=regs[7];
    */
    CTinout[0] = regs[0];
    CTinout[1] = regs[1];
    CTinout[2] = regs[2];
    CTinout[3] = regs[3];
    CTinout[4] = regs[4];
    CTinout[5] = regs[5];
    CTinout[6] = regs[6];
    CTinout[7] = regs[7];

    // ct y fix

    regs[0] = inoutA[8 * i];
    regs[1] = inoutA[8 * i + 1];
    regs[2] = inoutA[8 * i + 2];
    regs[3] = inoutA[8 * i + 3];
    regs[4] = inoutA[8 * i + 4];
    regs[5] = inoutA[8 * i + 5];
    regs[6] = inoutA[8 * i + 6];
    regs[7] = inoutA[8 * i + 7];
    /*

#pragma unroll
    for (int j = 0; j < 8; j++) {

        s_tile[j][i] = inoutA[i*8+j];
    }
    __syncwarp();
#pragma unroll
    for (int j = 0; j < 8; j++) {

        regs[j] = s_tile[j][i];
    }
        */
