    regs1[2] = Aa1[2] & mod_mask;
    regs1[3] = Aa1[3] & mod_mask;
    regs1[4] = Aa1[4] & mod_mask;
    regs1[5] = Aa1[5] & mod_mask;
    regs1[6] = Aa1[6] & mod_mask;
    regs1[7] = Aa1[7] & mod_mask;

    regs3[0] = regs0[0] >> u;
    regs3[1] = regs0[1] >> u;
    regs3[2] = regs0[2] >> u;
    regs3[3] = regs0[3] >> u;
    regs3[4] = regs0[4] >> u;
    regs3[5] = regs0[5] >> u;
    regs3[6] = regs0[6] >> u;
    regs3[7] = regs0[7] >> u;

    regs4[0] = regs0[0] & mod_mask;
    regs4[1] = regs0[1] & mod_mask;
    regs4[2] = regs0[2] & mod_mask;
    regs4[3] = regs0[3] & mod_mask;
    regs4[4] = regs0[4] & mod_mask;
    regs4[5] = regs0[5] & mod_mask;
    regs4[6] = regs0[6] & mod_mask;
    regs4[7] = regs0[7] & mod_mask;

    if (i == 31) {
      retail[0] = regs3[6] + regs4[7];
      // printf("retail[0]:%llu ",retail[0]);
      retail[1] = regs3[7];
    }

    new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
    new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
    new_regs3[2] = regs3[0];
    new_regs3[3] = regs3[1];
    new_regs3[4] = regs3[2];
    new_regs3[5] = regs3[3];
    new_regs3[6] = regs3[4];
    new_regs3[7] = regs3[5];

    new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
    new_regs4[1] = regs4[0];
    new_regs4[2] = regs4[1];
    new_regs4[3] = regs4[2];
    new_regs4[4] = regs4[3];
    new_regs4[5] = regs4[4];
    new_regs4[6] = regs4[5];
    new_regs4[7] = regs4[6];

    if (i == 0) {
      sum[0] = regs1[0];
      sum[1] = (regs1[1] + new_regs4[1]);
      for (int j = 2; j <= 7; j++) {
        sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
      }
    } else if (i == 31) {
      for (int j = 0; j <= 7; j++) {
        sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
      }
      // printf("sum7:%llu ",sum[7]);
      carry = sum[7] >> u;
      // printf("carry7:%llu ",carry);
    } else {
      for (int j = 0; j <= 7; j++) {
        sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
      }
    }

    uint64_t temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);

    if (i == 0) {
      prev_sum[0] = 0;  // 线程0 显式置0，忽略 shuffle 的结果
      for (int j = 1; j <= 7; j++) {
        prev_sum[j] = sum[j - 1] >> u;
      }
    } else {
      prev_sum[0] = temp_shuffled;  // 线程1-31 使用 shuffle 的结果
      for (int j = 1; j <= 7; j++) {
        prev_sum[j] = sum[j - 1] >> u;
      }
    }

    tail[0] = (sum[0] & mod_mask) + prev_sum[0];
    tail[1] = (sum[1] & mod_mask) + prev_sum[1];
    tail[2] = (sum[2] & mod_mask) + prev_sum[2];
    tail[3] = (sum[3] & mod_mask) + prev_sum[3];
    tail[4] = (sum[4] & mod_mask) + prev_sum[4];
    tail[5] = (sum[5] & mod_mask) + prev_sum[5];
    tail[6] = (sum[6] & mod_mask) + prev_sum[6];
    tail[7] = (sum[7] & mod_mask) + prev_sum[7];

    for (int j = 0; j <= 6; j++) {
      if (tail[j] == 131072) {
        tail[j] = 0;
        tail[j + 1] += 1;
      }
    }
    carry_32[i] = tail[7] >> u;
    tail[7] = (tail[7] == 131072) ? 0 : (tail[7] & mod_mask);

    // carry_32[i]=tail[7]>>u;
    // printf("before%2d: ",i);
    __syncwarp();
// printf("carry32:%llu ",carry_32[i]);
// printf("after%2d: ",i);
#if 1
    // mask = __activemask();
    // printf("线程 %2d: 条件满足，当前活跃掩码 = 0x%x\n", i, mask);
    //__syncwarp(__activemask());
    //__syncwarp(0x20);
    // printf("carry32:%llu ",carry_32[i]);

    if (i == 0) {
      sum_carry_32 = 0;
      for (int j = 0; j < 31; j++) {
        sum_carry_32 += carry_32[j];
      }

      // mask = __activemask();
      // printf("线程 %2d: if条件满足，当前活跃掩码 = 0x%x\n", i, mask);
      // printf("sum32:%llu ",sum_carry_32);
    }

    if (sum_carry_32 != 0) {
      for (int j = 0; j < 8; j++) {
