    gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
    gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
    gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
