    gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
    gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
    gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
    gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);
    Aa1[0] = regs[0];
