      right[6] = C * (regs[6] - new_regs[6]) + new_regs[6];
      right[7] = C * (regs[7] - new_regs[7]) + new_regs[7];

      // GSbutter(left[0],right[0],mod,twiddle[omegnIdx[0]]);
      // GSbutter(left[1],right[1],mod,twiddle[omegnIdx[1]]);
      // GSbutter(left[2],right[2],mod,twiddle[omegnIdx[2]]);
