      // GSbutter(left[5],right[5],mod,twiddle[omegnIdx[5]]);
      // GSbutter(left[6],right[6],mod,twiddle[omegnIdx[6]]);
      // GSbutter(left[7],right[7],mod,twiddle[omegnIdx[7]]);
      ct_butterfly(left[0], right[0], ICTTwiddle[omegnIdx[0]],
                   ICTTwiddle_shoup[omegnIdx[0]], mod);
      ct_butterfly(left[1], right[1], ICTTwiddle[omegnIdx[1]],
                   ICTTwiddle_shoup[omegnIdx[1]], mod);
      ct_butterfly(left[2], right[2], ICTTwiddle[omegnIdx[2]],
