      ct_butterfly(left[7], right[7], ICTTwiddle[omegnIdx[7]],
                   ICTTwiddle_shoup[omegnIdx[7]], mod);

      regs[0] = (1 - C) * (left[0] - right[0]) + right[0];
      regs[1] = (1 - C) * (left[1] - right[1]) + right[1];
      regs[2] = (1 - C) * (left[2] - right[2]) + right[2];
      regs[3] = (1 - C) * (left[3] - right[3]) + right[3];
