    left[1]=(1-C)*(regs[1]-new_regs[1])+new_regs[1];
    left[2]=(1-C)*(regs[2]-new_regs[2])+new_regs[2];
    left[3]=(1-C)*(regs[3]-new_regs[3])+new_regs[3];
    left[4]=(1-C)*(regs[4]-new_regs[4])+new_regs[4];
    left[5]=(1-C)*(regs[5]-new_regs[5])+new_regs[5];
    left[6]=(1-C)*(regs[6]-new_regs[6])+new_regs[6];
    left[7]=(1-C)*(regs[7]-new_regs[7])+new_regs[7];



    right[0]=C*(regs[0]-new_regs[0])+new_regs[0];
    right[1]=C*(regs[1]-new_regs[1])+new_regs[1];
    right[2]=C*(regs[2]-new_regs[2])+new_regs[2];
    right[3]=C*(regs[3]-new_regs[3])+new_regs[3];
    right[4]=C*(regs[4]-new_regs[4])+new_regs[4];
    right[5]=C*(regs[5]-new_regs[5])+new_regs[5];
    right[6]=C*(regs[6]-new_regs[6])+new_regs[6];
    right[7]=C*(regs[7]-new_regs[7])+new_regs[7];


    gs_butterfly(left[0],right[0],InvNCTtwiddle[omegnIdx[0]],InvNCTtwiddle_shoup[omegnIdx[0]],mod);
    gs_butterfly(left[1],right[1],InvNCTtwiddle[omegnIdx[1]],InvNCTtwiddle_shoup[omegnIdx[1]],mod);
    gs_butterfly(left[2],right[2],InvNCTtwiddle[omegnIdx[2]],InvNCTtwiddle_shoup[omegnIdx[2]],mod);
    gs_butterfly(left[3],right[3],InvNCTtwiddle[omegnIdx[3]],InvNCTtwiddle_shoup[omegnIdx[3]],mod);
    gs_butterfly(left[4],right[4],InvNCTtwiddle[omegnIdx[4]],InvNCTtwiddle_shoup[omegnIdx[4]],mod);
    gs_butterfly(left[5],right[5],InvNCTtwiddle[omegnIdx[5]],InvNCTtwiddle_shoup[omegnIdx[5]],mod);
    gs_butterfly(left[6],right[6],InvNCTtwiddle[omegnIdx[6]],InvNCTtwiddle_shoup[omegnIdx[6]],mod);
    gs_butterfly(left[7],right[7],InvNCTtwiddle[omegnIdx[7]],InvNCTtwiddle_shoup[omegnIdx[7]],mod);


    regs[0]=(1-C)*(left[0]-right[0])+right[0];
    regs[1]=(1-C)*(left[1]-right[1])+right[1];
    regs[2]=(1-C)*(left[2]-right[2])+right[2];
    regs[3]=(1-C)*(left[3]-right[3])+right[3];
    regs[4]=(1-C)*(left[4]-right[4])+right[4];
    regs[5]=(1-C)*(left[5]-right[5])+right[5];
    regs[6]=(1-C)*(left[6]-right[6])+right[6];
    regs[7]=(1-C)*(left[7]-right[7])+right[7];

    inoutA[8*i]=multiply_and_reduce_shoup_lazy(regs[0],inv,inv_shoup,mod);
    inoutA[8*i+1]=multiply_and_reduce_shoup_lazy(regs[1],inv,inv_shoup,mod);
    inoutA[8*i+2]=multiply_and_reduce_shoup_lazy(regs[2],inv,inv_shoup,mod);
    inoutA[8*i+3]=multiply_and_reduce_shoup_lazy(regs[3],inv,inv_shoup,mod);
    inoutA[8*i+4]=multiply_and_reduce_shoup_lazy(regs[4],inv,inv_shoup,mod);
    inoutA[8*i+5]=multiply_and_reduce_shoup_lazy(regs[5],inv,inv_shoup,mod);
    inoutA[8*i+6]=multiply_and_reduce_shoup_lazy(regs[6],inv,inv_shoup,mod);
    inoutA[8*i+7]=multiply_and_reduce_shoup_lazy(regs[7],inv,inv_shoup,mod);
    */
    // modh Gx fix
    // const uint64_t mod_mask=(1ULL<<u)-1;
    register int64_t sregs0[8];
    register int64_t sregs[8];
    register int64_t sregs1[8];
    register int64_t sregs3[8];
    register int64_t sregs4[8];
    register int64_t snew_regs3[8];
    register int64_t snew_regs4[8];
    register int64_t ssum[8];
    register int64_t sprev_sum[8];
    register int64_t stail[8];
    register uint64_t DivMod[8];
    __shared__ int64_t scarry_32[32];
    __shared__ int64_t ssum_carry_32;

    __shared__ int64_t sdata_tail[256];

    __shared__ int64_t scarry;
    // uint64_t carrySum=0;
    __shared__ int64_t sretail[2];

    // new_regs3[0]=new_regs3[1]=0;
    // new_regs4[0]=0;

    sregs0[0] = (Gx[0] > sample[8 * i])
                    ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                    : static_cast<int64_t>(Gx[0]);
    sregs0[1] = (Gx[1] > sample[8 * i + 1])
                    ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                    : static_cast<int64_t>(Gx[1]);
    sregs0[2] = (Gx[2] > sample[8 * i + 2])
                    ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                    : static_cast<int64_t>(Gx[2]);
    sregs0[3] = (Gx[3] > sample[8 * i + 3])
                    ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                    : static_cast<int64_t>(Gx[3]);
    sregs0[4] = (Gx[4] > sample[8 * i + 4])
                    ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                    : static_cast<int64_t>(Gx[4]);
    sregs0[5] = (Gx[5] > sample[8 * i + 5])
                    ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                    : static_cast<int64_t>(Gx[5]);
    sregs0[6] = (Gx[6] > sample[8 * i + 6])
                    ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                    : static_cast<int64_t>(Gx[6]);
    sregs0[7] = (Gx[7] > sample[8 * i + 7])
                    ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                    : static_cast<int64_t>(Gx[7]);

    sregs[0] = sregs0[0] >> u;
    sregs[1] = sregs0[1] >> u;
    sregs[2] = sregs0[2] >> u;
    sregs[3] = sregs0[3] >> u;
    sregs[4] = sregs0[4] >> u;
    sregs[5] = sregs0[5] >> u;
    sregs[6] = sregs0[6] >> u;
    sregs[7] = sregs0[7] >> u;

    sregs1[0] = sregs0[0] & mod_mask;
    sregs1[1] = sregs0[1] & mod_mask;
    sregs1[2] = sregs0[2] & mod_mask;
    sregs1[3] = sregs0[3] & mod_mask;
    sregs1[4] = sregs0[4] & mod_mask;
    sregs1[5] = sregs0[5] & mod_mask;
    sregs1[6] = sregs0[6] & mod_mask;
    sregs1[7] = sregs0[7] & mod_mask;

    sregs3[0] = sregs[0] >> u;
    sregs3[1] = sregs[1] >> u;
    sregs3[2] = sregs[2] >> u;
    sregs3[3] = sregs[3] >> u;
    sregs3[4] = sregs[4] >> u;
    sregs3[5] = sregs[5] >> u;
    sregs3[6] = sregs[6] >> u;
    sregs3[7] = sregs[7] >> u;

    sregs4[0] = sregs[0] & mod_mask;
    sregs4[1] = sregs[1] & mod_mask;
    sregs4[2] = sregs[2] & mod_mask;
    sregs4[3] = sregs[3] & mod_mask;
    sregs4[4] = sregs[4] & mod_mask;
    sregs4[5] = sregs[5] & mod_mask;
    sregs4[6] = sregs[6] & mod_mask;
    sregs4[7] = sregs[7] & mod_mask;

    if (i == 31) {
      sretail[0] = sregs3[6] + sregs4[7];

      sretail[1] = sregs3[7];
    }

    snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
    snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
    snew_regs3[2] = sregs3[0];
    snew_regs3[3] = sregs3[1];
    snew_regs3[4] = sregs3[2];
    snew_regs3[5] = sregs3[3];
    snew_regs3[6] = sregs3[4];
    snew_regs3[7] = sregs3[5];

    snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
    snew_regs4[1] = sregs4[0];
    snew_regs4[2] = sregs4[1];
    snew_regs4[3] = sregs4[2];
    snew_regs4[4] = sregs4[3];
    snew_regs4[5] = sregs4[4];
    snew_regs4[6] = sregs4[5];
    snew_regs4[7] = sregs4[6];

    if (i == 0) {
      ssum[0] = sregs1[0];
      ssum[1] = (sregs1[1] + snew_regs4[1]);
      for (int j = 2; j <= 7; j++) {
        ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
      }
    } else if (i == 31) {
      for (int j = 0; j <= 7; j++) {
        ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
      }

      scarry = ssum[7] >> u;

    } else {
      for (int j = 0; j <= 7; j++) {
        ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
      }
    }

    uint64_t stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

    if (i == 0) {
      sprev_sum[0] = 0;  // 线程0 显式置0，忽略 shuffle 的结果
      for (int j = 1; j <= 7; j++) {
        sprev_sum[j] = ssum[j - 1] >> u;
      }
    } else {
      sprev_sum[0] = stemp_shuffled;  // 线程1-31 使用 shuffle 的结果
      for (int j = 1; j <= 7; j++) {
        sprev_sum[j] = ssum[j - 1] >> u;
      }
    }

    stail[0] = (ssum[0] & mod_mask) + sprev_sum[0];
    stail[1] = (ssum[1] & mod_mask) + sprev_sum[1];
    stail[2] = (ssum[2] & mod_mask) + sprev_sum[2];
    stail[3] = (ssum[3] & mod_mask) + sprev_sum[3];
    stail[4] = (ssum[4] & mod_mask) + sprev_sum[4];
    stail[5] = (ssum[5] & mod_mask) + sprev_sum[5];
    stail[6] = (ssum[6] & mod_mask) + sprev_sum[6];
    stail[7] = (ssum[7] & mod_mask) + sprev_sum[7];

    for (int j = 0; j <= 6; j++) {
      if (stail[j] == 131072) {
        stail[j] = 0;
        stail[j + 1] += 1;
      }
    }
    scarry_32[i] = stail[7] >> u;
    stail[7] = (stail[7] == 131072) ? 0 : (stail[7] & mod_mask);

    __syncwarp();

    if (i == 0) {
      ssum_carry_32 = 0;
      for (int j = 0; j < 31; j++) {
        ssum_carry_32 += scarry_32[j];
      }
    }
    /*
    while(ssum_carry_32!=0)
    {

        stail[0]=(i==0)?stail[0]:(stail[0]+scarry_32[i-1]);
        for(int j=0;j<=6;j++)
        {
            if(stail[j]==131072)
            {
                stail[j]=0;
                stail[j+1]+=1;
            }
        }
        scarry_32[i]=stail[7]>>u;
        stail[7]=(stail[7]==131072)?0:(stail[7]&mod_mask);

        if(i==0)
        {
            ssum_carry_32=0;
            for(int j=0;j<31;j++)
            {
                ssum_carry_32+=scarry_32[j];
            }
            printf("sum32whilegx!!!!!!!!:%llu ",ssum_carry_32);
        }
    }
    */
    if (ssum_carry_32 != 0) {
      for (int j = 0; j < 8; j++) {
        sdata_tail[8 * i + j] = stail[j];
      }
      __syncwarp();
      if (i == 0) {
        for (int j = 1; j <= 254; j++) {
          if (sdata_tail[j] == 131072) {
            sdata_tail[j + 1] += 1;
          }
        }
        if (sdata_tail[255] == 131072) {
          sdata_tail[255] = 0;
        }
      }
      for (int j = 0; j < 8; j++) {
        stail[j] = sdata_tail[8 * i + j];
      }
    }

    if (i == 0) {
      int64_t negcarry = 0;

      int64_t flag = stail[0] - sretail[0] - scarry;

      int64_t sum = (flag < 0) ? (flag + (1 << u)) : flag;

      negcarry = flag >> u;

      stail[0] = sum % (1 << u);

      flag = stail[1] - sretail[1] + negcarry;
      sum = (flag < 0) ? (flag + (1 << u)) : flag;
      negcarry = flag >> u;

      stail[1] = sum % (1 << u);

      stail[2] = (negcarry != 0) ? (stail[2] - 1) : stail[2];
    }

    uint64_t maxNum = (1 << u) - 1;
    if (i == 0) {
      stail[0] = maxNum + 2 - stail[0];
      stail[1] = maxNum - stail[1];
      stail[2] = maxNum - stail[2];
      stail[3] = maxNum - stail[3];
      stail[4] = maxNum - stail[4];
      stail[5] = maxNum - stail[5];
      stail[6] = maxNum - stail[6];
      stail[7] = maxNum - stail[7];
    } else {
      stail[0] = maxNum - stail[0];
      stail[1] = maxNum - stail[1];
      stail[2] = maxNum - stail[2];
      stail[3] = maxNum - stail[3];
      stail[4] = maxNum - stail[4];
      stail[5] = maxNum - stail[5];
      stail[6] = maxNum - stail[6];
      stail[7] = maxNum - stail[7];
    }

    uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
    if (i == 31) {
      DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[7] = 0;
    } else {
      DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
      DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
    }

    stail[0] = (stail[0] / 2) + DivMod[0];
    stail[1] = (stail[1] / 2) + DivMod[1];
    stail[2] = (stail[2] / 2) + DivMod[2];
    stail[3] = (stail[3] / 2) + DivMod[3];
    stail[4] = (stail[4] / 2) + DivMod[4];
    stail[5] = (stail[5] / 2) + DivMod[5];
    stail[6] = (stail[6] / 2) + DivMod[6];
    stail[7] = (stail[7] / 2) + DivMod[7];

    inout[8 * i] = static_cast<uint64_t>(stail[0]);
    inout[8 * i + 1] = static_cast<uint64_t>(stail[1]);
    inout[8 * i + 2] = static_cast<uint64_t>(stail[2]);
    inout[8 * i + 3] = static_cast<uint64_t>(stail[3]);
    inout[8 * i + 4] = static_cast<uint64_t>(stail[4]);
    inout[8 * i + 5] = static_cast<uint64_t>(stail[5]);
    inout[8 * i + 6] = static_cast<uint64_t>(stail[6]);
    inout[8 * i + 7] = static_cast<uint64_t>(stail[7]);
  }
}

// 【新增配置】每个 Block 允许的最大 Warp 数量 (m)。
// 如果你每次调用是 128 线程 (m=4)，可以把这里改为
// 4，会极大节省编译期的共享内存分配！
#define MAX_WARPS 16

__global__ void XYfixWarpVector(
    uint64_t *inout, uint64_t *inoutA, uint64_t *negmodn,
    uint64_t *negmodn_shoup, uint64_t *modn, uint64_t *modn_shoup, uint64_t n,
    uint64_t mod, const __restrict__ uint64_t *twiddle,
    const __restrict__ uint64_t *twiddle_shoup,
    const __restrict__ uint64_t *ICTTwiddle,
    const __restrict__ uint64_t *ICTTwiddle_shoup,
    const __restrict__ uint64_t *NCTtwiddle,
    const __restrict__ uint64_t *NCTtwiddle_shoup,
    const __restrict__ uint64_t *InvNCTtwiddle,
    const __restrict__ uint64_t *InvNCTtwiddle_shoup,
    const __restrict__ uint64_t inv, const __restrict__ uint64_t inv_shoup,
    const __restrict__ uint64_t *sample) {
  uint64_t i = blockIdx.x * blockDim.x + threadIdx.x;
  uint32_t lane_id = threadIdx.x & 0x1F;
  // uint32_t warp_id = threadIdx.x >> 5; // 优化后已不再需要 shared
  // memory，因此 warp_id 可以省略

  register uint64_t CTinout[8];
  register uint64_t CTinoutA[8];
  register uint64_t NCTinout[8];
  register uint64_t NCTinoutA[8];
  register uint64_t regs[8];
  register uint64_t new_regs[8];

  register uint64_t C;
  register uint32_t omegnIdx[8];

  // 优化：提前声明并行进位需要的寄存器变量
  uint64_t retail_0, retail_1, carry_wrap, temp_shuffled;
  uint64_t lc;
  // uint64_t warp_c, incoming_c;
  int64_t sretail_0, sretail_1, scarry_wrap, stemp_shuffled;
  int64_t slc;

  // ================== 1. CT inout fix vector ==================
  regs[0] = inout[8 * i];
  regs[1] = inout[8 * i + 1];
  regs[2] = inout[8 * i + 2];
  regs[3] = inout[8 * i + 3];
  regs[4] = inout[8 * i + 4];
  regs[5] = inout[8 * i + 5];
  regs[6] = inout[8 * i + 6];
  regs[7] = inout[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  CTinout[0] = regs[0];
  CTinout[1] = regs[1];
  CTinout[2] = regs[2];
  CTinout[3] = regs[3];
  CTinout[4] = regs[4];
  CTinout[5] = regs[5];
  CTinout[6] = regs[6];
  CTinout[7] = regs[7];

  // ================== 2. CT y fix vector ==================
  regs[0] = inoutA[8 * i];
  regs[1] = inoutA[8 * i + 1];
  regs[2] = inoutA[8 * i + 2];
  regs[3] = inoutA[8 * i + 3];
  regs[4] = inoutA[8 * i + 4];
  regs[5] = inoutA[8 * i + 5];
  regs[6] = inoutA[8 * i + 6];
  regs[7] = inoutA[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  CTinoutA[0] = regs[0];
  CTinoutA[1] = regs[1];
  CTinoutA[2] = regs[2];
  CTinoutA[3] = regs[3];
  CTinoutA[4] = regs[4];
  CTinoutA[5] = regs[5];
  CTinoutA[6] = regs[6];
  CTinoutA[7] = regs[7];

  // ================== 3. x*negmodn fix vector ==================
  register uint64_t Aa1[8];

  for (int j = 0; j < 8; j++) {
    Aa1[j] =
        multiply_and_reduce_shoup_lazy(CTinout[j], negmodn[8 * lane_id + j],
                                       negmodn_shoup[8 * lane_id + j], mod);
  }

  // ================== 4. ict Aa1 fix vector ==================
  regs[0] = Aa1[0];
  regs[1] = Aa1[1];
  regs[2] = Aa1[2];
  regs[3] = Aa1[3];
  regs[4] = Aa1[4];
  regs[5] = Aa1[5];
  regs[6] = Aa1[6];
  regs[7] = Aa1[7];

  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);

  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);

  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);

  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  uint64_t pairsInGroup = 1 << (7);
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
  omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
  omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
  omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
  omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
  omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
  omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
  omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                 mod);
    regs[j] = C ? r : l;
  }

  for (int j = 0; j < 8; j++) {
    Aa1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);
  }

  // ================== 5. OPTIMIZED modr Aa1 fix vector ==================
  int u = 17;
  const uint64_t mod_mask = (1ULL << u) - 1;
  register uint64_t regs0[8], regs1[8], regs3[8], regs4[8];
  register uint64_t new_regs3[8], new_regs4[8];
  register uint64_t sum[8], prev_sum[8], tail[8];

  regs0[0] = Aa1[0] >> u;
  regs0[1] = Aa1[1] >> u;
  regs0[2] = Aa1[2] >> u;
  regs0[3] = Aa1[3] >> u;
  regs0[4] = Aa1[4] >> u;
  regs0[5] = Aa1[5] >> u;
  regs0[6] = Aa1[6] >> u;
  regs0[7] = Aa1[7] >> u;

  regs1[0] = Aa1[0] & mod_mask;
  regs1[1] = Aa1[1] & mod_mask;
  regs1[2] = Aa1[2] & mod_mask;
  regs1[3] = Aa1[3] & mod_mask;
  regs1[4] = Aa1[4] & mod_mask;
  regs1[5] = Aa1[5] & mod_mask;
  regs1[6] = Aa1[6] & mod_mask;
  regs1[7] = Aa1[7] & mod_mask;

  regs3[0] = regs0[0] >> u;
  regs3[1] = regs0[1] >> u;
  regs3[2] = regs0[2] >> u;
  regs3[3] = regs0[3] >> u;
  regs3[4] = regs0[4] >> u;
  regs3[5] = regs0[5] >> u;
  regs3[6] = regs0[6] >> u;
  regs3[7] = regs0[7] >> u;

  regs4[0] = regs0[0] & mod_mask;
  regs4[1] = regs0[1] & mod_mask;
  regs4[2] = regs0[2] & mod_mask;
  regs4[3] = regs0[3] & mod_mask;
  regs4[4] = regs0[4] & mod_mask;
  regs4[5] = regs0[5] & mod_mask;
  regs4[6] = regs0[6] & mod_mask;
  regs4[7] = regs0[7] & mod_mask;

  // 优化核心：使用 Shuffle 代替 Shared Memory 来传播 retail 溢出
  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);

  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];

  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = (regs1[1] + new_regs4[1]);
    for (int j = 2; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  // 取代 carry[warp_id]
  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);

  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] = (sum[j] & mod_mask) + prev_sum[j];
  }

  // ----------------------------------------------------
  // 第一阶段：寄存器内部本地进位 (消除 Shared Memory 循环)
  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }

  // 【修复】捕获第一波从最高位（index 255）掉落的进位
  uint64_t stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  // 第二阶段：Warp 级并行前缀和 (Scan) 获取累计进位
  warp_c = lc;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) {
      uint64_t t = __shfl_up_sync(0xffffffff, warp_c, offset);
      if (lane_id >= offset) warp_c += t;
  }

  // 传递累计进位给下一个线程
  incoming_c = __shfl_up_sync(0xffffffff, warp_c, 1);
  if (lane_id == 0) incoming_c = 0;

  tail[0] += incoming_c;

  // 第三阶段：最终本地进位修正
  lc = 0;
  #pragma unroll
  for(int j=0; j<8; j++) {
      tail[j] += lc;
      lc = tail[j] >> u;
      tail[j] &= mod_mask;
  }

  // 【修复】捕获第三阶段从最高位（index 255）再次掉落的进位
  uint64_t stage3_carry = __shfl_sync(0xffffffff, lc, 31);
  */
  uint64_t accumulated_wrap = 0;

  uint32_t active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  uint64_t final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  // 第四阶段：Lane 0 单独处理边界回卷
  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;

    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;

    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;

    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  // ----------------------------------------------------

  // ================== 6. ct Aa1 fix vector ==================
  regs[0] = tail[0];
  regs[1] = tail[1];
  regs[2] = tail[2];
  regs[3] = tail[3];
  regs[4] = tail[4];
  regs[5] = tail[5];
  regs[6] = tail[6];
  regs[7] = tail[7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  // ================== 7. ct(Aa1)*Rone fix vector ==================
  register uint64_t Mm1[8];
  for (int j = 0; j < 8; j++) {
    Mm1[j] =
        multiply_and_reduce_shoup_lazy_dotproduct(regs[j], CTinoutA[j], mod);
  }

  // ================== 8. ict Mm1 fix ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];

  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);

  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);

  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);

  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  pairsInGroup = 1 << (7);
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
  omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
  omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
  omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
  omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
  omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
  omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
  omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                 mod);
    regs[j] = C ? r : l;
  }

  for (int j = 0; j < 8; j++) {
    Mm1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);
  }

  // ================== 9. OPTIMIZED modr Mm1 fix vector ==================
  regs0[0] = Mm1[0] >> u;
  regs0[1] = Mm1[1] >> u;
  regs0[2] = Mm1[2] >> u;
  regs0[3] = Mm1[3] >> u;
  regs0[4] = Mm1[4] >> u;
  regs0[5] = Mm1[5] >> u;
  regs0[6] = Mm1[6] >> u;
  regs0[7] = Mm1[7] >> u;

  regs1[0] = Mm1[0] & mod_mask;
  regs1[1] = Mm1[1] & mod_mask;
  regs1[2] = Mm1[2] & mod_mask;
  regs1[3] = Mm1[3] & mod_mask;
  regs1[4] = Mm1[4] & mod_mask;
  regs1[5] = Mm1[5] & mod_mask;
  regs1[6] = Mm1[6] & mod_mask;
  regs1[7] = Mm1[7] & mod_mask;

  regs3[0] = regs0[0] >> u;
  regs3[1] = regs0[1] >> u;
  regs3[2] = regs0[2] >> u;
  regs3[3] = regs0[3] >> u;
  regs3[4] = regs0[4] >> u;
  regs3[5] = regs0[5] >> u;
  regs3[6] = regs0[6] >> u;
  regs3[7] = regs0[7] >> u;

  regs4[0] = regs0[0] & mod_mask;
  regs4[1] = regs0[1] & mod_mask;
  regs4[2] = regs0[2] & mod_mask;
  regs4[3] = regs0[3] & mod_mask;
  regs4[4] = regs0[4] & mod_mask;
  regs4[5] = regs0[5] & mod_mask;
  regs4[6] = regs0[6] & mod_mask;
  regs4[7] = regs0[7] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);

  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];

  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = (regs1[1] + new_regs4[1]);
    for (int j = 2; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);

  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] = (sum[j] & mod_mask) + prev_sum[j];
  }

  // ----------------------------------------------------
  // 第一阶段：寄存器内部本地进位 (消除 Shared Memory 循环)
  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }

  // 【修复】捕获第一波从最高位（index 255）掉落的进位
  stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  // 第二阶段：Warp 级并行前缀和 (Scan) 获取累计进位
  warp_c = lc;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) {
      uint64_t t = __shfl_up_sync(0xffffffff, warp_c, offset);
      if (lane_id >= offset) warp_c += t;
  }

  // 传递累计进位给下一个线程
  incoming_c = __shfl_up_sync(0xffffffff, warp_c, 1);
  if (lane_id == 0) incoming_c = 0;

  tail[0] += incoming_c;

  // 第三阶段：最终本地进位修正
  lc = 0;
  #pragma unroll
  for(int j=0; j<8; j++) {
      tail[j] += lc;
      lc = tail[j] >> u;
      tail[j] &= mod_mask;
  }

  // 【修复】捕获第三阶段从最高位（index 255）再次掉落的进位
  stage3_carry = __shfl_sync(0xffffffff, lc, 31);
  */
  accumulated_wrap = 0;

  active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  // 第四阶段：Lane 0 单独处理边界回卷
  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;

    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;

    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;

    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  // ----------------------------------------------------

  Mm1[0] = tail[0];
  Mm1[1] = tail[1];
  Mm1[2] = tail[2];
  Mm1[3] = tail[3];
  Mm1[4] = tail[4];
  Mm1[5] = tail[5];
  Mm1[6] = tail[6];
  Mm1[7] = tail[7];

  // ================== 10. nct x fix vector ==================
  regs[0] = inout[8 * i];
  regs[1] = inout[8 * i + 1];
  regs[2] = inout[8 * i + 2];
  regs[3] = inout[8 * i + 3];
  regs[4] = inout[8 * i + 4];
  regs[5] = inout[8 * i + 5];
  regs[6] = inout[8 * i + 6];
  regs[7] = inout[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  NCTinout[0] = regs[0];
  NCTinout[1] = regs[1];
  NCTinout[2] = regs[2];
  NCTinout[3] = regs[3];
  NCTinout[4] = regs[4];
  NCTinout[5] = regs[5];
  NCTinout[6] = regs[6];
  NCTinout[7] = regs[7];

  // ================== 11. nct mm1 fix vector ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  Mm1[0] = regs[0];
  Mm1[1] = regs[1];
  Mm1[2] = regs[2];
  Mm1[3] = regs[3];
  Mm1[4] = regs[4];
  Mm1[5] = regs[5];
  Mm1[6] = regs[6];
  Mm1[7] = regs[7];

  // ================== 12. nct y fix vector ==================
  regs[0] = inoutA[8 * i];
  regs[1] = inoutA[8 * i + 1];
  regs[2] = inoutA[8 * i + 2];
  regs[3] = inoutA[8 * i + 3];
  regs[4] = inoutA[8 * i + 4];
  regs[5] = inoutA[8 * i + 5];
  regs[6] = inoutA[8 * i + 6];
  regs[7] = inoutA[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  NCTinoutA[0] = regs[0];
  NCTinoutA[1] = regs[1];
  NCTinoutA[2] = regs[2];
  NCTinoutA[3] = regs[3];
  NCTinoutA[4] = regs[4];
  NCTinoutA[5] = regs[5];
  NCTinoutA[6] = regs[6];
  NCTinoutA[7] = regs[7];

  // ================== 13. g1+g2xandy ==================
  register uint64_t Gx[8];
  for (int j = 0; j < 8; j++) {
    uint64_t tmp1 = multiply_and_reduce_shoup_lazy_dotproduct(NCTinoutA[j],
                                                              NCTinout[j], mod);
    uint64_t tmp2 = multiply_and_reduce_shoup_lazy(
        Mm1[j], modn[8 * lane_id + j], modn_shoup[8 * lane_id + j], mod);
    Gx[j] = (tmp1 + tmp2) % MOD;
  }

  // ================== 14. inct gx fix vector ==================
  regs[0] = Gx[0];
  regs[1] = Gx[1];
  regs[2] = Gx[2];
  regs[3] = Gx[3];
  regs[4] = Gx[4];
  regs[5] = Gx[5];
  regs[6] = Gx[6];
  regs[7] = Gx[7];

  gs_butterfly(regs[0], regs[1], InvNCTtwiddle[128 + (4 * (lane_id))],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  gs_butterfly(regs[2], regs[3], InvNCTtwiddle[128 + (4 * (lane_id)) + 1],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  gs_butterfly(regs[4], regs[5], InvNCTtwiddle[128 + (4 * (lane_id)) + 2],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  gs_butterfly(regs[6], regs[7], InvNCTtwiddle[128 + (4 * (lane_id)) + 3],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  gs_butterfly(regs[0], regs[2], InvNCTtwiddle[64 + ((lane_id) * 2)],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  gs_butterfly(regs[1], regs[3], InvNCTtwiddle[64 + ((lane_id) * 2)],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  gs_butterfly(regs[4], regs[6], InvNCTtwiddle[64 + ((lane_id) * 2) + 1],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  gs_butterfly(regs[5], regs[7], InvNCTtwiddle[64 + ((lane_id) * 2) + 1],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  gs_butterfly(regs[0], regs[4], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[1], regs[5], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[2], regs[6], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[3], regs[7], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = ((8 * lane_id) & 0xFF) / pair2 + numOfGroups;
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  uint64_t pairsInGroup_inv = 1 << 7;
  uint64_t pair2_inv = pairsInGroup_inv << 1;
  uint64_t numOfGroups_inv = 128 / pairsInGroup_inv;
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = ((8 * lane_id) & 0xFF) / pair2_inv + numOfGroups_inv;
  omegnIdx[1] = numOfGroups_inv + (((8 * lane_id + 1) & 0xFF) / pair2_inv);
  omegnIdx[2] = numOfGroups_inv + (((8 * lane_id + 2) & 0xFF) / pair2_inv);
  omegnIdx[3] = numOfGroups_inv + (((8 * lane_id + 3) & 0xFF) / pair2_inv);
  omegnIdx[4] = numOfGroups_inv + (((8 * lane_id + 4) & 0xFF) / pair2_inv);
  omegnIdx[5] = numOfGroups_inv + (((8 * lane_id + 5) & 0xFF) / pair2_inv);
  omegnIdx[6] = numOfGroups_inv + (((8 * lane_id + 6) & 0xFF) / pair2_inv);
  omegnIdx[7] = numOfGroups_inv + (((8 * lane_id + 7) & 0xFF) / pair2_inv);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                 InvNCTtwiddle_shoup[omegnIdx[j]], mod);
    regs[j] = C ? r : l;
  }
  Gx[0] = multiply_and_reduce_shoup_lazy(regs[0], inv, inv_shoup, mod);
  Gx[1] = multiply_and_reduce_shoup_lazy(regs[1], inv, inv_shoup, mod);
  Gx[2] = multiply_and_reduce_shoup_lazy(regs[2], inv, inv_shoup, mod);
  Gx[3] = multiply_and_reduce_shoup_lazy(regs[3], inv, inv_shoup, mod);
  Gx[4] = multiply_and_reduce_shoup_lazy(regs[4], inv, inv_shoup, mod);
  Gx[5] = multiply_and_reduce_shoup_lazy(regs[5], inv, inv_shoup, mod);
  Gx[6] = multiply_and_reduce_shoup_lazy(regs[6], inv, inv_shoup, mod);
  Gx[7] = multiply_and_reduce_shoup_lazy(regs[7], inv, inv_shoup, mod);

  // ================== 15. OPTIMIZED modh Gx fix vector (Warp Shuffle
  // 并行带符号修正) ==================

  register int64_t sregs0[8], sregs[8], sregs1[8], sregs3[8], sregs4[8];
  register int64_t snew_regs3[8], snew_regs4[8];
  register int64_t ssum[8], sprev_sum[8], stail[8];
  register uint64_t DivMod[8];

  // 1. 获取带符号的初始值
  sregs0[0] = (Gx[0] > sample[8 * lane_id])
                  ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[0]);
  sregs0[1] = (Gx[1] > sample[(8 * lane_id + 1) & 0xFF])
                  ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[1]);
  sregs0[2] = (Gx[2] > sample[(8 * lane_id + 2) & 0xFF])
                  ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[2]);
  sregs0[3] = (Gx[3] > sample[(8 * lane_id + 3) & 0xFF])
                  ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[3]);
  sregs0[4] = (Gx[4] > sample[(8 * lane_id + 4) & 0xFF])
                  ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[4]);
  sregs0[5] = (Gx[5] > sample[(8 * lane_id + 5) & 0xFF])
                  ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[5]);
  sregs0[6] = (Gx[6] > sample[(8 * lane_id + 6) & 0xFF])
                  ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[6]);
  sregs0[7] = (Gx[7] > sample[(8 * lane_id + 7) & 0xFF])
                  ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[7]);

// 利用算术右移自动保留符号位
#pragma unroll
  for (int j = 0; j < 8; j++) {
    sregs[j] = sregs0[j] >> u;
    sregs1[j] = sregs0[j] & mod_mask;
    sregs3[j] = sregs[j] >> u;
    sregs4[j] = sregs[j] & mod_mask;
  }

  sretail_0 = __shfl_sync(0xffffffff, sregs3[6] + sregs4[7], 31);
  sretail_1 = __shfl_sync(0xffffffff, sregs3[7], 31);

  snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
  snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
  snew_regs3[2] = sregs3[0];
  snew_regs3[3] = sregs3[1];
  snew_regs3[4] = sregs3[2];
  snew_regs3[5] = sregs3[3];
  snew_regs3[6] = sregs3[4];
  snew_regs3[7] = sregs3[5];

  snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
  snew_regs4[1] = sregs4[0];
  snew_regs4[2] = sregs4[1];
  snew_regs4[3] = sregs4[2];
  snew_regs4[4] = sregs4[3];
  snew_regs4[5] = sregs4[4];
  snew_regs4[6] = sregs4[5];
  snew_regs4[7] = sregs4[6];

  if (lane_id == 0) {
    ssum[0] = sregs1[0];
    ssum[1] = (sregs1[1] + snew_regs4[1]);
    for (int j = 2; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  }

  scarry_wrap = __shfl_sync(0xffffffff, ssum[7] >> u, 31);
  stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

  if (lane_id == 0) {
    sprev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  } else {
    sprev_sum[0] = stemp_shuffled;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] = (ssum[j] & mod_mask) + sprev_sum[j];
  }

  // =========================================================================
  // ★ 核心修复：Stage 1 & 2 使用 Ballot While 循环涟漪进位，替代错误的前缀和
  // =========================================================================
  slc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] += slc;
    slc = stail[j] >> u;
    stail[j] &= mod_mask;
  }

  int64_t accumulated_lane31_carry =
      0;  // 专门捕捉所有从最高位（lane 31）溢出的最终进位/借位
  active = __ballot_sync(0xffffffff, slc != 0);

  // 只要有任何一个线程还有进位/借位没消化，整个 Warp 就继续同步传递
  while (active != 0) {
    if (lane_id == 31) {
      accumulated_lane31_carry += slc;
    }

    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;  // 最低位暂时不回卷

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;  // 算术右移完美处理负数借位
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // 获取从最高位最终溢出/借位的所有总量
  int64_t final_carry = __shfl_sync(0xffffffff, accumulated_lane31_carry, 31);

  // =========================================================================
  // ★ 核心修复：Stage 3 (Mod H 负向回卷)
  // =========================================================================
  slc = 0;
  if (lane_id == 0) {
    // 对于模 h (2^4352 + 1)，最高位的进位溢出权重大于 0，等价于从最低位减去。
    // 总溢出 = sretail_0 + scarry_wrap + final_carry
    int64_t total_wrap_0 = sretail_0 + scarry_wrap + final_carry;

    int64_t flag = stail[0] - total_wrap_0;
    int64_t negcarry = flag >> u;
    stail[0] = flag & mod_mask;

    flag = stail[1] - sretail_1 + negcarry;
    negcarry = flag >> u;
    stail[1] = flag & mod_mask;

    // 让借位顺着 lane_id 0 往上走，走到没有为止
    for (int j = 2; j < 8; j++) {
      flag = stail[j] + negcarry;
      negcarry = flag >> u;
      stail[j] = flag & mod_mask;
    }

    slc = negcarry;  // 如果 lane 0 扣完 8 个元素后还欠借位，扔给后面的线程
  }

  // 再次开启涟漪循环，彻底消化回卷带来的多米诺借位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }
  /*
  for(int _j = 0; _j < 8; _j++)
      printf("gxmodh|%03d|%llu ", 8*lane_id+_j, (unsigned long long)stail[_j]);
  printf("\n");
  __syncwarp();
  */
  // =========================================================================
  // Stage 4: 计算最终的 w = (h - g) / 2
  // =========================================================================
  uint64_t maxNum = (1ULL << u) - 1;
  if (lane_id == 0) {
    // 这一步等价于取补码 + 2
    stail[0] = maxNum + 2 - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  } else {
    stail[0] = maxNum - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  }

  // ★ 修复漏洞：maxNum+2-stail[0] 如果 stail[0] 极小，会导致超过 17
  // 位限制产生进位
  slc = 0;
  if (lane_id == 0) {
    for (int j = 0; j < 8; j++) {
      stail[j] += slc;
      slc = stail[j] >> u;
      stail[j] &= mod_mask;
    }
  }
  // 传播这最后一丝极小的正向进位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;
    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
  if (lane_id == 31) {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = 0;
  } else {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
  }

  stail[0] = (stail[0] / 2) + DivMod[0];
  stail[1] = (stail[1] / 2) + DivMod[1];
  stail[2] = (stail[2] / 2) + DivMod[2];
  stail[3] = (stail[3] / 2) + DivMod[3];
  stail[4] = (stail[4] / 2) + DivMod[4];
  stail[5] = (stail[5] / 2) + DivMod[5];
  stail[6] = (stail[6] / 2) + DivMod[6];
  stail[7] = (stail[7] / 2) + DivMod[7];

  // 最后写回外层大数组，使用全局索引 i
  inout[8 * i] = static_cast<uint64_t>(stail[0]);
  inout[8 * i + 1] = static_cast<uint64_t>(stail[1]);
  inout[8 * i + 2] = static_cast<uint64_t>(stail[2]);
  inout[8 * i + 3] = static_cast<uint64_t>(stail[3]);
  inout[8 * i + 4] = static_cast<uint64_t>(stail[4]);
  inout[8 * i + 5] = static_cast<uint64_t>(stail[5]);
  inout[8 * i + 6] = static_cast<uint64_t>(stail[6]);
  inout[8 * i + 7] = static_cast<uint64_t>(stail[7]);
}

__global__ void XYfixWarpROneVector(
    uint64_t *inout, uint64_t *inoutAct, uint64_t *inoutAnct, uint64_t *negmodn,
    uint64_t *negmodn_shoup, uint64_t *modn, uint64_t *modn_shoup, uint64_t n,
    uint64_t mod, const __restrict__ uint64_t *twiddle,
    const __restrict__ uint64_t *twiddle_shoup,
    const __restrict__ uint64_t *ICTTwiddle,
    const __restrict__ uint64_t *ICTTwiddle_shoup,
    const __restrict__ uint64_t *NCTtwiddle,
    const __restrict__ uint64_t *NCTtwiddle_shoup,
    const __restrict__ uint64_t *InvNCTtwiddle,
    const __restrict__ uint64_t *InvNCTtwiddle_shoup,
    const __restrict__ uint64_t inv, const __restrict__ uint64_t inv_shoup,
    const __restrict__ uint64_t *sample) {
  uint64_t i = blockIdx.x * blockDim.x + threadIdx.x;
  uint32_t lane_id = threadIdx.x & 0x1F;
  // uint32_t warp_id = threadIdx.x >> 5; // 优化后已不再需要 shared
  // memory，因此 warp_id 可以省略

  register uint64_t CTinout[8];
  register uint64_t CTinoutA[8];
  register uint64_t NCTinout[8];
  register uint64_t NCTinoutA[8];
  register uint64_t regs[8];
  register uint64_t new_regs[8];

  register uint64_t C;
  register uint32_t omegnIdx[8];

  // 优化：提前声明并行进位需要的寄存器变量
  uint64_t retail_0, retail_1, carry_wrap, temp_shuffled;
  // uint64_t lc, warp_c, incoming_c;
  uint64_t lc;
  int64_t sretail_0, sretail_1, scarry_wrap, stemp_shuffled;
  int64_t slc;

  // ================== 1. CT inout fix vector ==================
  regs[0] = inout[8 * i];
  regs[1] = inout[8 * i + 1];
  regs[2] = inout[8 * i + 2];
  regs[3] = inout[8 * i + 3];
  regs[4] = inout[8 * i + 4];
  regs[5] = inout[8 * i + 5];
  regs[6] = inout[8 * i + 6];
  regs[7] = inout[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  CTinout[0] = regs[0];
  CTinout[1] = regs[1];
  CTinout[2] = regs[2];
  CTinout[3] = regs[3];
  CTinout[4] = regs[4];
  CTinout[5] = regs[5];
  CTinout[6] = regs[6];
  CTinout[7] = regs[7];

  // ================== 2. ctRone=ctinoutA ==================
  CTinoutA[0] = inoutAct[8 * lane_id + 0];
  CTinoutA[1] = inoutAct[8 * lane_id + 1];
  CTinoutA[2] = inoutAct[8 * lane_id + 2];
  CTinoutA[3] = inoutAct[8 * lane_id + 3];
  CTinoutA[4] = inoutAct[8 * lane_id + 4];
  CTinoutA[5] = inoutAct[8 * lane_id + 5];
  CTinoutA[6] = inoutAct[8 * lane_id + 6];
  CTinoutA[7] = inoutAct[8 * lane_id + 7];

  // ================== 3. x*negmodn fix vector ==================
  register uint64_t Aa1[8];

  for (int j = 0; j < 8; j++) {
    Aa1[j] =
        multiply_and_reduce_shoup_lazy(CTinout[j], negmodn[8 * lane_id + j],
                                       negmodn_shoup[8 * lane_id + j], mod);
  }

  // ================== 4. ict Aa1 fix vector ==================
  regs[0] = Aa1[0];
  regs[1] = Aa1[1];
  regs[2] = Aa1[2];
  regs[3] = Aa1[3];
  regs[4] = Aa1[4];
  regs[5] = Aa1[5];
  regs[6] = Aa1[6];
  regs[7] = Aa1[7];

  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);

  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);

  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);

  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  uint64_t pairsInGroup = 1 << (7);
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
  omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
  omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
  omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
  omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
  omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
  omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
  omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                 mod);
    regs[j] = C ? r : l;
  }

  for (int j = 0; j < 8; j++) {
    Aa1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);
  }

  // ================== 5. OPTIMIZED modr Aa1 fix vector ==================
  int u = 17;
  const uint64_t mod_mask = (1ULL << u) - 1;
  register uint64_t regs0[8], regs1[8], regs3[8], regs4[8];
  register uint64_t new_regs3[8], new_regs4[8];
  register uint64_t sum[8], prev_sum[8], tail[8];

  regs0[0] = Aa1[0] >> u;
  regs0[1] = Aa1[1] >> u;
  regs0[2] = Aa1[2] >> u;
  regs0[3] = Aa1[3] >> u;
  regs0[4] = Aa1[4] >> u;
  regs0[5] = Aa1[5] >> u;
  regs0[6] = Aa1[6] >> u;
  regs0[7] = Aa1[7] >> u;

  regs1[0] = Aa1[0] & mod_mask;
  regs1[1] = Aa1[1] & mod_mask;
  regs1[2] = Aa1[2] & mod_mask;
  regs1[3] = Aa1[3] & mod_mask;
  regs1[4] = Aa1[4] & mod_mask;
  regs1[5] = Aa1[5] & mod_mask;
  regs1[6] = Aa1[6] & mod_mask;
  regs1[7] = Aa1[7] & mod_mask;

  regs3[0] = regs0[0] >> u;
  regs3[1] = regs0[1] >> u;
  regs3[2] = regs0[2] >> u;
  regs3[3] = regs0[3] >> u;
  regs3[4] = regs0[4] >> u;
  regs3[5] = regs0[5] >> u;
  regs3[6] = regs0[6] >> u;
  regs3[7] = regs0[7] >> u;

  regs4[0] = regs0[0] & mod_mask;
  regs4[1] = regs0[1] & mod_mask;
  regs4[2] = regs0[2] & mod_mask;
  regs4[3] = regs0[3] & mod_mask;
  regs4[4] = regs0[4] & mod_mask;
  regs4[5] = regs0[5] & mod_mask;
  regs4[6] = regs0[6] & mod_mask;
  regs4[7] = regs0[7] & mod_mask;

  // 优化核心：使用 Shuffle 代替 Shared Memory 来传播 retail 溢出
  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);

  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];

  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = (regs1[1] + new_regs4[1]);
    for (int j = 2; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  // 取代 carry[warp_id]
  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);

  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] = (sum[j] & mod_mask) + prev_sum[j];
  }

  // ----------------------------------------------------
  // 第一阶段：寄存器内部本地进位 (消除 Shared Memory 循环)
  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }

  // 【修复】捕获第一波从最高位（index 255）掉落的进位
  uint64_t stage1_carry = __shfl_sync(0xffffffff, lc, 31);

  /*
  // 第二阶段：Warp 级并行前缀和 (Scan) 获取累计进位
  warp_c = lc;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) {
      uint64_t t = __shfl_up_sync(0xffffffff, warp_c, offset);
      if (lane_id >= offset) warp_c += t;
  }

  // 传递累计进位给下一个线程
  incoming_c = __shfl_up_sync(0xffffffff, warp_c, 1);
  if (lane_id == 0) incoming_c = 0;

  tail[0] += incoming_c;

  // 第三阶段：最终本地进位修正
  lc = 0;
  #pragma unroll
  for(int j=0; j<8; j++) {
      tail[j] += lc;
      lc = tail[j] >> u;
      tail[j] &= mod_mask;
  }

  // 【修复】捕获第三阶段从最高位（index 255）再次掉落的进位
  uint64_t stage3_carry = __shfl_sync(0xffffffff, lc, 31);
  */
  uint64_t accumulated_wrap = 0;

  uint32_t active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  uint64_t final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  // 第四阶段：Lane 0 单独处理边界回卷
  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;

    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;

    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;

    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  // ----------------------------------------------------

  // ================== 6. ct Aa1 fix vector ==================
  regs[0] = tail[0];
  regs[1] = tail[1];
  regs[2] = tail[2];
  regs[3] = tail[3];
  regs[4] = tail[4];
  regs[5] = tail[5];
  regs[6] = tail[6];
  regs[7] = tail[7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  // ================== 7. ct(Aa1)*Rone fix vector ==================
  register uint64_t Mm1[8];
  for (int j = 0; j < 8; j++) {
    Mm1[j] =
        multiply_and_reduce_shoup_lazy_dotproduct(regs[j], CTinoutA[j], mod);
  }

  // ================== 8. ict Mm1 fix ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];

  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);

  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);

  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);

  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  pairsInGroup = 1 << (7);
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
  omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
  omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
  omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
  omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
  omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
  omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
  omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                 mod);
    regs[j] = C ? r : l;
  }

  for (int j = 0; j < 8; j++) {
    Mm1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);
  }
  /*
  for(int _j = 0; _j < 8; _j++)
      printf("m|%03d|%llu ", 8*lane_id+_j, (unsigned long long)Mm1[_j]);
  printf("\n");
  __syncwarp();
  */
  // ================== 9. OPTIMIZED modr Mm1 fix vector ==================
  regs0[0] = Mm1[0] >> u;
  regs0[1] = Mm1[1] >> u;
  regs0[2] = Mm1[2] >> u;
  regs0[3] = Mm1[3] >> u;
  regs0[4] = Mm1[4] >> u;
  regs0[5] = Mm1[5] >> u;
  regs0[6] = Mm1[6] >> u;
  regs0[7] = Mm1[7] >> u;

  regs1[0] = Mm1[0] & mod_mask;
  regs1[1] = Mm1[1] & mod_mask;
  regs1[2] = Mm1[2] & mod_mask;
  regs1[3] = Mm1[3] & mod_mask;
  regs1[4] = Mm1[4] & mod_mask;
  regs1[5] = Mm1[5] & mod_mask;
  regs1[6] = Mm1[6] & mod_mask;
  regs1[7] = Mm1[7] & mod_mask;

  regs3[0] = regs0[0] >> u;
  regs3[1] = regs0[1] >> u;
  regs3[2] = regs0[2] >> u;
  regs3[3] = regs0[3] >> u;
  regs3[4] = regs0[4] >> u;
  regs3[5] = regs0[5] >> u;
  regs3[6] = regs0[6] >> u;
  regs3[7] = regs0[7] >> u;

  regs4[0] = regs0[0] & mod_mask;
  regs4[1] = regs0[1] & mod_mask;
  regs4[2] = regs0[2] & mod_mask;
  regs4[3] = regs0[3] & mod_mask;
  regs4[4] = regs0[4] & mod_mask;
  regs4[5] = regs0[5] & mod_mask;
  regs4[6] = regs0[6] & mod_mask;
  regs4[7] = regs0[7] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);

  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];

  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = (regs1[1] + new_regs4[1]);
    for (int j = 2; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);

  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] = (sum[j] & mod_mask) + prev_sum[j];
  }

  // ----------------------------------------------------
  // 第一阶段：寄存器内部本地进位 (消除 Shared Memory 循环)
  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }

  // 【修复】捕获第一波从最高位（index 255）掉落的进位
  stage1_carry = __shfl_sync(0xffffffff, lc, 31);

  /*
  // 第二阶段：Warp 级并行前缀和 (Scan) 获取累计进位
  warp_c = lc;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) {
      uint64_t t = __shfl_up_sync(0xffffffff, warp_c, offset);
      if (lane_id >= offset) warp_c += t;
  }

  // 传递累计进位给下一个线程
  incoming_c = __shfl_up_sync(0xffffffff, warp_c, 1);
  if (lane_id == 0) incoming_c = 0;

  tail[0] += incoming_c;

  // 第三阶段：最终本地进位修正
  lc = 0;
  #pragma unroll
  for(int j=0; j<8; j++) {
      tail[j] += lc;
      lc = tail[j] >> u;
      tail[j] &= mod_mask;
  }

  // 【修复】捕获第三阶段从最高位（index 255）再次掉落的进位
  stage3_carry = __shfl_sync(0xffffffff, lc, 31);
  */
  accumulated_wrap = 0;

  active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  // 第四阶段：Lane 0 单独处理边界回卷
  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;
    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;

    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;

    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  // ----------------------------------------------------

  Mm1[0] = tail[0];
  Mm1[1] = tail[1];
  Mm1[2] = tail[2];
  Mm1[3] = tail[3];
  Mm1[4] = tail[4];
  Mm1[5] = tail[5];
  Mm1[6] = tail[6];
  Mm1[7] = tail[7];
  /*
  for(int _j = 0; _j < 8; _j++)
      printf("mmodr|%03d|%llu ", 8*lane_id+_j, (unsigned long long)Mm1[_j]);
  printf("\n");
  __syncwarp();
  */
  // ================== 10. nct x fix vector ==================
  regs[0] = inout[8 * i];
  regs[1] = inout[8 * i + 1];
  regs[2] = inout[8 * i + 2];
  regs[3] = inout[8 * i + 3];
  regs[4] = inout[8 * i + 4];
  regs[5] = inout[8 * i + 5];
  regs[6] = inout[8 * i + 6];
  regs[7] = inout[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  NCTinout[0] = regs[0];
  NCTinout[1] = regs[1];
  NCTinout[2] = regs[2];
  NCTinout[3] = regs[3];
  NCTinout[4] = regs[4];
  NCTinout[5] = regs[5];
  NCTinout[6] = regs[6];
  NCTinout[7] = regs[7];

  // ================== 11. nct mm1 fix vector ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  Mm1[0] = regs[0];
  Mm1[1] = regs[1];
  Mm1[2] = regs[2];
  Mm1[3] = regs[3];
  Mm1[4] = regs[4];
  Mm1[5] = regs[5];
  Mm1[6] = regs[6];
  Mm1[7] = regs[7];

  // ================== 12. nct y fix vector ==================
  NCTinoutA[0] = inoutAnct[8 * lane_id + 0];
  NCTinoutA[1] = inoutAnct[8 * lane_id + 1];
  NCTinoutA[2] = inoutAnct[8 * lane_id + 2];
  NCTinoutA[3] = inoutAnct[8 * lane_id + 3];
  NCTinoutA[4] = inoutAnct[8 * lane_id + 4];
  NCTinoutA[5] = inoutAnct[8 * lane_id + 5];
  NCTinoutA[6] = inoutAnct[8 * lane_id + 6];
  NCTinoutA[7] = inoutAnct[8 * lane_id + 7];

  // ================== 13. g1+g2xandy ==================
  register uint64_t Gx[8];
  for (int j = 0; j < 8; j++) {
    uint64_t tmp1 = multiply_and_reduce_shoup_lazy_dotproduct(NCTinoutA[j],
                                                              NCTinout[j], mod);
    uint64_t tmp2 = multiply_and_reduce_shoup_lazy(
        Mm1[j], modn[8 * lane_id + j], modn_shoup[8 * lane_id + j], mod);
    Gx[j] = (tmp1 + tmp2) % MOD;
  }

  // ================== 14. inct gx fix vector ==================
  regs[0] = Gx[0];
  regs[1] = Gx[1];
  regs[2] = Gx[2];
  regs[3] = Gx[3];
  regs[4] = Gx[4];
  regs[5] = Gx[5];
  regs[6] = Gx[6];
  regs[7] = Gx[7];

  gs_butterfly(regs[0], regs[1], InvNCTtwiddle[128 + (4 * (lane_id))],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  gs_butterfly(regs[2], regs[3], InvNCTtwiddle[128 + (4 * (lane_id)) + 1],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  gs_butterfly(regs[4], regs[5], InvNCTtwiddle[128 + (4 * (lane_id)) + 2],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  gs_butterfly(regs[6], regs[7], InvNCTtwiddle[128 + (4 * (lane_id)) + 3],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  gs_butterfly(regs[0], regs[2], InvNCTtwiddle[64 + ((lane_id) * 2)],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  gs_butterfly(regs[1], regs[3], InvNCTtwiddle[64 + ((lane_id) * 2)],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  gs_butterfly(regs[4], regs[6], InvNCTtwiddle[64 + ((lane_id) * 2) + 1],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  gs_butterfly(regs[5], regs[7], InvNCTtwiddle[64 + ((lane_id) * 2) + 1],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  gs_butterfly(regs[0], regs[4], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[1], regs[5], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[2], regs[6], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[3], regs[7], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = ((8 * lane_id) & 0xFF) / pair2 + numOfGroups;
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  uint64_t pairsInGroup_inv = 1 << 7;
  uint64_t pair2_inv = pairsInGroup_inv << 1;
  uint64_t numOfGroups_inv = 128 / pairsInGroup_inv;
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = ((8 * lane_id) & 0xFF) / pair2_inv + numOfGroups_inv;
  omegnIdx[1] = numOfGroups_inv + (((8 * lane_id + 1) & 0xFF) / pair2_inv);
  omegnIdx[2] = numOfGroups_inv + (((8 * lane_id + 2) & 0xFF) / pair2_inv);
  omegnIdx[3] = numOfGroups_inv + (((8 * lane_id + 3) & 0xFF) / pair2_inv);
  omegnIdx[4] = numOfGroups_inv + (((8 * lane_id + 4) & 0xFF) / pair2_inv);
  omegnIdx[5] = numOfGroups_inv + (((8 * lane_id + 5) & 0xFF) / pair2_inv);
  omegnIdx[6] = numOfGroups_inv + (((8 * lane_id + 6) & 0xFF) / pair2_inv);
  omegnIdx[7] = numOfGroups_inv + (((8 * lane_id + 7) & 0xFF) / pair2_inv);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                 InvNCTtwiddle_shoup[omegnIdx[j]], mod);
    regs[j] = C ? r : l;
  }
  Gx[0] = multiply_and_reduce_shoup_lazy(regs[0], inv, inv_shoup, mod);
  Gx[1] = multiply_and_reduce_shoup_lazy(regs[1], inv, inv_shoup, mod);
  Gx[2] = multiply_and_reduce_shoup_lazy(regs[2], inv, inv_shoup, mod);
  Gx[3] = multiply_and_reduce_shoup_lazy(regs[3], inv, inv_shoup, mod);
  Gx[4] = multiply_and_reduce_shoup_lazy(regs[4], inv, inv_shoup, mod);
  Gx[5] = multiply_and_reduce_shoup_lazy(regs[5], inv, inv_shoup, mod);
  Gx[6] = multiply_and_reduce_shoup_lazy(regs[6], inv, inv_shoup, mod);
  Gx[7] = multiply_and_reduce_shoup_lazy(regs[7], inv, inv_shoup, mod);

  // ================== 15. OPTIMIZED modh Gx fix vector (Warp Shuffle
  // 并行带符号修正) ==================
  register int64_t sregs0[8], sregs[8], sregs1[8], sregs3[8], sregs4[8];
  register int64_t snew_regs3[8], snew_regs4[8];
  register int64_t ssum[8], sprev_sum[8], stail[8];
  register uint64_t DivMod[8];

  // 1. 获取带符号的初始值
  sregs0[0] = (Gx[0] > sample[8 * lane_id])
                  ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[0]);
  sregs0[1] = (Gx[1] > sample[(8 * lane_id + 1) & 0xFF])
                  ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[1]);
  sregs0[2] = (Gx[2] > sample[(8 * lane_id + 2) & 0xFF])
                  ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[2]);
  sregs0[3] = (Gx[3] > sample[(8 * lane_id + 3) & 0xFF])
                  ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[3]);
  sregs0[4] = (Gx[4] > sample[(8 * lane_id + 4) & 0xFF])
                  ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[4]);
  sregs0[5] = (Gx[5] > sample[(8 * lane_id + 5) & 0xFF])
                  ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[5]);
  sregs0[6] = (Gx[6] > sample[(8 * lane_id + 6) & 0xFF])
                  ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[6]);
  sregs0[7] = (Gx[7] > sample[(8 * lane_id + 7) & 0xFF])
                  ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[7]);

// 利用算术右移自动保留符号位
#pragma unroll
  for (int j = 0; j < 8; j++) {
    sregs[j] = sregs0[j] >> u;
    sregs1[j] = sregs0[j] & mod_mask;
    sregs3[j] = sregs[j] >> u;
    sregs4[j] = sregs[j] & mod_mask;
  }

  sretail_0 = __shfl_sync(0xffffffff, sregs3[6] + sregs4[7], 31);
  sretail_1 = __shfl_sync(0xffffffff, sregs3[7], 31);

  snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
  snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
  snew_regs3[2] = sregs3[0];
  snew_regs3[3] = sregs3[1];
  snew_regs3[4] = sregs3[2];
  snew_regs3[5] = sregs3[3];
  snew_regs3[6] = sregs3[4];
  snew_regs3[7] = sregs3[5];

  snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
  snew_regs4[1] = sregs4[0];
  snew_regs4[2] = sregs4[1];
  snew_regs4[3] = sregs4[2];
  snew_regs4[4] = sregs4[3];
  snew_regs4[5] = sregs4[4];
  snew_regs4[6] = sregs4[5];
  snew_regs4[7] = sregs4[6];

  if (lane_id == 0) {
    ssum[0] = sregs1[0];
    ssum[1] = (sregs1[1] + snew_regs4[1]);
    for (int j = 2; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  }

  scarry_wrap = __shfl_sync(0xffffffff, ssum[7] >> u, 31);
  stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

  if (lane_id == 0) {
    sprev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  } else {
    sprev_sum[0] = stemp_shuffled;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] = (ssum[j] & mod_mask) + sprev_sum[j];
  }

  // =========================================================================
  // ★ 核心修复：Stage 1 & 2 使用 Ballot While 循环涟漪进位，替代错误的前缀和
  // =========================================================================
  slc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] += slc;
    slc = stail[j] >> u;
    stail[j] &= mod_mask;
  }

  int64_t accumulated_lane31_carry =
      0;  // 专门捕捉所有从最高位（lane 31）溢出的最终进位/借位
  active = __ballot_sync(0xffffffff, slc != 0);

  // 只要有任何一个线程还有进位/借位没消化，整个 Warp 就继续同步传递
  while (active != 0) {
    if (lane_id == 31) {
      accumulated_lane31_carry += slc;
    }

    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;  // 最低位暂时不回卷

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;  // 算术右移完美处理负数借位
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // 获取从最高位最终溢出/借位的所有总量
  int64_t final_carry = __shfl_sync(0xffffffff, accumulated_lane31_carry, 31);

  // =========================================================================
  // ★ 核心修复：Stage 3 (Mod H 负向回卷)
  // =========================================================================
  slc = 0;
  if (lane_id == 0) {
    // 对于模 h (2^4352 + 1)，最高位的进位溢出权重大于 0，等价于从最低位减去。
    // 总溢出 = sretail_0 + scarry_wrap + final_carry
    int64_t total_wrap_0 = sretail_0 + scarry_wrap + final_carry;

    int64_t flag = stail[0] - total_wrap_0;
    int64_t negcarry = flag >> u;
    stail[0] = flag & mod_mask;

    flag = stail[1] - sretail_1 + negcarry;
    negcarry = flag >> u;
    stail[1] = flag & mod_mask;

    // 让借位顺着 lane_id 0 往上走，走到没有为止
    for (int j = 2; j < 8; j++) {
      flag = stail[j] + negcarry;
      negcarry = flag >> u;
      stail[j] = flag & mod_mask;
    }

    slc = negcarry;  // 如果 lane 0 扣完 8 个元素后还欠借位，扔给后面的线程
  }

  // 再次开启涟漪循环，彻底消化回卷带来的多米诺借位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // =========================================================================
  // Stage 4: 计算最终的 w = (h - g) / 2
  // =========================================================================
  uint64_t maxNum = (1ULL << u) - 1;
  if (lane_id == 0) {
    // 这一步等价于取补码 + 2
    stail[0] = maxNum + 2 - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  } else {
    stail[0] = maxNum - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  }

  // ★ 修复漏洞：maxNum+2-stail[0] 如果 stail[0] 极小，会导致超过 17
  // 位限制产生进位
  slc = 0;
  if (lane_id == 0) {
    for (int j = 0; j < 8; j++) {
      stail[j] += slc;
      slc = stail[j] >> u;
      stail[j] &= mod_mask;
    }
  }
  // 传播这最后一丝极小的正向进位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;
    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
  if (lane_id == 31) {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = 0;
  } else {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
  }

  stail[0] = (stail[0] / 2) + DivMod[0];
  stail[1] = (stail[1] / 2) + DivMod[1];
  stail[2] = (stail[2] / 2) + DivMod[2];
  stail[3] = (stail[3] / 2) + DivMod[3];
  stail[4] = (stail[4] / 2) + DivMod[4];
  stail[5] = (stail[5] / 2) + DivMod[5];
  stail[6] = (stail[6] / 2) + DivMod[6];
  stail[7] = (stail[7] / 2) + DivMod[7];

  // 最后写回外层大数组，使用全局索引 i
  inout[8 * i] = static_cast<uint64_t>(stail[0]);
  inout[8 * i + 1] = static_cast<uint64_t>(stail[1]);
  inout[8 * i + 2] = static_cast<uint64_t>(stail[2]);
  inout[8 * i + 3] = static_cast<uint64_t>(stail[3]);
  inout[8 * i + 4] = static_cast<uint64_t>(stail[4]);
  inout[8 * i + 5] = static_cast<uint64_t>(stail[5]);
  inout[8 * i + 6] = static_cast<uint64_t>(stail[6]);
  inout[8 * i + 7] = static_cast<uint64_t>(stail[7]);
}

__global__ void XYfixWarpSquareVector(
    uint64_t *inout, uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n, uint64_t mod,
    const __restrict__ uint64_t *twiddle,
    const __restrict__ uint64_t *twiddle_shoup,
    const __restrict__ uint64_t *ICTTwiddle,
    const __restrict__ uint64_t *ICTTwiddle_shoup,
    const __restrict__ uint64_t *NCTtwiddle,
    const __restrict__ uint64_t *NCTtwiddle_shoup,
    const __restrict__ uint64_t *InvNCTtwiddle,
    const __restrict__ uint64_t *InvNCTtwiddle_shoup,
    const __restrict__ uint64_t inv, const __restrict__ uint64_t inv_shoup,
    const __restrict__ uint64_t *sample) {
  uint64_t i = blockIdx.x * blockDim.x + threadIdx.x;
  uint32_t lane_id = threadIdx.x & 0x1F;
  // uint32_t warp_id = threadIdx.x >> 5; // 优化后已不再需要 shared
  // memory，因此 warp_id 可以省略

  register uint64_t CTinout[8];

  register uint64_t NCTinout[8];

  register uint64_t regs[8];
  register uint64_t new_regs[8];

  register uint64_t C;
  register uint32_t omegnIdx[8];

  // 优化：提前声明并行进位需要的寄存器变量
  uint64_t retail_0, retail_1, carry_wrap, temp_shuffled;
  uint64_t lc;
  int64_t sretail_0, sretail_1, scarry_wrap, stemp_shuffled;
  int64_t slc;

  // ================== 1. CT inout fix vector ==================
  regs[0] = inout[8 * i];
  regs[1] = inout[8 * i + 1];
  regs[2] = inout[8 * i + 2];
  regs[3] = inout[8 * i + 3];
  regs[4] = inout[8 * i + 4];
  regs[5] = inout[8 * i + 5];
  regs[6] = inout[8 * i + 6];
  regs[7] = inout[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  CTinout[0] = regs[0];
  CTinout[1] = regs[1];
  CTinout[2] = regs[2];
  CTinout[3] = regs[3];
  CTinout[4] = regs[4];
  CTinout[5] = regs[5];
  CTinout[6] = regs[6];
  CTinout[7] = regs[7];

  // ================== 2. ctRone=ctinoutA ==================

  // ================== 3. x*negmodn fix vector ==================
  register uint64_t Aa1[8];

  for (int j = 0; j < 8; j++) {
    Aa1[j] =
        multiply_and_reduce_shoup_lazy(CTinout[j], negmodn[8 * lane_id + j],
                                       negmodn_shoup[8 * lane_id + j], mod);
  }

  // ================== 4. ict Aa1 fix vector ==================
  regs[0] = Aa1[0];
  regs[1] = Aa1[1];
  regs[2] = Aa1[2];
  regs[3] = Aa1[3];
  regs[4] = Aa1[4];
  regs[5] = Aa1[5];
  regs[6] = Aa1[6];
  regs[7] = Aa1[7];

  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);

  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);

  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);

  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  uint64_t pairsInGroup = 1 << (7);
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
  omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
  omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
  omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
  omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
  omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
  omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
  omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                 mod);
    regs[j] = C ? r : l;
  }

  for (int j = 0; j < 8; j++) {
    Aa1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);
  }

  // ================== 5. OPTIMIZED modr Aa1 fix vector ==================
  int u = 17;
  const uint64_t mod_mask = (1ULL << u) - 1;
  register uint64_t regs0[8], regs1[8], regs3[8], regs4[8];
  register uint64_t new_regs3[8], new_regs4[8];
  register uint64_t sum[8], prev_sum[8], tail[8];

  regs0[0] = Aa1[0] >> u;
  regs0[1] = Aa1[1] >> u;
  regs0[2] = Aa1[2] >> u;
  regs0[3] = Aa1[3] >> u;
  regs0[4] = Aa1[4] >> u;
  regs0[5] = Aa1[5] >> u;
  regs0[6] = Aa1[6] >> u;
  regs0[7] = Aa1[7] >> u;

  regs1[0] = Aa1[0] & mod_mask;
  regs1[1] = Aa1[1] & mod_mask;
  regs1[2] = Aa1[2] & mod_mask;
  regs1[3] = Aa1[3] & mod_mask;
  regs1[4] = Aa1[4] & mod_mask;
  regs1[5] = Aa1[5] & mod_mask;
  regs1[6] = Aa1[6] & mod_mask;
  regs1[7] = Aa1[7] & mod_mask;

  regs3[0] = regs0[0] >> u;
  regs3[1] = regs0[1] >> u;
  regs3[2] = regs0[2] >> u;
  regs3[3] = regs0[3] >> u;
  regs3[4] = regs0[4] >> u;
  regs3[5] = regs0[5] >> u;
  regs3[6] = regs0[6] >> u;
  regs3[7] = regs0[7] >> u;

  regs4[0] = regs0[0] & mod_mask;
  regs4[1] = regs0[1] & mod_mask;
  regs4[2] = regs0[2] & mod_mask;
  regs4[3] = regs0[3] & mod_mask;
  regs4[4] = regs0[4] & mod_mask;
  regs4[5] = regs0[5] & mod_mask;
  regs4[6] = regs0[6] & mod_mask;
  regs4[7] = regs0[7] & mod_mask;

  // 优化核心：使用 Shuffle 代替 Shared Memory 来传播 retail 溢出
  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);

  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];

  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = (regs1[1] + new_regs4[1]);
    for (int j = 2; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  // 取代 carry[warp_id]
  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);

  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] = (sum[j] & mod_mask) + prev_sum[j];
  }

  // ----------------------------------------------------
  // 第一阶段：寄存器内部本地进位 (消除 Shared Memory 循环)
  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }

  // 【修复】捕获第一波从最高位（index 255）掉落的进位
  uint64_t stage1_carry = __shfl_sync(0xffffffff, lc, 31);

  /*
  // 第二阶段：Warp 级并行前缀和 (Scan) 获取累计进位
  warp_c = lc;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) {
      uint64_t t = __shfl_up_sync(0xffffffff, warp_c, offset);
      if (lane_id >= offset) warp_c += t;
  }

  // 传递累计进位给下一个线程
  incoming_c = __shfl_up_sync(0xffffffff, warp_c, 1);
  if (lane_id == 0) incoming_c = 0;

  tail[0] += incoming_c;

  // 第三阶段：最终本地进位修正
  lc = 0;
  #pragma unroll
  for(int j=0; j<8; j++) {
      tail[j] += lc;
      lc = tail[j] >> u;
      tail[j] &= mod_mask;
  }

  // 【修复】捕获第三阶段从最高位（index 255）再次掉落的进位
  uint64_t stage3_carry = __shfl_sync(0xffffffff, lc, 31);
  */

  uint64_t accumulated_wrap = 0;

  uint32_t active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  uint64_t final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  // 第四阶段：Lane 0 单独处理边界回卷
  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;

    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;

    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;

    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  // ----------------------------------------------------

  // ================== 6. ct Aa1 fix vector ==================
  regs[0] = tail[0];
  regs[1] = tail[1];
  regs[2] = tail[2];
  regs[3] = tail[3];
  regs[4] = tail[4];
  regs[5] = tail[5];
  regs[6] = tail[6];
  regs[7] = tail[7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  // ================== 7. ct(Aa1)*Rone fix vector ==================
  register uint64_t Mm1[8];
  for (int j = 0; j < 8; j++) {
    Mm1[j] =
        multiply_and_reduce_shoup_lazy_dotproduct(regs[j], CTinout[j], mod);
  }

  // ================== 8. ict Mm1 fix ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];

  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);

  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);

  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);

  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  pairsInGroup = 1 << (7);
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
  omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
  omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
  omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
  omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
  omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
  omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
  omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                 mod);
    regs[j] = C ? r : l;
  }

  for (int j = 0; j < 8; j++) {
    Mm1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);
  }

  // ================== 9. OPTIMIZED modr Mm1 fix vector ==================
  regs0[0] = Mm1[0] >> u;
  regs0[1] = Mm1[1] >> u;
  regs0[2] = Mm1[2] >> u;
  regs0[3] = Mm1[3] >> u;
  regs0[4] = Mm1[4] >> u;
  regs0[5] = Mm1[5] >> u;
  regs0[6] = Mm1[6] >> u;
  regs0[7] = Mm1[7] >> u;

  regs1[0] = Mm1[0] & mod_mask;
  regs1[1] = Mm1[1] & mod_mask;
  regs1[2] = Mm1[2] & mod_mask;
  regs1[3] = Mm1[3] & mod_mask;
  regs1[4] = Mm1[4] & mod_mask;
  regs1[5] = Mm1[5] & mod_mask;
  regs1[6] = Mm1[6] & mod_mask;
  regs1[7] = Mm1[7] & mod_mask;

  regs3[0] = regs0[0] >> u;
  regs3[1] = regs0[1] >> u;
  regs3[2] = regs0[2] >> u;
  regs3[3] = regs0[3] >> u;
  regs3[4] = regs0[4] >> u;
  regs3[5] = regs0[5] >> u;
  regs3[6] = regs0[6] >> u;
  regs3[7] = regs0[7] >> u;

  regs4[0] = regs0[0] & mod_mask;
  regs4[1] = regs0[1] & mod_mask;
  regs4[2] = regs0[2] & mod_mask;
  regs4[3] = regs0[3] & mod_mask;
  regs4[4] = regs0[4] & mod_mask;
  regs4[5] = regs0[5] & mod_mask;
  regs4[6] = regs0[6] & mod_mask;
  regs4[7] = regs0[7] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);

  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];

  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = (regs1[1] + new_regs4[1]);
    for (int j = 2; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);

  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] = (sum[j] & mod_mask) + prev_sum[j];
  }

  // ----------------------------------------------------
  // 第一阶段：寄存器内部本地进位 (消除 Shared Memory 循环)
  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }

  // 【修复】捕获第一波从最高位（index 255）掉落的进位
  stage1_carry = __shfl_sync(0xffffffff, lc, 31);

  /*
  // 第二阶段：Warp 级并行前缀和 (Scan) 获取累计进位
  warp_c = lc;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) {
      uint64_t t = __shfl_up_sync(0xffffffff, warp_c, offset);
      if (lane_id >= offset) warp_c += t;
  }

  // 传递累计进位给下一个线程
  incoming_c = __shfl_up_sync(0xffffffff, warp_c, 1);
  if (lane_id == 0) incoming_c = 0;

  tail[0] += incoming_c;

  // 第三阶段：最终本地进位修正
  lc = 0;
  #pragma unroll
  for(int j=0; j<8; j++) {
      tail[j] += lc;
      lc = tail[j] >> u;
      tail[j] &= mod_mask;
  }

  // 【修复】捕获第三阶段从最高位（index 255）再次掉落的进位
  stage3_carry = __shfl_sync(0xffffffff, lc, 31);
  */
  accumulated_wrap = 0;

  active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  // 第四阶段：Lane 0 单独处理边界回卷
  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;

    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;

    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;

    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  // ----------------------------------------------------

  Mm1[0] = tail[0];
  Mm1[1] = tail[1];
  Mm1[2] = tail[2];
  Mm1[3] = tail[3];
  Mm1[4] = tail[4];
  Mm1[5] = tail[5];
  Mm1[6] = tail[6];
  Mm1[7] = tail[7];

  // ================== 10. nct x fix vector ==================
  regs[0] = inout[8 * i];
  regs[1] = inout[8 * i + 1];
  regs[2] = inout[8 * i + 2];
  regs[3] = inout[8 * i + 3];
  regs[4] = inout[8 * i + 4];
  regs[5] = inout[8 * i + 5];
  regs[6] = inout[8 * i + 6];
  regs[7] = inout[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  NCTinout[0] = regs[0];
  NCTinout[1] = regs[1];
  NCTinout[2] = regs[2];
  NCTinout[3] = regs[3];
  NCTinout[4] = regs[4];
  NCTinout[5] = regs[5];
  NCTinout[6] = regs[6];
  NCTinout[7] = regs[7];

  // ================== 11. nct mm1 fix vector ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  Mm1[0] = regs[0];
  Mm1[1] = regs[1];
  Mm1[2] = regs[2];
  Mm1[3] = regs[3];
  Mm1[4] = regs[4];
  Mm1[5] = regs[5];
  Mm1[6] = regs[6];
  Mm1[7] = regs[7];

  // ================== 12. nct y fix vector ==================

  // ================== 13. g1+g2xandy ==================
  register uint64_t Gx[8];
  for (int j = 0; j < 8; j++) {
    uint64_t tmp1 = multiply_and_reduce_shoup_lazy_dotproduct(NCTinout[j],
                                                              NCTinout[j], mod);
    uint64_t tmp2 = multiply_and_reduce_shoup_lazy(
        Mm1[j], modn[8 * lane_id + j], modn_shoup[8 * lane_id + j], mod);
    Gx[j] = (tmp1 + tmp2) % MOD;
  }

  // ================== 14. inct gx fix vector ==================
  regs[0] = Gx[0];
  regs[1] = Gx[1];
  regs[2] = Gx[2];
  regs[3] = Gx[3];
  regs[4] = Gx[4];
  regs[5] = Gx[5];
  regs[6] = Gx[6];
  regs[7] = Gx[7];

  gs_butterfly(regs[0], regs[1], InvNCTtwiddle[128 + (4 * (lane_id))],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  gs_butterfly(regs[2], regs[3], InvNCTtwiddle[128 + (4 * (lane_id)) + 1],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  gs_butterfly(regs[4], regs[5], InvNCTtwiddle[128 + (4 * (lane_id)) + 2],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  gs_butterfly(regs[6], regs[7], InvNCTtwiddle[128 + (4 * (lane_id)) + 3],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  gs_butterfly(regs[0], regs[2], InvNCTtwiddle[64 + ((lane_id) * 2)],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  gs_butterfly(regs[1], regs[3], InvNCTtwiddle[64 + ((lane_id) * 2)],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  gs_butterfly(regs[4], regs[6], InvNCTtwiddle[64 + ((lane_id) * 2) + 1],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  gs_butterfly(regs[5], regs[7], InvNCTtwiddle[64 + ((lane_id) * 2) + 1],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  gs_butterfly(regs[0], regs[4], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[1], regs[5], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[2], regs[6], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[3], regs[7], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = ((8 * lane_id) & 0xFF) / pair2 + numOfGroups;
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  uint64_t pairsInGroup_inv = 1 << 7;
  uint64_t pair2_inv = pairsInGroup_inv << 1;
  uint64_t numOfGroups_inv = 128 / pairsInGroup_inv;
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = ((8 * lane_id) & 0xFF) / pair2_inv + numOfGroups_inv;
  omegnIdx[1] = numOfGroups_inv + (((8 * lane_id + 1) & 0xFF) / pair2_inv);
  omegnIdx[2] = numOfGroups_inv + (((8 * lane_id + 2) & 0xFF) / pair2_inv);
  omegnIdx[3] = numOfGroups_inv + (((8 * lane_id + 3) & 0xFF) / pair2_inv);
  omegnIdx[4] = numOfGroups_inv + (((8 * lane_id + 4) & 0xFF) / pair2_inv);
  omegnIdx[5] = numOfGroups_inv + (((8 * lane_id + 5) & 0xFF) / pair2_inv);
  omegnIdx[6] = numOfGroups_inv + (((8 * lane_id + 6) & 0xFF) / pair2_inv);
  omegnIdx[7] = numOfGroups_inv + (((8 * lane_id + 7) & 0xFF) / pair2_inv);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                 InvNCTtwiddle_shoup[omegnIdx[j]], mod);
    regs[j] = C ? r : l;
  }
  Gx[0] = multiply_and_reduce_shoup_lazy(regs[0], inv, inv_shoup, mod);
  Gx[1] = multiply_and_reduce_shoup_lazy(regs[1], inv, inv_shoup, mod);
  Gx[2] = multiply_and_reduce_shoup_lazy(regs[2], inv, inv_shoup, mod);
  Gx[3] = multiply_and_reduce_shoup_lazy(regs[3], inv, inv_shoup, mod);
  Gx[4] = multiply_and_reduce_shoup_lazy(regs[4], inv, inv_shoup, mod);
  Gx[5] = multiply_and_reduce_shoup_lazy(regs[5], inv, inv_shoup, mod);
  Gx[6] = multiply_and_reduce_shoup_lazy(regs[6], inv, inv_shoup, mod);
  Gx[7] = multiply_and_reduce_shoup_lazy(regs[7], inv, inv_shoup, mod);

  // ================== 15. OPTIMIZED modh Gx fix vector (Warp Shuffle
  // 并行带符号修正) ==================
  register int64_t sregs0[8], sregs[8], sregs1[8], sregs3[8], sregs4[8];
  register int64_t snew_regs3[8], snew_regs4[8];
  register int64_t ssum[8], sprev_sum[8], stail[8];
  register uint64_t DivMod[8];

  // 1. 获取带符号的初始值
  sregs0[0] = (Gx[0] > sample[8 * lane_id])
                  ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[0]);
  sregs0[1] = (Gx[1] > sample[(8 * lane_id + 1) & 0xFF])
                  ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[1]);
  sregs0[2] = (Gx[2] > sample[(8 * lane_id + 2) & 0xFF])
                  ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[2]);
  sregs0[3] = (Gx[3] > sample[(8 * lane_id + 3) & 0xFF])
                  ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[3]);
  sregs0[4] = (Gx[4] > sample[(8 * lane_id + 4) & 0xFF])
                  ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[4]);
  sregs0[5] = (Gx[5] > sample[(8 * lane_id + 5) & 0xFF])
                  ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[5]);
  sregs0[6] = (Gx[6] > sample[(8 * lane_id + 6) & 0xFF])
                  ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[6]);
  sregs0[7] = (Gx[7] > sample[(8 * lane_id + 7) & 0xFF])
                  ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[7]);

// 利用算术右移自动保留符号位
#pragma unroll
  for (int j = 0; j < 8; j++) {
    sregs[j] = sregs0[j] >> u;
    sregs1[j] = sregs0[j] & mod_mask;
    sregs3[j] = sregs[j] >> u;
    sregs4[j] = sregs[j] & mod_mask;
  }

  sretail_0 = __shfl_sync(0xffffffff, sregs3[6] + sregs4[7], 31);
  sretail_1 = __shfl_sync(0xffffffff, sregs3[7], 31);

  snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
  snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
  snew_regs3[2] = sregs3[0];
  snew_regs3[3] = sregs3[1];
  snew_regs3[4] = sregs3[2];
  snew_regs3[5] = sregs3[3];
  snew_regs3[6] = sregs3[4];
  snew_regs3[7] = sregs3[5];

  snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
  snew_regs4[1] = sregs4[0];
  snew_regs4[2] = sregs4[1];
  snew_regs4[3] = sregs4[2];
  snew_regs4[4] = sregs4[3];
  snew_regs4[5] = sregs4[4];
  snew_regs4[6] = sregs4[5];
  snew_regs4[7] = sregs4[6];

  if (lane_id == 0) {
    ssum[0] = sregs1[0];
    ssum[1] = (sregs1[1] + snew_regs4[1]);
    for (int j = 2; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  }

  scarry_wrap = __shfl_sync(0xffffffff, ssum[7] >> u, 31);
  stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

  if (lane_id == 0) {
    sprev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  } else {
    sprev_sum[0] = stemp_shuffled;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] = (ssum[j] & mod_mask) + sprev_sum[j];
  }

  // =========================================================================
  // ★ 核心修复：Stage 1 & 2 使用 Ballot While 循环涟漪进位，替代错误的前缀和
  // =========================================================================
  slc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] += slc;
    slc = stail[j] >> u;
    stail[j] &= mod_mask;
  }

  int64_t accumulated_lane31_carry =
      0;  // 专门捕捉所有从最高位（lane 31）溢出的最终进位/借位
  active = __ballot_sync(0xffffffff, slc != 0);

  // 只要有任何一个线程还有进位/借位没消化，整个 Warp 就继续同步传递
  while (active != 0) {
    if (lane_id == 31) {
      accumulated_lane31_carry += slc;
    }

    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;  // 最低位暂时不回卷

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;  // 算术右移完美处理负数借位
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // 获取从最高位最终溢出/借位的所有总量
  int64_t final_carry = __shfl_sync(0xffffffff, accumulated_lane31_carry, 31);

  // =========================================================================
  // ★ 核心修复：Stage 3 (Mod H 负向回卷)
  // =========================================================================
  slc = 0;
  if (lane_id == 0) {
    // 对于模 h (2^4352 + 1)，最高位的进位溢出权重大于 0，等价于从最低位减去。
    // 总溢出 = sretail_0 + scarry_wrap + final_carry
    int64_t total_wrap_0 = sretail_0 + scarry_wrap + final_carry;

    int64_t flag = stail[0] - total_wrap_0;
    int64_t negcarry = flag >> u;
    stail[0] = flag & mod_mask;

    flag = stail[1] - sretail_1 + negcarry;
    negcarry = flag >> u;
    stail[1] = flag & mod_mask;

    // 让借位顺着 lane_id 0 往上走，走到没有为止
    for (int j = 2; j < 8; j++) {
      flag = stail[j] + negcarry;
      negcarry = flag >> u;
      stail[j] = flag & mod_mask;
    }

    slc = negcarry;  // 如果 lane 0 扣完 8 个元素后还欠借位，扔给后面的线程
  }

  // 再次开启涟漪循环，彻底消化回卷带来的多米诺借位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // =========================================================================
  // Stage 4: 计算最终的 w = (h - g) / 2
  // =========================================================================
  uint64_t maxNum = (1ULL << u) - 1;
  if (lane_id == 0) {
    // 这一步等价于取补码 + 2
    stail[0] = maxNum + 2 - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  } else {
    stail[0] = maxNum - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  }

  // ★ 修复漏洞：maxNum+2-stail[0] 如果 stail[0] 极小，会导致超过 17
  // 位限制产生进位
  slc = 0;
  if (lane_id == 0) {
    for (int j = 0; j < 8; j++) {
      stail[j] += slc;
      slc = stail[j] >> u;
      stail[j] &= mod_mask;
    }
  }
  // 传播这最后一丝极小的正向进位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;
    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
  if (lane_id == 31) {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = 0;
  } else {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
  }

  stail[0] = (stail[0] / 2) + DivMod[0];
  stail[1] = (stail[1] / 2) + DivMod[1];
  stail[2] = (stail[2] / 2) + DivMod[2];
  stail[3] = (stail[3] / 2) + DivMod[3];
  stail[4] = (stail[4] / 2) + DivMod[4];
  stail[5] = (stail[5] / 2) + DivMod[5];
  stail[6] = (stail[6] / 2) + DivMod[6];
  stail[7] = (stail[7] / 2) + DivMod[7];

  // 最后写回外层大数组，使用全局索引 i
  inout[8 * i] = static_cast<uint64_t>(stail[0]);
  inout[8 * i + 1] = static_cast<uint64_t>(stail[1]);
  inout[8 * i + 2] = static_cast<uint64_t>(stail[2]);
  inout[8 * i + 3] = static_cast<uint64_t>(stail[3]);
  inout[8 * i + 4] = static_cast<uint64_t>(stail[4]);
  inout[8 * i + 5] = static_cast<uint64_t>(stail[5]);
  inout[8 * i + 6] = static_cast<uint64_t>(stail[6]);
  inout[8 * i + 7] = static_cast<uint64_t>(stail[7]);
}

__global__ void XYfixWarpIRVector(
    uint64_t *inout, uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n, uint64_t mod,
    const __restrict__ uint64_t *twiddle,
    const __restrict__ uint64_t *twiddle_shoup,
    const __restrict__ uint64_t *ICTTwiddle,
    const __restrict__ uint64_t *ICTTwiddle_shoup,
    const __restrict__ uint64_t *NCTtwiddle,
    const __restrict__ uint64_t *NCTtwiddle_shoup,
    const __restrict__ uint64_t *InvNCTtwiddle,
    const __restrict__ uint64_t *InvNCTtwiddle_shoup,
    const __restrict__ uint64_t inv, const __restrict__ uint64_t inv_shoup,
    const __restrict__ uint64_t *sample) {
  uint64_t i = blockIdx.x * blockDim.x + threadIdx.x;
  uint32_t lane_id = threadIdx.x & 0x1F;
  // uint32_t warp_id = threadIdx.x >> 5; // 优化后已不再需要 shared
  // memory，因此 warp_id 可以省略

  register uint64_t CTinout[8];
  // register uint64_t CTinoutA[8];
  register uint64_t NCTinout[8];
  // register uint64_t NCTinoutA[8];
  register uint64_t regs[8];
  register uint64_t new_regs[8];

  register uint64_t C;
  register uint32_t omegnIdx[8];

  // 优化：提前声明并行进位需要的寄存器变量
  uint64_t retail_0, retail_1, carry_wrap, temp_shuffled;
  uint64_t lc;
  int64_t sretail_0, sretail_1, scarry_wrap, stemp_shuffled;
  int64_t slc;
  //  int64_t swarp_c, sincoming_c;
  // ================== 1. CT inout fix vector ==================
  regs[0] = inout[8 * i];
  regs[1] = inout[8 * i + 1];
  regs[2] = inout[8 * i + 2];
  regs[3] = inout[8 * i + 3];
  regs[4] = inout[8 * i + 4];
  regs[5] = inout[8 * i + 5];
  regs[6] = inout[8 * i + 6];
  regs[7] = inout[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);

  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);

  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  CTinout[0] = regs[0];
  CTinout[1] = regs[1];
  CTinout[2] = regs[2];
  CTinout[3] = regs[3];
  CTinout[4] = regs[4];
  CTinout[5] = regs[5];
  CTinout[6] = regs[6];
  CTinout[7] = regs[7];

  // ================== 2. ctRone=ctinoutA ==================

  // ================== 3. x*negmodn fix vector ==================
  register uint64_t Aa1[8];
  register uint64_t Mm1[8];

  for (int j = 0; j < 8; j++) {
    Aa1[j] =
        multiply_and_reduce_shoup_lazy(CTinout[j], negmodn[8 * lane_id + j],
                                       negmodn_shoup[8 * lane_id + j], mod);
  }

  // ================== 4. ict Aa1 fix vector ==================
  regs[0] = Aa1[0];
  regs[1] = Aa1[1];
  regs[2] = Aa1[2];
  regs[3] = Aa1[3];
  regs[4] = Aa1[4];
  regs[5] = Aa1[5];
  regs[6] = Aa1[6];
  regs[7] = Aa1[7];

  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);

  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);

  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);

  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;

    omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  uint64_t pairsInGroup = 1 << (7);
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = (8 * lane_id) % pairsInGroup + pairsInGroup;
  omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
  omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
  omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
  omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
  omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
  omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
  omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                 mod);
    regs[j] = C ? r : l;
  }

  for (int j = 0; j < 8; j++) {
    Aa1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);
  }

  // ================== 5. OPTIMIZED modr Aa1 fix vector ==================
  int u = 17;
  const uint64_t mod_mask = (1ULL << u) - 1;
  register uint64_t regs0[8], regs1[8], regs3[8], regs4[8];
  register uint64_t new_regs3[8], new_regs4[8];
  register uint64_t sum[8], prev_sum[8], tail[8];

  regs0[0] = Aa1[0] >> u;
  regs0[1] = Aa1[1] >> u;
  regs0[2] = Aa1[2] >> u;
  regs0[3] = Aa1[3] >> u;
  regs0[4] = Aa1[4] >> u;
  regs0[5] = Aa1[5] >> u;
  regs0[6] = Aa1[6] >> u;
  regs0[7] = Aa1[7] >> u;

  regs1[0] = Aa1[0] & mod_mask;
  regs1[1] = Aa1[1] & mod_mask;
  regs1[2] = Aa1[2] & mod_mask;
  regs1[3] = Aa1[3] & mod_mask;
  regs1[4] = Aa1[4] & mod_mask;
  regs1[5] = Aa1[5] & mod_mask;
  regs1[6] = Aa1[6] & mod_mask;
  regs1[7] = Aa1[7] & mod_mask;

  regs3[0] = regs0[0] >> u;
  regs3[1] = regs0[1] >> u;
  regs3[2] = regs0[2] >> u;
  regs3[3] = regs0[3] >> u;
  regs3[4] = regs0[4] >> u;
  regs3[5] = regs0[5] >> u;
  regs3[6] = regs0[6] >> u;
  regs3[7] = regs0[7] >> u;

  regs4[0] = regs0[0] & mod_mask;
  regs4[1] = regs0[1] & mod_mask;
  regs4[2] = regs0[2] & mod_mask;
  regs4[3] = regs0[3] & mod_mask;
  regs4[4] = regs0[4] & mod_mask;
  regs4[5] = regs0[5] & mod_mask;
  regs4[6] = regs0[6] & mod_mask;
  regs4[7] = regs0[7] & mod_mask;

  // 优化核心：使用 Shuffle 代替 Shared Memory 来传播 retail 溢出
  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);

  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];

  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = (regs1[1] + new_regs4[1]);
    for (int j = 2; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  // 取代 carry[warp_id]
  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);

  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j <= 7; j++) prev_sum[j] = sum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] = (sum[j] & mod_mask) + prev_sum[j];
  }

  // ----------------------------------------------------
  // 第一阶段：寄存器内部本地进位 (消除 Shared Memory 循环)
  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }

  // 【修复】捕获第一波从最高位（index 255）掉落的进位
  uint64_t stage1_carry = __shfl_sync(0xffffffff, lc, 31);

  /*
  // 第二阶段：Warp 级并行前缀和 (Scan) 获取累计进位
  warp_c = lc;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) {
      uint64_t t = __shfl_up_sync(0xffffffff, warp_c, offset);
      if (lane_id >= offset) warp_c += t;
  }

  // 传递累计进位给下一个线程
  incoming_c = __shfl_up_sync(0xffffffff, warp_c, 1);
  if (lane_id == 0) incoming_c = 0;

  tail[0] += incoming_c;

  // 第三阶段：最终本地进位修正
  lc = 0;
  #pragma unroll
  for(int j=0; j<8; j++) {
      tail[j] += lc;
      lc = tail[j] >> u;
      tail[j] &= mod_mask;
  }

  // 【修复】捕获第三阶段从最高位（index 255）再次掉落的进位
  uint64_t stage3_carry = __shfl_sync(0xffffffff, lc, 31);
  */
  uint64_t accumulated_wrap = 0;

  uint32_t active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  uint64_t final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  // 第四阶段：Lane 0 单独处理边界回卷
  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;

    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;

    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;

    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  // ----------------------------------------------------
  Mm1[0] = tail[0];
  Mm1[1] = tail[1];
  Mm1[2] = tail[2];
  Mm1[3] = tail[3];
  Mm1[4] = tail[4];
  Mm1[5] = tail[5];
  Mm1[6] = tail[6];
  Mm1[7] = tail[7];

  // ----------------------------------------------------

  // ================== 6. ct Aa1 fix vector ==================

  // ================== 7. ct(Aa1)*Rone fix vector ==================

  // ================== 8. ict Mm1 fix ==================

  // ================== 9. OPTIMIZED modr Mm1 fix vector ==================

  // ================== 10. nct x fix vector ==================
  regs[0] = inout[8 * i];
  regs[1] = inout[8 * i + 1];
  regs[2] = inout[8 * i + 2];
  regs[3] = inout[8 * i + 3];
  regs[4] = inout[8 * i + 4];
  regs[5] = inout[8 * i + 5];
  regs[6] = inout[8 * i + 6];
  regs[7] = inout[8 * i + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  NCTinout[0] = regs[0];
  NCTinout[1] = regs[1];
  NCTinout[2] = regs[2];
  NCTinout[3] = regs[3];
  NCTinout[4] = regs[4];
  NCTinout[5] = regs[5];
  NCTinout[6] = regs[6];
  NCTinout[7] = regs[7];

  // ================== 11. nct mm1 fix vector ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;

    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }

  ct_butterfly(regs[0], regs[4], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[(lane_id) + 32],
               NCTtwiddle_shoup[(lane_id) + 32], mod);

  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + ((lane_id) * 2)],
               NCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + ((lane_id) * 2) + 1],
               NCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + (4 * (lane_id))],
               NCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + (4 * (lane_id)) + 1],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + (4 * (lane_id)) + 2],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + (4 * (lane_id)) + 3],
               NCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  Mm1[0] = regs[0];
  Mm1[1] = regs[1];
  Mm1[2] = regs[2];
  Mm1[3] = regs[3];
  Mm1[4] = regs[4];
  Mm1[5] = regs[5];
  Mm1[6] = regs[6];
  Mm1[7] = regs[7];

  // ================== 12. nct y fix vector ==================

  // ================== 13. g1+g2xandy ==================
  register uint64_t Gx[8];
  for (int j = 0; j < 8; j++) {
    // uint64_t tmp1 =
    // multiply_and_reduce_shoup_lazy_dotproduct(NCTinoutA[j],NCTinout[j],mod);
    uint64_t tmp2 = multiply_and_reduce_shoup_lazy(
        Mm1[j], modn[8 * lane_id + j], modn_shoup[8 * lane_id + j], mod);
    Gx[j] = (NCTinout[j] + tmp2) % MOD;
  }

  // ================== 14. inct gx fix vector ==================
  regs[0] = Gx[0];
  regs[1] = Gx[1];
  regs[2] = Gx[2];
  regs[3] = Gx[3];
  regs[4] = Gx[4];
  regs[5] = Gx[5];
  regs[6] = Gx[6];
  regs[7] = Gx[7];

  gs_butterfly(regs[0], regs[1], InvNCTtwiddle[128 + (4 * (lane_id))],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id))], mod);
  gs_butterfly(regs[2], regs[3], InvNCTtwiddle[128 + (4 * (lane_id)) + 1],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 1], mod);
  gs_butterfly(regs[4], regs[5], InvNCTtwiddle[128 + (4 * (lane_id)) + 2],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 2], mod);
  gs_butterfly(regs[6], regs[7], InvNCTtwiddle[128 + (4 * (lane_id)) + 3],
               InvNCTtwiddle_shoup[128 + (4 * (lane_id)) + 3], mod);

  gs_butterfly(regs[0], regs[2], InvNCTtwiddle[64 + ((lane_id) * 2)],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  gs_butterfly(regs[1], regs[3], InvNCTtwiddle[64 + ((lane_id) * 2)],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2)], mod);
  gs_butterfly(regs[4], regs[6], InvNCTtwiddle[64 + ((lane_id) * 2) + 1],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);
  gs_butterfly(regs[5], regs[7], InvNCTtwiddle[64 + ((lane_id) * 2) + 1],
               InvNCTtwiddle_shoup[64 + ((lane_id) * 2) + 1], mod);

  gs_butterfly(regs[0], regs[4], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[1], regs[5], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[2], regs[6], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  gs_butterfly(regs[3], regs[7], InvNCTtwiddle[(lane_id) + 32],
               InvNCTtwiddle_shoup[(lane_id) + 32], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);

    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = ((8 * lane_id) & 0xFF) / pair2 + numOfGroups;
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);

    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j];
      uint64_t r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }

  uint64_t pairsInGroup_inv = 1 << 7;
  uint64_t pair2_inv = pairsInGroup_inv << 1;
  uint64_t numOfGroups_inv = 128 / pairsInGroup_inv;
  new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
  new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
  new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
  new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
  new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
  new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
  new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
  new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);

  C = (lane_id >> 4) & 1;

  omegnIdx[0] = ((8 * lane_id) & 0xFF) / pair2_inv + numOfGroups_inv;
  omegnIdx[1] = numOfGroups_inv + (((8 * lane_id + 1) & 0xFF) / pair2_inv);
  omegnIdx[2] = numOfGroups_inv + (((8 * lane_id + 2) & 0xFF) / pair2_inv);
  omegnIdx[3] = numOfGroups_inv + (((8 * lane_id + 3) & 0xFF) / pair2_inv);
  omegnIdx[4] = numOfGroups_inv + (((8 * lane_id + 4) & 0xFF) / pair2_inv);
  omegnIdx[5] = numOfGroups_inv + (((8 * lane_id + 5) & 0xFF) / pair2_inv);
  omegnIdx[6] = numOfGroups_inv + (((8 * lane_id + 6) & 0xFF) / pair2_inv);
  omegnIdx[7] = numOfGroups_inv + (((8 * lane_id + 7) & 0xFF) / pair2_inv);

  for (int j = 0; j < 8; j++) {
    uint64_t l = C ? new_regs[j] : regs[j];
    uint64_t r = C ? regs[j] : new_regs[j];
    gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                 InvNCTtwiddle_shoup[omegnIdx[j]], mod);
    regs[j] = C ? r : l;
  }
  Gx[0] = multiply_and_reduce_shoup_lazy(regs[0], inv, inv_shoup, mod);
  Gx[1] = multiply_and_reduce_shoup_lazy(regs[1], inv, inv_shoup, mod);
  Gx[2] = multiply_and_reduce_shoup_lazy(regs[2], inv, inv_shoup, mod);
  Gx[3] = multiply_and_reduce_shoup_lazy(regs[3], inv, inv_shoup, mod);
  Gx[4] = multiply_and_reduce_shoup_lazy(regs[4], inv, inv_shoup, mod);
  Gx[5] = multiply_and_reduce_shoup_lazy(regs[5], inv, inv_shoup, mod);
  Gx[6] = multiply_and_reduce_shoup_lazy(regs[6], inv, inv_shoup, mod);
  Gx[7] = multiply_and_reduce_shoup_lazy(regs[7], inv, inv_shoup, mod);

  // ================== 15. OPTIMIZED modh Gx fix vector (Warp Shuffle
  // 并行带符号修正) ==================

  register int64_t sregs0[8], sregs[8], sregs1[8], sregs3[8], sregs4[8];
  register int64_t snew_regs3[8], snew_regs4[8];
  register int64_t ssum[8], sprev_sum[8], stail[8];
  register uint64_t DivMod[8];

  // 1. 获取带符号的初始值
  sregs0[0] = (Gx[0] > sample[8 * lane_id])
                  ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[0]);
  sregs0[1] = (Gx[1] > sample[(8 * lane_id + 1) & 0xFF])
                  ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[1]);
  sregs0[2] = (Gx[2] > sample[(8 * lane_id + 2) & 0xFF])
                  ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[2]);
  sregs0[3] = (Gx[3] > sample[(8 * lane_id + 3) & 0xFF])
                  ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[3]);
  sregs0[4] = (Gx[4] > sample[(8 * lane_id + 4) & 0xFF])
                  ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[4]);
  sregs0[5] = (Gx[5] > sample[(8 * lane_id + 5) & 0xFF])
                  ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[5]);
  sregs0[6] = (Gx[6] > sample[(8 * lane_id + 6) & 0xFF])
                  ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[6]);
  sregs0[7] = (Gx[7] > sample[(8 * lane_id + 7) & 0xFF])
                  ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[7]);

// 利用算术右移自动保留符号位
#pragma unroll
  for (int j = 0; j < 8; j++) {
    sregs[j] = sregs0[j] >> u;
    sregs1[j] = sregs0[j] & mod_mask;
    sregs3[j] = sregs[j] >> u;
    sregs4[j] = sregs[j] & mod_mask;
  }

  sretail_0 = __shfl_sync(0xffffffff, sregs3[6] + sregs4[7], 31);
  sretail_1 = __shfl_sync(0xffffffff, sregs3[7], 31);

  snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
  snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
  snew_regs3[2] = sregs3[0];
  snew_regs3[3] = sregs3[1];
  snew_regs3[4] = sregs3[2];
  snew_regs3[5] = sregs3[3];
  snew_regs3[6] = sregs3[4];
  snew_regs3[7] = sregs3[5];

  snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
  snew_regs4[1] = sregs4[0];
  snew_regs4[2] = sregs4[1];
  snew_regs4[3] = sregs4[2];
  snew_regs4[4] = sregs4[3];
  snew_regs4[5] = sregs4[4];
  snew_regs4[6] = sregs4[5];
  snew_regs4[7] = sregs4[6];

  if (lane_id == 0) {
    ssum[0] = sregs1[0];
    ssum[1] = (sregs1[1] + snew_regs4[1]);
    for (int j = 2; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  }

  scarry_wrap = __shfl_sync(0xffffffff, ssum[7] >> u, 31);
  stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

  if (lane_id == 0) {
    sprev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  } else {
    sprev_sum[0] = stemp_shuffled;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] = (ssum[j] & mod_mask) + sprev_sum[j];
  }

  // =========================================================================
  // ★ 核心修复：Stage 1 & 2 使用 Ballot While 循环涟漪进位，替代错误的前缀和
  // =========================================================================
  slc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] += slc;
    slc = stail[j] >> u;
    stail[j] &= mod_mask;
  }

  int64_t accumulated_lane31_carry =
      0;  // 专门捕捉所有从最高位（lane 31）溢出的最终进位/借位
  active = __ballot_sync(0xffffffff, slc != 0);

  // 只要有任何一个线程还有进位/借位没消化，整个 Warp 就继续同步传递
  while (active != 0) {
    if (lane_id == 31) {
      accumulated_lane31_carry += slc;
    }

    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;  // 最低位暂时不回卷

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;  // 算术右移完美处理负数借位
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // 获取从最高位最终溢出/借位的所有总量
  int64_t final_carry = __shfl_sync(0xffffffff, accumulated_lane31_carry, 31);

  // =========================================================================
  // ★ 核心修复：Stage 3 (Mod H 负向回卷)
  // =========================================================================
  slc = 0;
  if (lane_id == 0) {
    // 对于模 h (2^4352 + 1)，最高位的进位溢出权重大于 0，等价于从最低位减去。
    // 总溢出 = sretail_0 + scarry_wrap + final_carry
    int64_t total_wrap_0 = sretail_0 + scarry_wrap + final_carry;

    int64_t flag = stail[0] - total_wrap_0;
    int64_t negcarry = flag >> u;
    stail[0] = flag & mod_mask;

    flag = stail[1] - sretail_1 + negcarry;
    negcarry = flag >> u;
    stail[1] = flag & mod_mask;

    // 让借位顺着 lane_id 0 往上走，走到没有为止
    for (int j = 2; j < 8; j++) {
      flag = stail[j] + negcarry;
      negcarry = flag >> u;
      stail[j] = flag & mod_mask;
    }

    slc = negcarry;  // 如果 lane 0 扣完 8 个元素后还欠借位，扔给后面的线程
  }

  // 再次开启涟漪循环，彻底消化回卷带来的多米诺借位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // =========================================================================
  // Stage 4: 计算最终的 w = (h - g) / 2
  // =========================================================================
  uint64_t maxNum = (1ULL << u) - 1;
  if (lane_id == 0) {
    // 这一步等价于取补码 + 2
    stail[0] = maxNum + 2 - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  } else {
    stail[0] = maxNum - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  }

  // ★ 修复漏洞：maxNum+2-stail[0] 如果 stail[0] 极小，会导致超过 17
  // 位限制产生进位
  slc = 0;
  if (lane_id == 0) {
    for (int j = 0; j < 8; j++) {
      stail[j] += slc;
      slc = stail[j] >> u;
      stail[j] &= mod_mask;
    }
  }
  // 传播这最后一丝极小的正向进位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;
    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
  if (lane_id == 31) {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = 0;
  } else {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
  }

  stail[0] = (stail[0] / 2) + DivMod[0];
  stail[1] = (stail[1] / 2) + DivMod[1];
  stail[2] = (stail[2] / 2) + DivMod[2];
  stail[3] = (stail[3] / 2) + DivMod[3];
  stail[4] = (stail[4] / 2) + DivMod[4];
  stail[5] = (stail[5] / 2) + DivMod[5];
  stail[6] = (stail[6] / 2) + DivMod[6];
  stail[7] = (stail[7] / 2) + DivMod[7];
  // 最后写回外层大数组，使用全局索引 i
  inout[8 * i] = static_cast<uint64_t>(stail[0]);
  inout[8 * i + 1] = static_cast<uint64_t>(stail[1]);
  inout[8 * i + 2] = static_cast<uint64_t>(stail[2]);
  inout[8 * i + 3] = static_cast<uint64_t>(stail[3]);
  inout[8 * i + 4] = static_cast<uint64_t>(stail[4]);
  inout[8 * i + 5] = static_cast<uint64_t>(stail[5]);
  inout[8 * i + 6] = static_cast<uint64_t>(stail[6]);
  inout[8 * i + 7] = static_cast<uint64_t>(stail[7]);
}

// start device function xy

__device__ __forceinline__ void XYfixWarpVector_dev(
    uint64_t *inout, uint64_t *inoutA, uint64_t *negmodn,
    uint64_t *negmodn_shoup, uint64_t *modn, uint64_t *modn_shoup, uint64_t n,
    uint64_t mod, const __restrict__ uint64_t *twiddle,
    const __restrict__ uint64_t *twiddle_shoup,
    const __restrict__ uint64_t *ICTTwiddle,
    const __restrict__ uint64_t *ICTTwiddle_shoup,
    const __restrict__ uint64_t *NCTtwiddle,
    const __restrict__ uint64_t *NCTtwiddle_shoup,
    const __restrict__ uint64_t *InvNCTtwiddle,
    const __restrict__ uint64_t *InvNCTtwiddle_shoup,
    const __restrict__ uint64_t inv, const __restrict__ uint64_t inv_shoup,
    const __restrict__ uint64_t *sample) {
  // ★ 唯一修改：去掉全局索引 i，改用 lane_id
  uint32_t lane_id = threadIdx.x & 0x1F;

  register uint64_t CTinout[8];
  register uint64_t CTinoutA[8];
  register uint64_t NCTinout[8];
  register uint64_t NCTinoutA[8];
  register uint64_t regs[8];
  register uint64_t new_regs[8];
  register uint64_t C;
  register uint32_t omegnIdx[8];

  uint64_t retail_0, retail_1, carry_wrap, temp_shuffled;
  uint64_t lc;
  int64_t sretail_0, sretail_1, scarry_wrap, stemp_shuffled;
  int64_t slc;
  // int64_t swarp_c, sincoming_c
  //  ================== 1. CT inout ==================
  //  ★ inout[8*i+j] → inout[8*lane_id+j]
  regs[0] = inout[8 * lane_id];
  regs[1] = inout[8 * lane_id + 1];
  regs[2] = inout[8 * lane_id + 2];
  regs[3] = inout[8 * lane_id + 3];
  regs[4] = inout[8 * lane_id + 4];
  regs[5] = inout[8 * lane_id + 5];
  regs[6] = inout[8 * lane_id + 6];
  regs[7] = inout[8 * lane_id + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);
  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);
  CTinout[0] = regs[0];
  CTinout[1] = regs[1];
  CTinout[2] = regs[2];
  CTinout[3] = regs[3];
  CTinout[4] = regs[4];
  CTinout[5] = regs[5];
  CTinout[6] = regs[6];
  CTinout[7] = regs[7];

  // ================== 2. CT inoutA ==================
  // ★ inoutA[8*i+j] → inoutA[8*lane_id+j]
  regs[0] = inoutA[8 * lane_id];
  regs[1] = inoutA[8 * lane_id + 1];
  regs[2] = inoutA[8 * lane_id + 2];
  regs[3] = inoutA[8 * lane_id + 3];
  regs[4] = inoutA[8 * lane_id + 4];
  regs[5] = inoutA[8 * lane_id + 5];
  regs[6] = inoutA[8 * lane_id + 6];
  regs[7] = inoutA[8 * lane_id + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);
  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);
  CTinoutA[0] = regs[0];
  CTinoutA[1] = regs[1];
  CTinoutA[2] = regs[2];
  CTinoutA[3] = regs[3];
  CTinoutA[4] = regs[4];
  CTinoutA[5] = regs[5];
  CTinoutA[6] = regs[6];
  CTinoutA[7] = regs[7];

  // ================== 3. x*negmodn ==================
  register uint64_t Aa1[8];
  for (int j = 0; j < 8; j++)
    Aa1[j] =
        multiply_and_reduce_shoup_lazy(CTinout[j], negmodn[8 * lane_id + j],
                                       negmodn_shoup[8 * lane_id + j], mod);

  // ================== 4. ICT Aa1 ==================
  regs[0] = Aa1[0];
  regs[1] = Aa1[1];
  regs[2] = Aa1[2];
  regs[3] = Aa1[3];
  regs[4] = Aa1[4];
  regs[5] = Aa1[5];
  regs[6] = Aa1[6];
  regs[7] = Aa1[7];
  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup = 1 << 7;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Aa1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 5. modr Aa1 ==================
  int u = 17;
  const uint64_t mod_mask = (1ULL << u) - 1;
  register uint64_t regs0[8], regs1[8], regs3[8], regs4[8];
  register uint64_t new_regs3[8], new_regs4[8];
  register uint64_t sum[8], prev_sum[8], tail[8];

  for (int j = 0; j < 8; j++) regs0[j] = Aa1[j] >> u;
  for (int j = 0; j < 8; j++) regs1[j] = Aa1[j] & mod_mask;
  for (int j = 0; j < 8; j++) regs3[j] = regs0[j] >> u;
  for (int j = 0; j < 8; j++) regs4[j] = regs0[j] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);
  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];
  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = regs1[1] + new_regs4[1];
    for (int j = 2; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);
  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  }
#pragma unroll
  for (int j = 0; j < 8; j++) tail[j] = (sum[j] & mod_mask) + prev_sum[j];

  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }
  uint64_t stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  warp_c=lc;
  #pragma unroll
  for(int offset=1;offset<32;offset<<=1){
      uint64_t t=__shfl_up_sync(0xffffffff,warp_c,offset);
      if(lane_id>=(uint32_t)offset) warp_c+=t;
  }
  incoming_c=__shfl_up_sync(0xffffffff,warp_c,1);
  if(lane_id==0) incoming_c=0;
  tail[0]+=incoming_c;

  lc=0;
  #pragma unroll
  for(int j=0;j<8;j++){ tail[j]+=lc; lc=tail[j]>>u; tail[j]&=mod_mask; }
  uint64_t stage3_carry=__shfl_sync(0xffffffff,lc,31);
  */
  uint64_t accumulated_wrap = 0;

  uint32_t active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  uint64_t final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;
    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;
    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;
    tail[2] = (tail[2] + cay1) & mod_mask;
  }

  // ================== 6. CT Aa1 ==================
  regs[0] = tail[0];
  regs[1] = tail[1];
  regs[2] = tail[2];
  regs[3] = tail[3];
  regs[4] = tail[4];
  regs[5] = tail[5];
  regs[6] = tail[6];
  regs[7] = tail[7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);
  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  // ================== 7. CT(Aa1)*CTinoutA ==================
  register uint64_t Mm1[8];
  for (int j = 0; j < 8; j++)
    Mm1[j] =
        multiply_and_reduce_shoup_lazy_dotproduct(regs[j], CTinoutA[j], mod);

  // ================== 8. ICT Mm1 ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];
  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup = 1 << 7;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Mm1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 9. modr Mm1 ==================
  for (int j = 0; j < 8; j++) regs0[j] = Mm1[j] >> u;
  for (int j = 0; j < 8; j++) regs1[j] = Mm1[j] & mod_mask;
  for (int j = 0; j < 8; j++) regs3[j] = regs0[j] >> u;
  for (int j = 0; j < 8; j++) regs4[j] = regs0[j] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);
  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];
  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = regs1[1] + new_regs4[1];
    for (int j = 2; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);
  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  }
#pragma unroll
  for (int j = 0; j < 8; j++) tail[j] = (sum[j] & mod_mask) + prev_sum[j];

  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }
  stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  warp_c=lc;
  #pragma unroll
  for(int offset=1;offset<32;offset<<=1){
      uint64_t t=__shfl_up_sync(0xffffffff,warp_c,offset);
      if(lane_id>=(uint32_t)offset) warp_c+=t;
  }
  incoming_c=__shfl_up_sync(0xffffffff,warp_c,1);
  if(lane_id==0) incoming_c=0;
  tail[0]+=incoming_c;

  lc=0;
  #pragma unroll
  for(int j=0;j<8;j++){ tail[j]+=lc; lc=tail[j]>>u; tail[j]&=mod_mask; }
  stage3_carry=__shfl_sync(0xffffffff,lc,31);
  */
  accumulated_wrap = 0;

  active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;
    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;
    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;
    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  for (int j = 0; j < 8; j++) Mm1[j] = tail[j];

  // ================== 10. NCT inout ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  regs[0] = inout[8 * lane_id];
  regs[1] = inout[8 * lane_id + 1];
  regs[2] = inout[8 * lane_id + 2];
  regs[3] = inout[8 * lane_id + 3];
  regs[4] = inout[8 * lane_id + 4];
  regs[5] = inout[8 * lane_id + 5];
  regs[6] = inout[8 * lane_id + 6];
  regs[7] = inout[8 * lane_id + 7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  NCTinout[0] = regs[0];
  NCTinout[1] = regs[1];
  NCTinout[2] = regs[2];
  NCTinout[3] = regs[3];
  NCTinout[4] = regs[4];
  NCTinout[5] = regs[5];
  NCTinout[6] = regs[6];
  NCTinout[7] = regs[7];

  // ================== 11. NCT Mm1 ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  for (int j = 0; j < 8; j++) Mm1[j] = regs[j];

  // ================== 12. NCT inoutA ==================
  // ★ inoutA[8*i+j] → inoutA[8*lane_id+j]
  regs[0] = inoutA[8 * lane_id];
  regs[1] = inoutA[8 * lane_id + 1];
  regs[2] = inoutA[8 * lane_id + 2];
  regs[3] = inoutA[8 * lane_id + 3];
  regs[4] = inoutA[8 * lane_id + 4];
  regs[5] = inoutA[8 * lane_id + 5];
  regs[6] = inoutA[8 * lane_id + 6];
  regs[7] = inoutA[8 * lane_id + 7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  NCTinoutA[0] = regs[0];
  NCTinoutA[1] = regs[1];
  NCTinoutA[2] = regs[2];
  NCTinoutA[3] = regs[3];
  NCTinoutA[4] = regs[4];
  NCTinoutA[5] = regs[5];
  NCTinoutA[6] = regs[6];
  NCTinoutA[7] = regs[7];

  // ================== 13. Gx = NCT(x)*NCT(y) + NCT(m)*N ==================
  register uint64_t Gx[8];
  for (int j = 0; j < 8; j++) {
    uint64_t tmp1 = multiply_and_reduce_shoup_lazy_dotproduct(NCTinoutA[j],
                                                              NCTinout[j], mod);
    uint64_t tmp2 = multiply_and_reduce_shoup_lazy(
        Mm1[j], modn[8 * lane_id + j], modn_shoup[8 * lane_id + j], mod);
    Gx[j] = (tmp1 + tmp2) % MOD;
  }

  // ================== 14. INCT Gx ==================
  regs[0] = Gx[0];
  regs[1] = Gx[1];
  regs[2] = Gx[2];
  regs[3] = Gx[3];
  regs[4] = Gx[4];
  regs[5] = Gx[5];
  regs[6] = Gx[6];
  regs[7] = Gx[7];
  gs_butterfly(regs[0], regs[1], InvNCTtwiddle[128 + 4 * lane_id],
               InvNCTtwiddle_shoup[128 + 4 * lane_id], mod);
  gs_butterfly(regs[2], regs[3], InvNCTtwiddle[128 + 4 * lane_id + 1],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  gs_butterfly(regs[4], regs[5], InvNCTtwiddle[128 + 4 * lane_id + 2],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  gs_butterfly(regs[6], regs[7], InvNCTtwiddle[128 + 4 * lane_id + 3],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  gs_butterfly(regs[0], regs[2], InvNCTtwiddle[64 + lane_id * 2],
               InvNCTtwiddle_shoup[64 + lane_id * 2], mod);
  gs_butterfly(regs[1], regs[3], InvNCTtwiddle[64 + lane_id * 2],
               InvNCTtwiddle_shoup[64 + lane_id * 2], mod);
  gs_butterfly(regs[4], regs[6], InvNCTtwiddle[64 + lane_id * 2 + 1],
               InvNCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  gs_butterfly(regs[5], regs[7], InvNCTtwiddle[64 + lane_id * 2 + 1],
               InvNCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  gs_butterfly(regs[0], regs[4], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[1], regs[5], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[2], regs[6], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[3], regs[7], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = (((8 * lane_id) & 0xFF) / pair2) + numOfGroups;
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup_inv = 1 << 7;
    uint64_t pair2_inv = pairsInGroup_inv << 1;
    uint64_t numOfGroups_inv = 128 / pairsInGroup_inv;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = (((8 * lane_id) & 0xFF) / pair2_inv) + numOfGroups_inv;
    omegnIdx[1] = numOfGroups_inv + (((8 * lane_id + 1) & 0xFF) / pair2_inv);
    omegnIdx[2] = numOfGroups_inv + (((8 * lane_id + 2) & 0xFF) / pair2_inv);
    omegnIdx[3] = numOfGroups_inv + (((8 * lane_id + 3) & 0xFF) / pair2_inv);
    omegnIdx[4] = numOfGroups_inv + (((8 * lane_id + 4) & 0xFF) / pair2_inv);
    omegnIdx[5] = numOfGroups_inv + (((8 * lane_id + 5) & 0xFF) / pair2_inv);
    omegnIdx[6] = numOfGroups_inv + (((8 * lane_id + 6) & 0xFF) / pair2_inv);
    omegnIdx[7] = numOfGroups_inv + (((8 * lane_id + 7) & 0xFF) / pair2_inv);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Gx[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 15. modh Gx ==================
  register int64_t sregs0[8], sregs[8], sregs1[8], sregs3[8], sregs4[8];
  register int64_t snew_regs3[8], snew_regs4[8];
  register int64_t ssum[8], sprev_sum[8], stail[8];
  register uint64_t DivMod[8];

  // 1. 获取带符号的初始值
  sregs0[0] = (Gx[0] > sample[8 * lane_id])
                  ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[0]);
  sregs0[1] = (Gx[1] > sample[(8 * lane_id + 1) & 0xFF])
                  ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[1]);
  sregs0[2] = (Gx[2] > sample[(8 * lane_id + 2) & 0xFF])
                  ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[2]);
  sregs0[3] = (Gx[3] > sample[(8 * lane_id + 3) & 0xFF])
                  ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[3]);
  sregs0[4] = (Gx[4] > sample[(8 * lane_id + 4) & 0xFF])
                  ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[4]);
  sregs0[5] = (Gx[5] > sample[(8 * lane_id + 5) & 0xFF])
                  ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[5]);
  sregs0[6] = (Gx[6] > sample[(8 * lane_id + 6) & 0xFF])
                  ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[6]);
  sregs0[7] = (Gx[7] > sample[(8 * lane_id + 7) & 0xFF])
                  ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[7]);

// 利用算术右移自动保留符号位
#pragma unroll
  for (int j = 0; j < 8; j++) {
    sregs[j] = sregs0[j] >> u;
    sregs1[j] = sregs0[j] & mod_mask;
    sregs3[j] = sregs[j] >> u;
    sregs4[j] = sregs[j] & mod_mask;
  }

  sretail_0 = __shfl_sync(0xffffffff, sregs3[6] + sregs4[7], 31);
  sretail_1 = __shfl_sync(0xffffffff, sregs3[7], 31);

  snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
  snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
  snew_regs3[2] = sregs3[0];
  snew_regs3[3] = sregs3[1];
  snew_regs3[4] = sregs3[2];
  snew_regs3[5] = sregs3[3];
  snew_regs3[6] = sregs3[4];
  snew_regs3[7] = sregs3[5];

  snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
  snew_regs4[1] = sregs4[0];
  snew_regs4[2] = sregs4[1];
  snew_regs4[3] = sregs4[2];
  snew_regs4[4] = sregs4[3];
  snew_regs4[5] = sregs4[4];
  snew_regs4[6] = sregs4[5];
  snew_regs4[7] = sregs4[6];

  if (lane_id == 0) {
    ssum[0] = sregs1[0];
    ssum[1] = (sregs1[1] + snew_regs4[1]);
    for (int j = 2; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  }

  scarry_wrap = __shfl_sync(0xffffffff, ssum[7] >> u, 31);
  stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

  if (lane_id == 0) {
    sprev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  } else {
    sprev_sum[0] = stemp_shuffled;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] = (ssum[j] & mod_mask) + sprev_sum[j];
  }

  // =========================================================================
  // ★ 核心修复：Stage 1 & 2 使用 Ballot While 循环涟漪进位，替代错误的前缀和
  // =========================================================================
  slc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] += slc;
    slc = stail[j] >> u;
    stail[j] &= mod_mask;
  }

  int64_t accumulated_lane31_carry =
      0;  // 专门捕捉所有从最高位（lane 31）溢出的最终进位/借位
  active = __ballot_sync(0xffffffff, slc != 0);

  // 只要有任何一个线程还有进位/借位没消化，整个 Warp 就继续同步传递
  while (active != 0) {
    if (lane_id == 31) {
      accumulated_lane31_carry += slc;
    }

    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;  // 最低位暂时不回卷

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;  // 算术右移完美处理负数借位
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // 获取从最高位最终溢出/借位的所有总量
  int64_t final_carry = __shfl_sync(0xffffffff, accumulated_lane31_carry, 31);

  // =========================================================================
  // ★ 核心修复：Stage 3 (Mod H 负向回卷)
  // =========================================================================
  slc = 0;
  if (lane_id == 0) {
    // 对于模 h (2^4352 + 1)，最高位的进位溢出权重大于 0，等价于从最低位减去。
    // 总溢出 = sretail_0 + scarry_wrap + final_carry
    int64_t total_wrap_0 = sretail_0 + scarry_wrap + final_carry;

    int64_t flag = stail[0] - total_wrap_0;
    int64_t negcarry = flag >> u;
    stail[0] = flag & mod_mask;

    flag = stail[1] - sretail_1 + negcarry;
    negcarry = flag >> u;
    stail[1] = flag & mod_mask;

    // 让借位顺着 lane_id 0 往上走，走到没有为止
    for (int j = 2; j < 8; j++) {
      flag = stail[j] + negcarry;
      negcarry = flag >> u;
      stail[j] = flag & mod_mask;
    }

    slc = negcarry;  // 如果 lane 0 扣完 8 个元素后还欠借位，扔给后面的线程
  }

  // 再次开启涟漪循环，彻底消化回卷带来的多米诺借位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // =========================================================================
  // Stage 4: 计算最终的 w = (h - g) / 2
  // =========================================================================
  uint64_t maxNum = (1ULL << u) - 1;
  if (lane_id == 0) {
    // 这一步等价于取补码 + 2
    stail[0] = maxNum + 2 - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  } else {
    stail[0] = maxNum - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  }

  // ★ 修复漏洞：maxNum+2-stail[0] 如果 stail[0] 极小，会导致超过 17
  // 位限制产生进位
  slc = 0;
  if (lane_id == 0) {
    for (int j = 0; j < 8; j++) {
      stail[j] += slc;
      slc = stail[j] >> u;
      stail[j] &= mod_mask;
    }
  }
  // 传播这最后一丝极小的正向进位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;
    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
  if (lane_id == 31) {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = 0;
  } else {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
  }

  stail[0] = (stail[0] / 2) + DivMod[0];
  stail[1] = (stail[1] / 2) + DivMod[1];
  stail[2] = (stail[2] / 2) + DivMod[2];
  stail[3] = (stail[3] / 2) + DivMod[3];
  stail[4] = (stail[4] / 2) + DivMod[4];
  stail[5] = (stail[5] / 2) + DivMod[5];
  stail[6] = (stail[6] / 2) + DivMod[6];
  stail[7] = (stail[7] / 2) + DivMod[7];

  // ================== 16. 写回 ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  for (int j = 0; j < 8; j++)
    inout[8 * lane_id + j] = static_cast<uint64_t>(stail[j]);
}

// end device function xy

// start device xr1 2banben
__device__ __forceinline__ void XYfixWarpROneVector_dev(
    uint64_t *inout,
    uint64_t *inoutAct,   // 预计算好的 CT(R1)，所有 warp 共享，不偏移
    uint64_t *inoutAnct,  // 预计算好的 NCT(R1)，所有 warp 共享，不偏移
    uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n, uint64_t mod,
    const __restrict__ uint64_t *twiddle,
    const __restrict__ uint64_t *twiddle_shoup,
    const __restrict__ uint64_t *ICTTwiddle,
    const __restrict__ uint64_t *ICTTwiddle_shoup,
    const __restrict__ uint64_t *NCTtwiddle,
    const __restrict__ uint64_t *NCTtwiddle_shoup,
    const __restrict__ uint64_t *InvNCTtwiddle,
    const __restrict__ uint64_t *InvNCTtwiddle_shoup,
    const __restrict__ uint64_t inv, const __restrict__ uint64_t inv_shoup,
    const __restrict__ uint64_t *sample) {
  // ★ 唯一修改：去掉全局索引 i，改用 lane_id
  uint32_t lane_id = threadIdx.x & 0x1F;

  register uint64_t CTinout[8];
  register uint64_t CTinoutA[8];
  register uint64_t NCTinout[8];
  register uint64_t NCTinoutA[8];
  register uint64_t regs[8];
  register uint64_t new_regs[8];
  register uint64_t C;
  register uint32_t omegnIdx[8];

  uint64_t retail_0, retail_1, carry_wrap, temp_shuffled;
  uint64_t lc;
  int64_t sretail_0, sretail_1, scarry_wrap, stemp_shuffled;
  int64_t slc;
  // int64_t swarp_c, sincoming_c
  //  ================== 1. CT inout ==================
  //  ★ inout[8*i+j] → inout[8*lane_id+j]
  regs[0] = inout[8 * lane_id];
  regs[1] = inout[8 * lane_id + 1];
  regs[2] = inout[8 * lane_id + 2];
  regs[3] = inout[8 * lane_id + 3];
  regs[4] = inout[8 * lane_id + 4];
  regs[5] = inout[8 * lane_id + 5];
  regs[6] = inout[8 * lane_id + 6];
  regs[7] = inout[8 * lane_id + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);
  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);
  CTinout[0] = regs[0];
  CTinout[1] = regs[1];
  CTinout[2] = regs[2];
  CTinout[3] = regs[3];
  CTinout[4] = regs[4];
  CTinout[5] = regs[5];
  CTinout[6] = regs[6];
  CTinout[7] = regs[7];

  // ================== 2. ctRone =
  // CTinoutA（预计算，直接读，不偏移）==================
  CTinoutA[0] = inoutAct[8 * lane_id];
  CTinoutA[1] = inoutAct[8 * lane_id + 1];
  CTinoutA[2] = inoutAct[8 * lane_id + 2];
  CTinoutA[3] = inoutAct[8 * lane_id + 3];
  CTinoutA[4] = inoutAct[8 * lane_id + 4];
  CTinoutA[5] = inoutAct[8 * lane_id + 5];
  CTinoutA[6] = inoutAct[8 * lane_id + 6];
  CTinoutA[7] = inoutAct[8 * lane_id + 7];

  // ================== 3. x*negmodn ==================
  register uint64_t Aa1[8];
  for (int j = 0; j < 8; j++)
    Aa1[j] =
        multiply_and_reduce_shoup_lazy(CTinout[j], negmodn[8 * lane_id + j],
                                       negmodn_shoup[8 * lane_id + j], mod);

  // ================== 4. ICT Aa1 ==================
  regs[0] = Aa1[0];
  regs[1] = Aa1[1];
  regs[2] = Aa1[2];
  regs[3] = Aa1[3];
  regs[4] = Aa1[4];
  regs[5] = Aa1[5];
  regs[6] = Aa1[6];
  regs[7] = Aa1[7];
  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup = 1 << 7;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Aa1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 5. modr Aa1 ==================
  int u = 17;
  const uint64_t mod_mask = (1ULL << u) - 1;
  register uint64_t regs0[8], regs1[8], regs3[8], regs4[8];
  register uint64_t new_regs3[8], new_regs4[8];
  register uint64_t sum[8], prev_sum[8], tail[8];

  for (int j = 0; j < 8; j++) regs0[j] = Aa1[j] >> u;
  for (int j = 0; j < 8; j++) regs1[j] = Aa1[j] & mod_mask;
  for (int j = 0; j < 8; j++) regs3[j] = regs0[j] >> u;
  for (int j = 0; j < 8; j++) regs4[j] = regs0[j] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);
  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];
  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = regs1[1] + new_regs4[1];
    for (int j = 2; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);
  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  }
#pragma unroll
  for (int j = 0; j < 8; j++) tail[j] = (sum[j] & mod_mask) + prev_sum[j];

  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }
  uint64_t stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  warp_c=lc;
  #pragma unroll
  for(int offset=1;offset<32;offset<<=1){
      uint64_t t=__shfl_up_sync(0xffffffff,warp_c,offset);
      if(lane_id>=(uint32_t)offset) warp_c+=t;
  }
  incoming_c=__shfl_up_sync(0xffffffff,warp_c,1);
  if(lane_id==0) incoming_c=0;
  tail[0]+=incoming_c;

  lc=0;
  #pragma unroll
  for(int j=0;j<8;j++){ tail[j]+=lc; lc=tail[j]>>u; tail[j]&=mod_mask; }
  uint64_t stage3_carry=__shfl_sync(0xffffffff,lc,31);
  */
  uint64_t accumulated_wrap = 0;

  uint32_t active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  uint64_t final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;
    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;
    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;
    tail[2] = (tail[2] + cay1) & mod_mask;
  }

  // ================== 6. CT Aa1 ==================
  regs[0] = tail[0];
  regs[1] = tail[1];
  regs[2] = tail[2];
  regs[3] = tail[3];
  regs[4] = tail[4];
  regs[5] = tail[5];
  regs[6] = tail[6];
  regs[7] = tail[7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);
  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  // ================== 7. CT(Aa1)*CTinoutA ==================
  register uint64_t Mm1[8];
  for (int j = 0; j < 8; j++)
    Mm1[j] =
        multiply_and_reduce_shoup_lazy_dotproduct(regs[j], CTinoutA[j], mod);

  // ================== 8. ICT Mm1 ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];
  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup = 1 << 7;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Mm1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 9. modr Mm1 ==================
  for (int j = 0; j < 8; j++) regs0[j] = Mm1[j] >> u;
  for (int j = 0; j < 8; j++) regs1[j] = Mm1[j] & mod_mask;
  for (int j = 0; j < 8; j++) regs3[j] = regs0[j] >> u;
  for (int j = 0; j < 8; j++) regs4[j] = regs0[j] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);
  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];
  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = regs1[1] + new_regs4[1];
    for (int j = 2; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);
  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  }
#pragma unroll
  for (int j = 0; j < 8; j++) tail[j] = (sum[j] & mod_mask) + prev_sum[j];

  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }
  stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  warp_c=lc;
  #pragma unroll
  for(int offset=1;offset<32;offset<<=1){
      uint64_t t=__shfl_up_sync(0xffffffff,warp_c,offset);
      if(lane_id>=(uint32_t)offset) warp_c+=t;
  }
  incoming_c=__shfl_up_sync(0xffffffff,warp_c,1);
  if(lane_id==0) incoming_c=0;
  tail[0]+=incoming_c;

  lc=0;
  #pragma unroll
  for(int j=0;j<8;j++){ tail[j]+=lc; lc=tail[j]>>u; tail[j]&=mod_mask; }
  stage3_carry=__shfl_sync(0xffffffff,lc,31);
  */
  accumulated_wrap = 0;

  active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;
    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;
    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;
    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  for (int j = 0; j < 8; j++) Mm1[j] = tail[j];

  // ================== 10. NCT inout ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  regs[0] = inout[8 * lane_id];
  regs[1] = inout[8 * lane_id + 1];
  regs[2] = inout[8 * lane_id + 2];
  regs[3] = inout[8 * lane_id + 3];
  regs[4] = inout[8 * lane_id + 4];
  regs[5] = inout[8 * lane_id + 5];
  regs[6] = inout[8 * lane_id + 6];
  regs[7] = inout[8 * lane_id + 7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  NCTinout[0] = regs[0];
  NCTinout[1] = regs[1];
  NCTinout[2] = regs[2];
  NCTinout[3] = regs[3];
  NCTinout[4] = regs[4];
  NCTinout[5] = regs[5];
  NCTinout[6] = regs[6];
  NCTinout[7] = regs[7];

  // ================== 11. NCT Mm1 ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  for (int j = 0; j < 8; j++) Mm1[j] = regs[j];

  // ================== 12. nctRone =
  // NCTinoutA（预计算，直接读，不偏移）==================
  NCTinoutA[0] = inoutAnct[8 * lane_id];
  NCTinoutA[1] = inoutAnct[8 * lane_id + 1];
  NCTinoutA[2] = inoutAnct[8 * lane_id + 2];
  NCTinoutA[3] = inoutAnct[8 * lane_id + 3];
  NCTinoutA[4] = inoutAnct[8 * lane_id + 4];
  NCTinoutA[5] = inoutAnct[8 * lane_id + 5];
  NCTinoutA[6] = inoutAnct[8 * lane_id + 6];
  NCTinoutA[7] = inoutAnct[8 * lane_id + 7];

  // ================== 13. Gx ==================
  register uint64_t Gx[8];
  for (int j = 0; j < 8; j++) {
    uint64_t tmp1 = multiply_and_reduce_shoup_lazy_dotproduct(NCTinoutA[j],
                                                              NCTinout[j], mod);
    uint64_t tmp2 = multiply_and_reduce_shoup_lazy(
        Mm1[j], modn[8 * lane_id + j], modn_shoup[8 * lane_id + j], mod);
    Gx[j] = (tmp1 + tmp2) % MOD;
  }

  // ================== 14. INCT Gx ==================
  regs[0] = Gx[0];
  regs[1] = Gx[1];
  regs[2] = Gx[2];
  regs[3] = Gx[3];
  regs[4] = Gx[4];
  regs[5] = Gx[5];
  regs[6] = Gx[6];
  regs[7] = Gx[7];
  gs_butterfly(regs[0], regs[1], InvNCTtwiddle[128 + 4 * lane_id],
               InvNCTtwiddle_shoup[128 + 4 * lane_id], mod);
  gs_butterfly(regs[2], regs[3], InvNCTtwiddle[128 + 4 * lane_id + 1],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  gs_butterfly(regs[4], regs[5], InvNCTtwiddle[128 + 4 * lane_id + 2],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  gs_butterfly(regs[6], regs[7], InvNCTtwiddle[128 + 4 * lane_id + 3],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  gs_butterfly(regs[0], regs[2], InvNCTtwiddle[64 + lane_id * 2],
               InvNCTtwiddle_shoup[64 + lane_id * 2], mod);
  gs_butterfly(regs[1], regs[3], InvNCTtwiddle[64 + lane_id * 2],
               InvNCTtwiddle_shoup[64 + lane_id * 2], mod);
  gs_butterfly(regs[4], regs[6], InvNCTtwiddle[64 + lane_id * 2 + 1],
               InvNCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  gs_butterfly(regs[5], regs[7], InvNCTtwiddle[64 + lane_id * 2 + 1],
               InvNCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  gs_butterfly(regs[0], regs[4], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[1], regs[5], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[2], regs[6], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[3], regs[7], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = (((8 * lane_id) & 0xFF) / pair2) + numOfGroups;
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup_inv = 1 << 7;
    uint64_t pair2_inv = pairsInGroup_inv << 1;
    uint64_t numOfGroups_inv = 128 / pairsInGroup_inv;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = (((8 * lane_id) & 0xFF) / pair2_inv) + numOfGroups_inv;
    omegnIdx[1] = numOfGroups_inv + (((8 * lane_id + 1) & 0xFF) / pair2_inv);
    omegnIdx[2] = numOfGroups_inv + (((8 * lane_id + 2) & 0xFF) / pair2_inv);
    omegnIdx[3] = numOfGroups_inv + (((8 * lane_id + 3) & 0xFF) / pair2_inv);
    omegnIdx[4] = numOfGroups_inv + (((8 * lane_id + 4) & 0xFF) / pair2_inv);
    omegnIdx[5] = numOfGroups_inv + (((8 * lane_id + 5) & 0xFF) / pair2_inv);
    omegnIdx[6] = numOfGroups_inv + (((8 * lane_id + 6) & 0xFF) / pair2_inv);
    omegnIdx[7] = numOfGroups_inv + (((8 * lane_id + 7) & 0xFF) / pair2_inv);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Gx[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 15. modh Gx ==================
  register int64_t sregs0[8], sregs[8], sregs1[8], sregs3[8], sregs4[8];
  register int64_t snew_regs3[8], snew_regs4[8];
  register int64_t ssum[8], sprev_sum[8], stail[8];
  register uint64_t DivMod[8];

  // 1. 获取带符号的初始值
  sregs0[0] = (Gx[0] > sample[8 * lane_id])
                  ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[0]);
  sregs0[1] = (Gx[1] > sample[(8 * lane_id + 1) & 0xFF])
                  ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[1]);
  sregs0[2] = (Gx[2] > sample[(8 * lane_id + 2) & 0xFF])
                  ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[2]);
  sregs0[3] = (Gx[3] > sample[(8 * lane_id + 3) & 0xFF])
                  ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[3]);
  sregs0[4] = (Gx[4] > sample[(8 * lane_id + 4) & 0xFF])
                  ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[4]);
  sregs0[5] = (Gx[5] > sample[(8 * lane_id + 5) & 0xFF])
                  ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[5]);
  sregs0[6] = (Gx[6] > sample[(8 * lane_id + 6) & 0xFF])
                  ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[6]);
  sregs0[7] = (Gx[7] > sample[(8 * lane_id + 7) & 0xFF])
                  ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[7]);

// 利用算术右移自动保留符号位
#pragma unroll
  for (int j = 0; j < 8; j++) {
    sregs[j] = sregs0[j] >> u;
    sregs1[j] = sregs0[j] & mod_mask;
    sregs3[j] = sregs[j] >> u;
    sregs4[j] = sregs[j] & mod_mask;
  }

  sretail_0 = __shfl_sync(0xffffffff, sregs3[6] + sregs4[7], 31);
  sretail_1 = __shfl_sync(0xffffffff, sregs3[7], 31);

  snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
  snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
  snew_regs3[2] = sregs3[0];
  snew_regs3[3] = sregs3[1];
  snew_regs3[4] = sregs3[2];
  snew_regs3[5] = sregs3[3];
  snew_regs3[6] = sregs3[4];
  snew_regs3[7] = sregs3[5];

  snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
  snew_regs4[1] = sregs4[0];
  snew_regs4[2] = sregs4[1];
  snew_regs4[3] = sregs4[2];
  snew_regs4[4] = sregs4[3];
  snew_regs4[5] = sregs4[4];
  snew_regs4[6] = sregs4[5];
  snew_regs4[7] = sregs4[6];

  if (lane_id == 0) {
    ssum[0] = sregs1[0];
    ssum[1] = (sregs1[1] + snew_regs4[1]);
    for (int j = 2; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  }

  scarry_wrap = __shfl_sync(0xffffffff, ssum[7] >> u, 31);
  stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

  if (lane_id == 0) {
    sprev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  } else {
    sprev_sum[0] = stemp_shuffled;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] = (ssum[j] & mod_mask) + sprev_sum[j];
  }

  // =========================================================================
  // ★ 核心修复：Stage 1 & 2 使用 Ballot While 循环涟漪进位，替代错误的前缀和
  // =========================================================================
  slc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] += slc;
    slc = stail[j] >> u;
    stail[j] &= mod_mask;
  }

  int64_t accumulated_lane31_carry =
      0;  // 专门捕捉所有从最高位（lane 31）溢出的最终进位/借位
  active = __ballot_sync(0xffffffff, slc != 0);

  // 只要有任何一个线程还有进位/借位没消化，整个 Warp 就继续同步传递
  while (active != 0) {
    if (lane_id == 31) {
      accumulated_lane31_carry += slc;
    }

    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;  // 最低位暂时不回卷

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;  // 算术右移完美处理负数借位
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // 获取从最高位最终溢出/借位的所有总量
  int64_t final_carry = __shfl_sync(0xffffffff, accumulated_lane31_carry, 31);

  // =========================================================================
  // ★ 核心修复：Stage 3 (Mod H 负向回卷)
  // =========================================================================
  slc = 0;
  if (lane_id == 0) {
    // 对于模 h (2^4352 + 1)，最高位的进位溢出权重大于 0，等价于从最低位减去。
    // 总溢出 = sretail_0 + scarry_wrap + final_carry
    int64_t total_wrap_0 = sretail_0 + scarry_wrap + final_carry;

    int64_t flag = stail[0] - total_wrap_0;
    int64_t negcarry = flag >> u;
    stail[0] = flag & mod_mask;

    flag = stail[1] - sretail_1 + negcarry;
    negcarry = flag >> u;
    stail[1] = flag & mod_mask;

    // 让借位顺着 lane_id 0 往上走，走到没有为止
    for (int j = 2; j < 8; j++) {
      flag = stail[j] + negcarry;
      negcarry = flag >> u;
      stail[j] = flag & mod_mask;
    }

    slc = negcarry;  // 如果 lane 0 扣完 8 个元素后还欠借位，扔给后面的线程
  }

  // 再次开启涟漪循环，彻底消化回卷带来的多米诺借位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // =========================================================================
  // Stage 4: 计算最终的 w = (h - g) / 2
  // =========================================================================
  uint64_t maxNum = (1ULL << u) - 1;
  if (lane_id == 0) {
    // 这一步等价于取补码 + 2
    stail[0] = maxNum + 2 - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  } else {
    stail[0] = maxNum - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  }

  // ★ 修复漏洞：maxNum+2-stail[0] 如果 stail[0] 极小，会导致超过 17
  // 位限制产生进位
  slc = 0;
  if (lane_id == 0) {
    for (int j = 0; j < 8; j++) {
      stail[j] += slc;
      slc = stail[j] >> u;
      stail[j] &= mod_mask;
    }
  }
  // 传播这最后一丝极小的正向进位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;
    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
  if (lane_id == 31) {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = 0;
  } else {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
  }

  stail[0] = (stail[0] / 2) + DivMod[0];
  stail[1] = (stail[1] / 2) + DivMod[1];
  stail[2] = (stail[2] / 2) + DivMod[2];
  stail[3] = (stail[3] / 2) + DivMod[3];
  stail[4] = (stail[4] / 2) + DivMod[4];
  stail[5] = (stail[5] / 2) + DivMod[5];
  stail[6] = (stail[6] / 2) + DivMod[6];
  stail[7] = (stail[7] / 2) + DivMod[7];

  // ================== 16. 写回 ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  for (int j = 0; j < 8; j++)
    inout[8 * lane_id + j] = static_cast<uint64_t>(stail[j]);
}

// end device xr1 2baneben

// start device xx
__device__ __forceinline__ void XYfixWarpSquareVector_dev(
    uint64_t *inout, uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n, uint64_t mod,
    const __restrict__ uint64_t *twiddle,
    const __restrict__ uint64_t *twiddle_shoup,
    const __restrict__ uint64_t *ICTTwiddle,
    const __restrict__ uint64_t *ICTTwiddle_shoup,
    const __restrict__ uint64_t *NCTtwiddle,
    const __restrict__ uint64_t *NCTtwiddle_shoup,
    const __restrict__ uint64_t *InvNCTtwiddle,
    const __restrict__ uint64_t *InvNCTtwiddle_shoup,
    const __restrict__ uint64_t inv, const __restrict__ uint64_t inv_shoup,
    const __restrict__ uint64_t *sample) {
  // ★ 唯一修改：去掉全局索引 i，改用 lane_id
  uint32_t lane_id = threadIdx.x & 0x1F;

  register uint64_t CTinout[8];
  register uint64_t NCTinout[8];
  register uint64_t regs[8];
  register uint64_t new_regs[8];
  register uint64_t C;
  register uint32_t omegnIdx[8];

  uint64_t retail_0, retail_1, carry_wrap, temp_shuffled;
  uint64_t lc;
  int64_t sretail_0, sretail_1, scarry_wrap, stemp_shuffled;
  int64_t slc;
  // int64_t swarp_c,  sincoming_c;

  // ================== 1. CT inout ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  regs[0] = inout[8 * lane_id];
  regs[1] = inout[8 * lane_id + 1];
  regs[2] = inout[8 * lane_id + 2];
  regs[3] = inout[8 * lane_id + 3];
  regs[4] = inout[8 * lane_id + 4];
  regs[5] = inout[8 * lane_id + 5];
  regs[6] = inout[8 * lane_id + 6];
  regs[7] = inout[8 * lane_id + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);
  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);
  CTinout[0] = regs[0];
  CTinout[1] = regs[1];
  CTinout[2] = regs[2];
  CTinout[3] = regs[3];
  CTinout[4] = regs[4];
  CTinout[5] = regs[5];
  CTinout[6] = regs[6];
  CTinout[7] = regs[7];

  // ================== 2. Section 2 为空（平方不需要独立
  // CTinoutA）==================

  // ================== 3. x*negmodn ==================
  register uint64_t Aa1[8];
  for (int j = 0; j < 8; j++)
    Aa1[j] =
        multiply_and_reduce_shoup_lazy(CTinout[j], negmodn[8 * lane_id + j],
                                       negmodn_shoup[8 * lane_id + j], mod);

  // ================== 4. ICT Aa1 ==================
  regs[0] = Aa1[0];
  regs[1] = Aa1[1];
  regs[2] = Aa1[2];
  regs[3] = Aa1[3];
  regs[4] = Aa1[4];
  regs[5] = Aa1[5];
  regs[6] = Aa1[6];
  regs[7] = Aa1[7];
  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup = 1 << 7;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Aa1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 5. modr Aa1 ==================
  int u = 17;
  const uint64_t mod_mask = (1ULL << u) - 1;
  register uint64_t regs0[8], regs1[8], regs3[8], regs4[8];
  register uint64_t new_regs3[8], new_regs4[8];
  register uint64_t sum[8], prev_sum[8], tail[8];

  for (int j = 0; j < 8; j++) regs0[j] = Aa1[j] >> u;
  for (int j = 0; j < 8; j++) regs1[j] = Aa1[j] & mod_mask;
  for (int j = 0; j < 8; j++) regs3[j] = regs0[j] >> u;
  for (int j = 0; j < 8; j++) regs4[j] = regs0[j] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);
  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];
  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = regs1[1] + new_regs4[1];
    for (int j = 2; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);
  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  }
#pragma unroll
  for (int j = 0; j < 8; j++) tail[j] = (sum[j] & mod_mask) + prev_sum[j];

  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }
  uint64_t stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  warp_c=lc;
  #pragma unroll
  for(int offset=1;offset<32;offset<<=1){
      uint64_t t=__shfl_up_sync(0xffffffff,warp_c,offset);
      if(lane_id>=(uint32_t)offset) warp_c+=t;
  }
  incoming_c=__shfl_up_sync(0xffffffff,warp_c,1);
  if(lane_id==0) incoming_c=0;
  tail[0]+=incoming_c;

  lc=0;
  #pragma unroll
  for(int j=0;j<8;j++){ tail[j]+=lc; lc=tail[j]>>u; tail[j]&=mod_mask; }
  uint64_t stage3_carry=__shfl_sync(0xffffffff,lc,31);
  */
  uint64_t accumulated_wrap = 0;

  uint32_t active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  uint64_t final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;
    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;
    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;
    tail[2] = (tail[2] + cay1) & mod_mask;
  }

  // ================== 6. CT Aa1 ==================
  regs[0] = tail[0];
  regs[1] = tail[1];
  regs[2] = tail[2];
  regs[3] = tail[3];
  regs[4] = tail[4];
  regs[5] = tail[5];
  regs[6] = tail[6];
  regs[7] = tail[7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);
  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);

  // ================== 7. CT(Aa1)*CTinout（平方：y=x，直接用
  // CTinout）==================
  register uint64_t Mm1[8];
  for (int j = 0; j < 8; j++)
    Mm1[j] =
        multiply_and_reduce_shoup_lazy_dotproduct(regs[j], CTinout[j], mod);

  // ================== 8. ICT Mm1 ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];
  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup = 1 << 7;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Mm1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 9. modr Mm1 ==================
  for (int j = 0; j < 8; j++) regs0[j] = Mm1[j] >> u;
  for (int j = 0; j < 8; j++) regs1[j] = Mm1[j] & mod_mask;
  for (int j = 0; j < 8; j++) regs3[j] = regs0[j] >> u;
  for (int j = 0; j < 8; j++) regs4[j] = regs0[j] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);
  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];
  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = regs1[1] + new_regs4[1];
    for (int j = 2; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);
  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  }
#pragma unroll
  for (int j = 0; j < 8; j++) tail[j] = (sum[j] & mod_mask) + prev_sum[j];

  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }
  stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  warp_c=lc;
  #pragma unroll
  for(int offset=1;offset<32;offset<<=1){
      uint64_t t=__shfl_up_sync(0xffffffff,warp_c,offset);
      if(lane_id>=(uint32_t)offset) warp_c+=t;
  }
  incoming_c=__shfl_up_sync(0xffffffff,warp_c,1);
  if(lane_id==0) incoming_c=0;
  tail[0]+=incoming_c;

  lc=0;
  #pragma unroll
  for(int j=0;j<8;j++){ tail[j]+=lc; lc=tail[j]>>u; tail[j]&=mod_mask; }
  stage3_carry=__shfl_sync(0xffffffff,lc,31);
  */
  accumulated_wrap = 0;

  active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;
    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;
    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;
    tail[2] = (tail[2] + cay1) & mod_mask;
  }
  for (int j = 0; j < 8; j++) Mm1[j] = tail[j];

  // ================== 10. NCT inout ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  regs[0] = inout[8 * lane_id];
  regs[1] = inout[8 * lane_id + 1];
  regs[2] = inout[8 * lane_id + 2];
  regs[3] = inout[8 * lane_id + 3];
  regs[4] = inout[8 * lane_id + 4];
  regs[5] = inout[8 * lane_id + 5];
  regs[6] = inout[8 * lane_id + 6];
  regs[7] = inout[8 * lane_id + 7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  NCTinout[0] = regs[0];
  NCTinout[1] = regs[1];
  NCTinout[2] = regs[2];
  NCTinout[3] = regs[3];
  NCTinout[4] = regs[4];
  NCTinout[5] = regs[5];
  NCTinout[6] = regs[6];
  NCTinout[7] = regs[7];

  // ================== 11. NCT Mm1 ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  for (int j = 0; j < 8; j++) Mm1[j] = regs[j];

  // ================== 12. Section 12 为空（平方不需要独立
  // NCTinoutA）==================

  // ================== 13. Gx = NCT(x)*NCT(x) +
  // NCT(m)*N（平方：y=x）==================
  register uint64_t Gx[8];
  for (int j = 0; j < 8; j++) {
    uint64_t tmp1 = multiply_and_reduce_shoup_lazy_dotproduct(NCTinout[j],
                                                              NCTinout[j], mod);
    uint64_t tmp2 = multiply_and_reduce_shoup_lazy(
        Mm1[j], modn[8 * lane_id + j], modn_shoup[8 * lane_id + j], mod);
    Gx[j] = (tmp1 + tmp2) % MOD;
  }

  // ================== 14. INCT Gx ==================
  regs[0] = Gx[0];
  regs[1] = Gx[1];
  regs[2] = Gx[2];
  regs[3] = Gx[3];
  regs[4] = Gx[4];
  regs[5] = Gx[5];
  regs[6] = Gx[6];
  regs[7] = Gx[7];
  gs_butterfly(regs[0], regs[1], InvNCTtwiddle[128 + 4 * lane_id],
               InvNCTtwiddle_shoup[128 + 4 * lane_id], mod);
  gs_butterfly(regs[2], regs[3], InvNCTtwiddle[128 + 4 * lane_id + 1],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  gs_butterfly(regs[4], regs[5], InvNCTtwiddle[128 + 4 * lane_id + 2],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  gs_butterfly(regs[6], regs[7], InvNCTtwiddle[128 + 4 * lane_id + 3],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  gs_butterfly(regs[0], regs[2], InvNCTtwiddle[64 + lane_id * 2],
               InvNCTtwiddle_shoup[64 + lane_id * 2], mod);
  gs_butterfly(regs[1], regs[3], InvNCTtwiddle[64 + lane_id * 2],
               InvNCTtwiddle_shoup[64 + lane_id * 2], mod);
  gs_butterfly(regs[4], regs[6], InvNCTtwiddle[64 + lane_id * 2 + 1],
               InvNCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  gs_butterfly(regs[5], regs[7], InvNCTtwiddle[64 + lane_id * 2 + 1],
               InvNCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  gs_butterfly(regs[0], regs[4], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[1], regs[5], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[2], regs[6], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[3], regs[7], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = (((8 * lane_id) & 0xFF) / pair2) + numOfGroups;
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup_inv = 1 << 7;
    uint64_t pair2_inv = pairsInGroup_inv << 1;
    uint64_t numOfGroups_inv = 128 / pairsInGroup_inv;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = (((8 * lane_id) & 0xFF) / pair2_inv) + numOfGroups_inv;
    omegnIdx[1] = numOfGroups_inv + (((8 * lane_id + 1) & 0xFF) / pair2_inv);
    omegnIdx[2] = numOfGroups_inv + (((8 * lane_id + 2) & 0xFF) / pair2_inv);
    omegnIdx[3] = numOfGroups_inv + (((8 * lane_id + 3) & 0xFF) / pair2_inv);
    omegnIdx[4] = numOfGroups_inv + (((8 * lane_id + 4) & 0xFF) / pair2_inv);
    omegnIdx[5] = numOfGroups_inv + (((8 * lane_id + 5) & 0xFF) / pair2_inv);
    omegnIdx[6] = numOfGroups_inv + (((8 * lane_id + 6) & 0xFF) / pair2_inv);
    omegnIdx[7] = numOfGroups_inv + (((8 * lane_id + 7) & 0xFF) / pair2_inv);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Gx[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 15. modh Gx ==================
  register int64_t sregs0[8], sregs[8], sregs1[8], sregs3[8], sregs4[8];
  register int64_t snew_regs3[8], snew_regs4[8];
  register int64_t ssum[8], sprev_sum[8], stail[8];
  register uint64_t DivMod[8];

  // 1. 获取带符号的初始值
  sregs0[0] = (Gx[0] > sample[8 * lane_id])
                  ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[0]);
  sregs0[1] = (Gx[1] > sample[(8 * lane_id + 1) & 0xFF])
                  ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[1]);
  sregs0[2] = (Gx[2] > sample[(8 * lane_id + 2) & 0xFF])
                  ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[2]);
  sregs0[3] = (Gx[3] > sample[(8 * lane_id + 3) & 0xFF])
                  ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[3]);
  sregs0[4] = (Gx[4] > sample[(8 * lane_id + 4) & 0xFF])
                  ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[4]);
  sregs0[5] = (Gx[5] > sample[(8 * lane_id + 5) & 0xFF])
                  ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[5]);
  sregs0[6] = (Gx[6] > sample[(8 * lane_id + 6) & 0xFF])
                  ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[6]);
  sregs0[7] = (Gx[7] > sample[(8 * lane_id + 7) & 0xFF])
                  ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[7]);

// 利用算术右移自动保留符号位
#pragma unroll
  for (int j = 0; j < 8; j++) {
    sregs[j] = sregs0[j] >> u;
    sregs1[j] = sregs0[j] & mod_mask;
    sregs3[j] = sregs[j] >> u;
    sregs4[j] = sregs[j] & mod_mask;
  }

  sretail_0 = __shfl_sync(0xffffffff, sregs3[6] + sregs4[7], 31);
  sretail_1 = __shfl_sync(0xffffffff, sregs3[7], 31);

  snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
  snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
  snew_regs3[2] = sregs3[0];
  snew_regs3[3] = sregs3[1];
  snew_regs3[4] = sregs3[2];
  snew_regs3[5] = sregs3[3];
  snew_regs3[6] = sregs3[4];
  snew_regs3[7] = sregs3[5];

  snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
  snew_regs4[1] = sregs4[0];
  snew_regs4[2] = sregs4[1];
  snew_regs4[3] = sregs4[2];
  snew_regs4[4] = sregs4[3];
  snew_regs4[5] = sregs4[4];
  snew_regs4[6] = sregs4[5];
  snew_regs4[7] = sregs4[6];

  if (lane_id == 0) {
    ssum[0] = sregs1[0];
    ssum[1] = (sregs1[1] + snew_regs4[1]);
    for (int j = 2; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  }

  scarry_wrap = __shfl_sync(0xffffffff, ssum[7] >> u, 31);
  stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

  if (lane_id == 0) {
    sprev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  } else {
    sprev_sum[0] = stemp_shuffled;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] = (ssum[j] & mod_mask) + sprev_sum[j];
  }

  // =========================================================================
  // ★ 核心修复：Stage 1 & 2 使用 Ballot While 循环涟漪进位，替代错误的前缀和
  // =========================================================================
  slc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] += slc;
    slc = stail[j] >> u;
    stail[j] &= mod_mask;
  }

  int64_t accumulated_lane31_carry =
      0;  // 专门捕捉所有从最高位（lane 31）溢出的最终进位/借位
  active = __ballot_sync(0xffffffff, slc != 0);

  // 只要有任何一个线程还有进位/借位没消化，整个 Warp 就继续同步传递
  while (active != 0) {
    if (lane_id == 31) {
      accumulated_lane31_carry += slc;
    }

    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;  // 最低位暂时不回卷

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;  // 算术右移完美处理负数借位
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // 获取从最高位最终溢出/借位的所有总量
  int64_t final_carry = __shfl_sync(0xffffffff, accumulated_lane31_carry, 31);

  // =========================================================================
  // ★ 核心修复：Stage 3 (Mod H 负向回卷)
  // =========================================================================
  slc = 0;
  if (lane_id == 0) {
    // 对于模 h (2^4352 + 1)，最高位的进位溢出权重大于 0，等价于从最低位减去。
    // 总溢出 = sretail_0 + scarry_wrap + final_carry
    int64_t total_wrap_0 = sretail_0 + scarry_wrap + final_carry;

    int64_t flag = stail[0] - total_wrap_0;
    int64_t negcarry = flag >> u;
    stail[0] = flag & mod_mask;

    flag = stail[1] - sretail_1 + negcarry;
    negcarry = flag >> u;
    stail[1] = flag & mod_mask;

    // 让借位顺着 lane_id 0 往上走，走到没有为止
    for (int j = 2; j < 8; j++) {
      flag = stail[j] + negcarry;
      negcarry = flag >> u;
      stail[j] = flag & mod_mask;
    }

    slc = negcarry;  // 如果 lane 0 扣完 8 个元素后还欠借位，扔给后面的线程
  }

  // 再次开启涟漪循环，彻底消化回卷带来的多米诺借位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // =========================================================================
  // Stage 4: 计算最终的 w = (h - g) / 2
  // =========================================================================
  uint64_t maxNum = (1ULL << u) - 1;
  if (lane_id == 0) {
    // 这一步等价于取补码 + 2
    stail[0] = maxNum + 2 - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  } else {
    stail[0] = maxNum - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  }

  // ★ 修复漏洞：maxNum+2-stail[0] 如果 stail[0] 极小，会导致超过 17
  // 位限制产生进位
  slc = 0;
  if (lane_id == 0) {
    for (int j = 0; j < 8; j++) {
      stail[j] += slc;
      slc = stail[j] >> u;
      stail[j] &= mod_mask;
    }
  }
  // 传播这最后一丝极小的正向进位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;
    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
  if (lane_id == 31) {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = 0;
  } else {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
  }

  stail[0] = (stail[0] / 2) + DivMod[0];
  stail[1] = (stail[1] / 2) + DivMod[1];
  stail[2] = (stail[2] / 2) + DivMod[2];
  stail[3] = (stail[3] / 2) + DivMod[3];
  stail[4] = (stail[4] / 2) + DivMod[4];
  stail[5] = (stail[5] / 2) + DivMod[5];
  stail[6] = (stail[6] / 2) + DivMod[6];
  stail[7] = (stail[7] / 2) + DivMod[7];

  // ================== 16. 写回 ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  for (int j = 0; j < 8; j++)
    inout[8 * lane_id + j] = static_cast<uint64_t>(stail[j]);
}

// end device xx

// start device x1
__device__ __forceinline__ void XYfixWarpIRVector_dev(
    uint64_t *inout, uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n, uint64_t mod,
    const __restrict__ uint64_t *twiddle,
    const __restrict__ uint64_t *twiddle_shoup,
    const __restrict__ uint64_t *ICTTwiddle,
    const __restrict__ uint64_t *ICTTwiddle_shoup,
    const __restrict__ uint64_t *NCTtwiddle,
    const __restrict__ uint64_t *NCTtwiddle_shoup,
    const __restrict__ uint64_t *InvNCTtwiddle,
    const __restrict__ uint64_t *InvNCTtwiddle_shoup,
    const __restrict__ uint64_t inv, const __restrict__ uint64_t inv_shoup,
    const __restrict__ uint64_t *sample) {
  // ★ 唯一修改：去掉全局索引 i，改用 lane_id
  uint32_t lane_id = threadIdx.x & 0x1F;

  register uint64_t CTinout[8];
  register uint64_t NCTinout[8];
  register uint64_t regs[8];
  register uint64_t new_regs[8];
  register uint64_t C;
  register uint32_t omegnIdx[8];

  uint64_t retail_0, retail_1, carry_wrap, temp_shuffled;
  uint64_t lc;
  int64_t sretail_0, sretail_1, scarry_wrap, stemp_shuffled;
  int64_t slc;
  // int64_t swarp_c, sincoming_c;

  // ================== 1. CT inout ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  regs[0] = inout[8 * lane_id];
  regs[1] = inout[8 * lane_id + 1];
  regs[2] = inout[8 * lane_id + 2];
  regs[3] = inout[8 * lane_id + 3];
  regs[4] = inout[8 * lane_id + 4];
  regs[5] = inout[8 * lane_id + 5];
  regs[6] = inout[8 * lane_id + 6];
  regs[7] = inout[8 * lane_id + 7];

  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, twiddle[omegnIdx[j]], twiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  gs_butterfly(regs[0], regs[4], twiddle[4], twiddle_shoup[4], mod);
  gs_butterfly(regs[1], regs[5], twiddle[5], twiddle_shoup[5], mod);
  gs_butterfly(regs[2], regs[6], twiddle[6], twiddle_shoup[6], mod);
  gs_butterfly(regs[3], regs[7], twiddle[7], twiddle_shoup[7], mod);
  gs_butterfly(regs[0], regs[2], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[1], regs[3], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[4], regs[6], twiddle[2], twiddle_shoup[2], mod);
  gs_butterfly(regs[5], regs[7], twiddle[3], twiddle_shoup[3], mod);
  gs_butterfly(regs[0], regs[1], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[2], regs[3], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[4], regs[5], twiddle[1], twiddle_shoup[1], mod);
  gs_butterfly(regs[6], regs[7], twiddle[1], twiddle_shoup[1], mod);
  CTinout[0] = regs[0];
  CTinout[1] = regs[1];
  CTinout[2] = regs[2];
  CTinout[3] = regs[3];
  CTinout[4] = regs[4];
  CTinout[5] = regs[5];
  CTinout[6] = regs[6];
  CTinout[7] = regs[7];

  // ================== 2. Section 2
  // 为空（IR：y=1，无需单独CT(y)）==================

  // ================== 3. x*negmodn ==================
  register uint64_t Aa1[8];
  register uint64_t Mm1[8];

  for (int j = 0; j < 8; j++)
    Aa1[j] =
        multiply_and_reduce_shoup_lazy(CTinout[j], negmodn[8 * lane_id + j],
                                       negmodn_shoup[8 * lane_id + j], mod);

  // ================== 4. ICT Aa1 ==================
  regs[0] = Aa1[0];
  regs[1] = Aa1[1];
  regs[2] = Aa1[2];
  regs[3] = Aa1[3];
  regs[4] = Aa1[4];
  regs[5] = Aa1[5];
  regs[6] = Aa1[6];
  regs[7] = Aa1[7];
  ct_butterfly(regs[0], regs[1], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[2], regs[3], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[4], regs[5], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[6], regs[7], ICTTwiddle[1], ICTTwiddle_shoup[1], mod);
  ct_butterfly(regs[0], regs[2], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[1], regs[3], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[4], regs[6], ICTTwiddle[2], ICTTwiddle_shoup[2], mod);
  ct_butterfly(regs[5], regs[7], ICTTwiddle[3], ICTTwiddle_shoup[3], mod);
  ct_butterfly(regs[0], regs[4], ICTTwiddle[4], ICTTwiddle_shoup[4], mod);
  ct_butterfly(regs[1], regs[5], ICTTwiddle[5], ICTTwiddle_shoup[5], mod);
  ct_butterfly(regs[2], regs[6], ICTTwiddle[6], ICTTwiddle_shoup[6], mod);
  ct_butterfly(regs[3], regs[7], ICTTwiddle[7], ICTTwiddle_shoup[7], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup = 1 << 7;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = pairsInGroup + ((8 * lane_id) % pairsInGroup);
    omegnIdx[1] = pairsInGroup + ((8 * lane_id + 1) % pairsInGroup);
    omegnIdx[2] = pairsInGroup + ((8 * lane_id + 2) % pairsInGroup);
    omegnIdx[3] = pairsInGroup + ((8 * lane_id + 3) % pairsInGroup);
    omegnIdx[4] = pairsInGroup + ((8 * lane_id + 4) % pairsInGroup);
    omegnIdx[5] = pairsInGroup + ((8 * lane_id + 5) % pairsInGroup);
    omegnIdx[6] = pairsInGroup + ((8 * lane_id + 6) % pairsInGroup);
    omegnIdx[7] = pairsInGroup + ((8 * lane_id + 7) % pairsInGroup);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, ICTTwiddle[omegnIdx[j]], ICTTwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Aa1[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 5. modr Aa1 ==================
  int u = 17;
  const uint64_t mod_mask = (1ULL << u) - 1;
  register uint64_t regs0[8], regs1[8], regs3[8], regs4[8];
  register uint64_t new_regs3[8], new_regs4[8];
  register uint64_t sum[8], prev_sum[8], tail[8];

  for (int j = 0; j < 8; j++) regs0[j] = Aa1[j] >> u;
  for (int j = 0; j < 8; j++) regs1[j] = Aa1[j] & mod_mask;
  for (int j = 0; j < 8; j++) regs3[j] = regs0[j] >> u;
  for (int j = 0; j < 8; j++) regs4[j] = regs0[j] & mod_mask;

  retail_0 = __shfl_sync(0xffffffff, regs3[6] + regs4[7], 31);
  retail_1 = __shfl_sync(0xffffffff, regs3[7], 31);
  new_regs3[0] = __shfl_up_sync(0xffffffff, regs3[6], 1);
  new_regs3[1] = __shfl_up_sync(0xffffffff, regs3[7], 1);
  new_regs3[2] = regs3[0];
  new_regs3[3] = regs3[1];
  new_regs3[4] = regs3[2];
  new_regs3[5] = regs3[3];
  new_regs3[6] = regs3[4];
  new_regs3[7] = regs3[5];
  new_regs4[0] = __shfl_up_sync(0xffffffff, regs4[7], 1);
  new_regs4[1] = regs4[0];
  new_regs4[2] = regs4[1];
  new_regs4[3] = regs4[2];
  new_regs4[4] = regs4[3];
  new_regs4[5] = regs4[4];
  new_regs4[6] = regs4[5];
  new_regs4[7] = regs4[6];

  if (lane_id == 0) {
    sum[0] = regs1[0];
    sum[1] = regs1[1] + new_regs4[1];
    for (int j = 2; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  } else {
    for (int j = 0; j < 8; j++) sum[j] = new_regs3[j] + regs1[j] + new_regs4[j];
  }

  carry_wrap = __shfl_sync(0xffffffff, sum[7] >> u, 31);
  temp_shuffled = __shfl_up_sync(0xffffffff, sum[7] >> u, 1);
  if (lane_id == 0) {
    prev_sum[0] = 0;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  } else {
    prev_sum[0] = temp_shuffled;
    for (int j = 1; j < 8; j++) prev_sum[j] = sum[j - 1] >> u;
  }
#pragma unroll
  for (int j = 0; j < 8; j++) tail[j] = (sum[j] & mod_mask) + prev_sum[j];

  lc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    tail[j] += lc;
    lc = tail[j] >> u;
    tail[j] &= mod_mask;
  }
  uint64_t stage1_carry = __shfl_sync(0xffffffff, lc, 31);
  /*
  warp_c=lc;
  #pragma unroll
  for(int offset=1;offset<32;offset<<=1){
      uint64_t t=__shfl_up_sync(0xffffffff,warp_c,offset);
      if(lane_id>=(uint32_t)offset) warp_c+=t;
  }
  incoming_c=__shfl_up_sync(0xffffffff,warp_c,1);
  if(lane_id==0) incoming_c=0;
  tail[0]+=incoming_c;

  lc=0;
  #pragma unroll
  for(int j=0;j<8;j++){ tail[j]+=lc; lc=tail[j]>>u; tail[j]&=mod_mask; }
  uint64_t stage3_carry=__shfl_sync(0xffffffff,lc,31);
  */
  uint64_t accumulated_wrap = 0;

  uint32_t active = __ballot_sync(0xffffffff, lc != 0);
  while (active != 0) {
    // 收集 lane 31 溢出（用于模运算回卷）
    if (lane_id == 31) accumulated_wrap += lc;

    // 只把进位传给紧邻的下一个 lane
    uint64_t incoming = __shfl_up_sync(0xffffffff, lc, 1);
    if (lane_id == 0) incoming = 0;  // 回卷单独处理

    lc = 0;
    if (incoming != 0) {
#pragma unroll
      for (int j = 0; j < 8; j++) {
        tail[j] += incoming;
        incoming = tail[j] >> u;
        tail[j] &= mod_mask;
      }
      lc = incoming;
    }
    active = __ballot_sync(0xffffffff, lc != 0);
  }

  // 取 lane 31 累积的回卷进位
  uint64_t final_wrap = __shfl_sync(0xffffffff, accumulated_wrap, 31);

  if (lane_id == 0) {
    // uint64_t total_wrap0 = retail_0 + carry_wrap + stage1_carry +
    // stage3_carry;
    uint64_t total_wrap0 = retail_0 + carry_wrap + final_wrap;
    uint64_t cay0 = (tail[0] + total_wrap0) >> u;
    tail[0] = (tail[0] + total_wrap0) & mod_mask;
    uint64_t cay1 = (tail[1] + retail_1 + cay0) >> u;
    tail[1] = (tail[1] + retail_1 + cay0) & mod_mask;
    tail[2] = (tail[2] + cay1) & mod_mask;
  }

  // modr 结果存入 Mm1（Section 6/7/8/9 为空，IR直接用 Aa1 的 modr 结果）
  for (int j = 0; j < 8; j++) Mm1[j] = tail[j];

  // ================== 10. NCT inout ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  regs[0] = inout[8 * lane_id];
  regs[1] = inout[8 * lane_id + 1];
  regs[2] = inout[8 * lane_id + 2];
  regs[3] = inout[8 * lane_id + 3];
  regs[4] = inout[8 * lane_id + 4];
  regs[5] = inout[8 * lane_id + 5];
  regs[6] = inout[8 * lane_id + 6];
  regs[7] = inout[8 * lane_id + 7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  NCTinout[0] = regs[0];
  NCTinout[1] = regs[1];
  NCTinout[2] = regs[2];
  NCTinout[3] = regs[3];
  NCTinout[4] = regs[4];
  NCTinout[5] = regs[5];
  NCTinout[6] = regs[6];
  NCTinout[7] = regs[7];

  // ================== 11. NCT Mm1 ==================
  regs[0] = Mm1[0];
  regs[1] = Mm1[1];
  regs[2] = Mm1[2];
  regs[3] = Mm1[3];
  regs[4] = Mm1[4];
  regs[5] = Mm1[5];
  regs[6] = Mm1[6];
  regs[7] = Mm1[7];
  for (size_t log_m = 0; log_m < 5; log_m++) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = numOfGroups + (((8 * lane_id) & 0xFF) / pair2);
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      ct_butterfly(l, r, NCTtwiddle[omegnIdx[j]], NCTtwiddle_shoup[omegnIdx[j]],
                   mod);
      regs[j] = C ? r : l;
    }
  }
  ct_butterfly(regs[0], regs[4], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[1], regs[5], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[2], regs[6], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[3], regs[7], NCTtwiddle[lane_id + 32],
               NCTtwiddle_shoup[lane_id + 32], mod);
  ct_butterfly(regs[0], regs[2], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[1], regs[3], NCTtwiddle[64 + lane_id * 2],
               NCTtwiddle_shoup[64 + lane_id * 2], mod);
  ct_butterfly(regs[4], regs[6], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[5], regs[7], NCTtwiddle[64 + lane_id * 2 + 1],
               NCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  ct_butterfly(regs[0], regs[1], NCTtwiddle[128 + 4 * lane_id],
               NCTtwiddle_shoup[128 + 4 * lane_id], mod);
  ct_butterfly(regs[2], regs[3], NCTtwiddle[128 + 4 * lane_id + 1],
               NCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  ct_butterfly(regs[4], regs[5], NCTtwiddle[128 + 4 * lane_id + 2],
               NCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  ct_butterfly(regs[6], regs[7], NCTtwiddle[128 + 4 * lane_id + 3],
               NCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  for (int j = 0; j < 8; j++) Mm1[j] = regs[j];

  // ================== 12. Section 12
  // 为空（IR：y=1，NCT(1)直接就是1）==================

  // ================== 13. Gx = NCT(x)*1 +
  // NCT(m)*N（IR：NCTinoutA=1）==================
  register uint64_t Gx[8];
  for (int j = 0; j < 8; j++) {
    uint64_t tmp2 = multiply_and_reduce_shoup_lazy(
        Mm1[j], modn[8 * lane_id + j], modn_shoup[8 * lane_id + j], mod);
    Gx[j] = (NCTinout[j] + tmp2) % MOD;
  }

  // ================== 14. INCT Gx ==================
  regs[0] = Gx[0];
  regs[1] = Gx[1];
  regs[2] = Gx[2];
  regs[3] = Gx[3];
  regs[4] = Gx[4];
  regs[5] = Gx[5];
  regs[6] = Gx[6];
  regs[7] = Gx[7];
  gs_butterfly(regs[0], regs[1], InvNCTtwiddle[128 + 4 * lane_id],
               InvNCTtwiddle_shoup[128 + 4 * lane_id], mod);
  gs_butterfly(regs[2], regs[3], InvNCTtwiddle[128 + 4 * lane_id + 1],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 1], mod);
  gs_butterfly(regs[4], regs[5], InvNCTtwiddle[128 + 4 * lane_id + 2],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 2], mod);
  gs_butterfly(regs[6], regs[7], InvNCTtwiddle[128 + 4 * lane_id + 3],
               InvNCTtwiddle_shoup[128 + 4 * lane_id + 3], mod);
  gs_butterfly(regs[0], regs[2], InvNCTtwiddle[64 + lane_id * 2],
               InvNCTtwiddle_shoup[64 + lane_id * 2], mod);
  gs_butterfly(regs[1], regs[3], InvNCTtwiddle[64 + lane_id * 2],
               InvNCTtwiddle_shoup[64 + lane_id * 2], mod);
  gs_butterfly(regs[4], regs[6], InvNCTtwiddle[64 + lane_id * 2 + 1],
               InvNCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  gs_butterfly(regs[5], regs[7], InvNCTtwiddle[64 + lane_id * 2 + 1],
               InvNCTtwiddle_shoup[64 + lane_id * 2 + 1], mod);
  gs_butterfly(regs[0], regs[4], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[1], regs[5], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[2], regs[6], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  gs_butterfly(regs[3], regs[7], InvNCTtwiddle[lane_id + 32],
               InvNCTtwiddle_shoup[lane_id + 32], mod);
  for (size_t log_m = 4; log_m >= 1; log_m--) {
    size_t log_step = 4 - log_m;
    uint64_t pairsInGroup = 1 << (log_step + 3);
    uint64_t numOfGroups = 128 / pairsInGroup;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << log_step);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << log_step);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << log_step);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << log_step);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << log_step);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << log_step);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << log_step);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << log_step);
    C = (lane_id >> log_step) & 1;
    uint64_t pair2 = pairsInGroup << 1;
    omegnIdx[0] = (((8 * lane_id) & 0xFF) / pair2) + numOfGroups;
    omegnIdx[1] = numOfGroups + (((8 * lane_id + 1) & 0xFF) / pair2);
    omegnIdx[2] = numOfGroups + (((8 * lane_id + 2) & 0xFF) / pair2);
    omegnIdx[3] = numOfGroups + (((8 * lane_id + 3) & 0xFF) / pair2);
    omegnIdx[4] = numOfGroups + (((8 * lane_id + 4) & 0xFF) / pair2);
    omegnIdx[5] = numOfGroups + (((8 * lane_id + 5) & 0xFF) / pair2);
    omegnIdx[6] = numOfGroups + (((8 * lane_id + 6) & 0xFF) / pair2);
    omegnIdx[7] = numOfGroups + (((8 * lane_id + 7) & 0xFF) / pair2);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  {
    uint64_t pairsInGroup_inv = 1 << 7;
    uint64_t pair2_inv = pairsInGroup_inv << 1;
    uint64_t numOfGroups_inv = 128 / pairsInGroup_inv;
    new_regs[0] = __shfl_xor_sync(0xffffffff, regs[0], 1 << 4);
    new_regs[1] = __shfl_xor_sync(0xffffffff, regs[1], 1 << 4);
    new_regs[2] = __shfl_xor_sync(0xffffffff, regs[2], 1 << 4);
    new_regs[3] = __shfl_xor_sync(0xffffffff, regs[3], 1 << 4);
    new_regs[4] = __shfl_xor_sync(0xffffffff, regs[4], 1 << 4);
    new_regs[5] = __shfl_xor_sync(0xffffffff, regs[5], 1 << 4);
    new_regs[6] = __shfl_xor_sync(0xffffffff, regs[6], 1 << 4);
    new_regs[7] = __shfl_xor_sync(0xffffffff, regs[7], 1 << 4);
    C = (lane_id >> 4) & 1;
    omegnIdx[0] = (((8 * lane_id) & 0xFF) / pair2_inv) + numOfGroups_inv;
    omegnIdx[1] = numOfGroups_inv + (((8 * lane_id + 1) & 0xFF) / pair2_inv);
    omegnIdx[2] = numOfGroups_inv + (((8 * lane_id + 2) & 0xFF) / pair2_inv);
    omegnIdx[3] = numOfGroups_inv + (((8 * lane_id + 3) & 0xFF) / pair2_inv);
    omegnIdx[4] = numOfGroups_inv + (((8 * lane_id + 4) & 0xFF) / pair2_inv);
    omegnIdx[5] = numOfGroups_inv + (((8 * lane_id + 5) & 0xFF) / pair2_inv);
    omegnIdx[6] = numOfGroups_inv + (((8 * lane_id + 6) & 0xFF) / pair2_inv);
    omegnIdx[7] = numOfGroups_inv + (((8 * lane_id + 7) & 0xFF) / pair2_inv);
    for (int j = 0; j < 8; j++) {
      uint64_t l = C ? new_regs[j] : regs[j], r = C ? regs[j] : new_regs[j];
      gs_butterfly(l, r, InvNCTtwiddle[omegnIdx[j]],
                   InvNCTtwiddle_shoup[omegnIdx[j]], mod);
      regs[j] = C ? r : l;
    }
  }
  for (int j = 0; j < 8; j++)
    Gx[j] = multiply_and_reduce_shoup_lazy(regs[j], inv, inv_shoup, mod);

  // ================== 15. OPTIMIZED modh Gx fix vector (Warp 涟漪进位修正)
  // ==================

  register int64_t sregs0[8], sregs[8], sregs1[8], sregs3[8], sregs4[8];
  register int64_t snew_regs3[8], snew_regs4[8];
  register int64_t ssum[8], sprev_sum[8], stail[8];
  register uint64_t DivMod[8];

  // 1. 获取带符号的初始值
  sregs0[0] = (Gx[0] > sample[8 * lane_id])
                  ? (static_cast<int64_t>(Gx[0]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[0]);
  sregs0[1] = (Gx[1] > sample[(8 * lane_id + 1) & 0xFF])
                  ? (static_cast<int64_t>(Gx[1]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[1]);
  sregs0[2] = (Gx[2] > sample[(8 * lane_id + 2) & 0xFF])
                  ? (static_cast<int64_t>(Gx[2]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[2]);
  sregs0[3] = (Gx[3] > sample[(8 * lane_id + 3) & 0xFF])
                  ? (static_cast<int64_t>(Gx[3]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[3]);
  sregs0[4] = (Gx[4] > sample[(8 * lane_id + 4) & 0xFF])
                  ? (static_cast<int64_t>(Gx[4]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[4]);
  sregs0[5] = (Gx[5] > sample[(8 * lane_id + 5) & 0xFF])
                  ? (static_cast<int64_t>(Gx[5]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[5]);
  sregs0[6] = (Gx[6] > sample[(8 * lane_id + 6) & 0xFF])
                  ? (static_cast<int64_t>(Gx[6]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[6]);
  sregs0[7] = (Gx[7] > sample[(8 * lane_id + 7) & 0xFF])
                  ? (static_cast<int64_t>(Gx[7]) - static_cast<int64_t>(MOD))
                  : static_cast<int64_t>(Gx[7]);

// 利用算术右移自动保留符号位
#pragma unroll
  for (int j = 0; j < 8; j++) {
    sregs[j] = sregs0[j] >> u;
    sregs1[j] = sregs0[j] & mod_mask;
    sregs3[j] = sregs[j] >> u;
    sregs4[j] = sregs[j] & mod_mask;
  }

  sretail_0 = __shfl_sync(0xffffffff, sregs3[6] + sregs4[7], 31);
  sretail_1 = __shfl_sync(0xffffffff, sregs3[7], 31);

  snew_regs3[0] = __shfl_up_sync(0xffffffff, sregs3[6], 1);
  snew_regs3[1] = __shfl_up_sync(0xffffffff, sregs3[7], 1);
  snew_regs3[2] = sregs3[0];
  snew_regs3[3] = sregs3[1];
  snew_regs3[4] = sregs3[2];
  snew_regs3[5] = sregs3[3];
  snew_regs3[6] = sregs3[4];
  snew_regs3[7] = sregs3[5];

  snew_regs4[0] = __shfl_up_sync(0xffffffff, sregs4[7], 1);
  snew_regs4[1] = sregs4[0];
  snew_regs4[2] = sregs4[1];
  snew_regs4[3] = sregs4[2];
  snew_regs4[4] = sregs4[3];
  snew_regs4[5] = sregs4[4];
  snew_regs4[6] = sregs4[5];
  snew_regs4[7] = sregs4[6];

  if (lane_id == 0) {
    ssum[0] = sregs1[0];
    ssum[1] = (sregs1[1] + snew_regs4[1]);
    for (int j = 2; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  } else {
    for (int j = 0; j <= 7; j++)
      ssum[j] = snew_regs3[j] + sregs1[j] + snew_regs4[j];
  }

  scarry_wrap = __shfl_sync(0xffffffff, ssum[7] >> u, 31);
  stemp_shuffled = __shfl_up_sync(0xffffffff, ssum[7] >> u, 1);

  if (lane_id == 0) {
    sprev_sum[0] = 0;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  } else {
    sprev_sum[0] = stemp_shuffled;
    for (int j = 1; j <= 7; j++) sprev_sum[j] = ssum[j - 1] >> u;
  }

#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] = (ssum[j] & mod_mask) + sprev_sum[j];
  }

  // =========================================================================
  // ★ 核心修复：Stage 1 & 2 使用 Ballot While 循环涟漪进位，替代错误的前缀和
  // =========================================================================
  slc = 0;
#pragma unroll
  for (int j = 0; j < 8; j++) {
    stail[j] += slc;
    slc = stail[j] >> u;
    stail[j] &= mod_mask;
  }

  int64_t accumulated_lane31_carry =
      0;  // 专门捕捉所有从最高位（lane 31）溢出的最终进位/借位
  active = __ballot_sync(0xffffffff, slc != 0);

  // 只要有任何一个线程还有进位/借位没消化，整个 Warp 就继续同步传递
  while (active != 0) {
    if (lane_id == 31) {
      accumulated_lane31_carry += slc;
    }

    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;  // 最低位暂时不回卷

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;  // 算术右移完美处理负数借位
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // 获取从最高位最终溢出/借位的所有总量
  int64_t final_carry = __shfl_sync(0xffffffff, accumulated_lane31_carry, 31);

  // =========================================================================
  // ★ 核心修复：Stage 3 (Mod H 负向回卷)
  // =========================================================================
  slc = 0;
  if (lane_id == 0) {
    // 对于模 h (2^4352 + 1)，最高位的进位溢出权重大于 0，等价于从最低位减去。
    // 总溢出 = sretail_0 + scarry_wrap + final_carry
    int64_t total_wrap_0 = sretail_0 + scarry_wrap + final_carry;

    int64_t flag = stail[0] - total_wrap_0;
    int64_t negcarry = flag >> u;
    stail[0] = flag & mod_mask;

    flag = stail[1] - sretail_1 + negcarry;
    negcarry = flag >> u;
    stail[1] = flag & mod_mask;

    // 让借位顺着 lane_id 0 往上走，走到没有为止
    for (int j = 2; j < 8; j++) {
      flag = stail[j] + negcarry;
      negcarry = flag >> u;
      stail[j] = flag & mod_mask;
    }

    slc = negcarry;  // 如果 lane 0 扣完 8 个元素后还欠借位，扔给后面的线程
  }

  // 再次开启涟漪循环，彻底消化回卷带来的多米诺借位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;

    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  // =========================================================================
  // Stage 4: 计算最终的 w = (h - g) / 2
  // =========================================================================
  uint64_t maxNum = (1ULL << u) - 1;
  if (lane_id == 0) {
    // 这一步等价于取补码 + 2
    stail[0] = maxNum + 2 - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  } else {
    stail[0] = maxNum - stail[0];
    stail[1] = maxNum - stail[1];
    stail[2] = maxNum - stail[2];
    stail[3] = maxNum - stail[3];
    stail[4] = maxNum - stail[4];
    stail[5] = maxNum - stail[5];
    stail[6] = maxNum - stail[6];
    stail[7] = maxNum - stail[7];
  }

  // ★ 修复漏洞：maxNum+2-stail[0] 如果 stail[0] 极小，会导致超过 17
  // 位限制产生进位
  slc = 0;
  if (lane_id == 0) {
    for (int j = 0; j < 8; j++) {
      stail[j] += slc;
      slc = stail[j] >> u;
      stail[j] &= mod_mask;
    }
  }
  // 传播这最后一丝极小的正向进位
  active = __ballot_sync(0xffffffff, slc != 0);
  while (active != 0) {
    int64_t incoming_c = __shfl_up_sync(0xffffffff, slc, 1);
    if (lane_id == 0) incoming_c = 0;
    slc = 0;
    if (incoming_c != 0) {
      for (int j = 0; j < 8; j++) {
        stail[j] += incoming_c;
        incoming_c = stail[j] >> u;
        stail[j] &= mod_mask;
      }
      slc = incoming_c;
    }
    active = __ballot_sync(0xffffffff, slc != 0);
  }

  uint64_t temp_shuffled1 = __shfl_down_sync(0xffffffff, stail[0], 1);
  if (lane_id == 31) {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = 0;
  } else {
    DivMod[0] = (stail[1] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[1] = (stail[2] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[2] = (stail[3] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[3] = (stail[4] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[4] = (stail[5] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[5] = (stail[6] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[6] = (stail[7] % 2 == 1) ? (1 << (u - 1)) : 0;
    DivMod[7] = (temp_shuffled1 % 2 == 1) ? (1 << (u - 1)) : 0;
  }

  stail[0] = (stail[0] / 2) + DivMod[0];
  stail[1] = (stail[1] / 2) + DivMod[1];
  stail[2] = (stail[2] / 2) + DivMod[2];
  stail[3] = (stail[3] / 2) + DivMod[3];
  stail[4] = (stail[4] / 2) + DivMod[4];
  stail[5] = (stail[5] / 2) + DivMod[5];
  stail[6] = (stail[6] / 2) + DivMod[6];
  stail[7] = (stail[7] / 2) + DivMod[7];

  // ================== 16. 写回 ==================
  // ★ inout[8*i+j] → inout[8*lane_id+j]
  for (int j = 0; j < 8; j++)
    inout[8 * lane_id + j] = static_cast<uint64_t>(stail[j]);
}

// end device x1
//------------------------test-------------------------------------
// test device xy
__global__ void XYfixWarpVector_dev_wrapper(
    uint64_t *inout, uint64_t *inoutA, uint64_t *negmodn,
    uint64_t *negmodn_shoup, uint64_t *modn, uint64_t *modn_shoup,
    uint64_t n_poly, uint64_t mod, const uint64_t *twiddle,
    const uint64_t *twiddle_shoup, const uint64_t *ICTTwiddle,
    const uint64_t *ICTTwiddle_shoup, const uint64_t *NCTtwiddle,
    const uint64_t *NCTtwiddle_shoup, const uint64_t *InvNCTtwiddle,
    const uint64_t *InvNCTtwiddle_shoup, uint64_t inv, uint64_t inv_shoup,
    const uint64_t *sample) {
  // 每个 warp 在全局中的编号
  const int warps_per_block = blockDim.x >> 5;
  const int warp_in_block = threadIdx.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;

  // 把指针偏移到本 warp 专属的 256 元素段
  uint64_t *my_inout = inout + global_warp_id * 256;
  uint64_t *my_inoutA = inoutA + global_warp_id * 256;

  XYfixWarpVector_dev(my_inout, my_inoutA, negmodn, negmodn_shoup, modn,
                      modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                      ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                      NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                      inv_shoup, sample);
}

