__global__ void FMLMKernel_e(
    const uint64_t *__restrict__ A,
    const uint64_t
        *__restrict__ exp_bits,  // 格式改为压缩：[m * (tau/64)] uint64_t
    int tau, uint64_t *output, int m, const uint64_t *__restrict__ d_r0,
    uint64_t *d_r1_ct, uint64_t *d_r1_nct, uint64_t *negmodn,
    uint64_t *negmodn_shoup, uint64_t *modn, uint64_t *modn_shoup,
    uint64_t n_poly, uint64_t mod, const uint64_t *twiddle,
    const uint64_t *twiddle_shoup, const uint64_t *ICTTwiddle,
    const uint64_t *ICTTwiddle_shoup, const uint64_t *NCTtwiddle,
    const uint64_t *NCTtwiddle_shoup, const uint64_t *InvNCTtwiddle,
    const uint64_t *InvNCTtwiddle_shoup, uint64_t inv, uint64_t inv_shoup,
    const uint64_t *sample) {
  const int warp_in_block = threadIdx.x >> 5;
  const int warps_per_block = blockDim.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;
  const uint32_t lane_id = threadIdx.x & 0x1F;

  if (global_warp_id >= m) return;

  extern __shared__ uint64_t smem[];
  uint64_t *const ws = smem + warp_in_block * 512;
  uint64_t *const y_buf = ws;
  uint64_t *const t_buf = ws + 256;

  const int off = global_warp_id * 256;

  // ================================================================
  // 优化：压缩格式加载
  //
  // exp_bits 格式：[m * (tau/64)] uint64_t
  //   每个指数存为 tau/64 = 16 个 uint64_t（packed，LSB first）
  //   第 p 个指数占 exp_bits[p*16 .. p*16+15]
  //
  // 加载方式：
  //   每个 warp 只需加载 16 个 uint64_t = 128 字节（1 个 cache line）
  //   lane 0~15 各加载 1 个 uint64_t（合并访问）
  //   lane 16~31 加载 0（通过 __shfl_sync 获取）
  //
  // 总加载量：2048 warp × 128B = 256KB（完全驻留 L2 Cache）
  // ================================================================
  const int exp_limbs = tau / 64;  // = 16（tau=1024时）
  const uint64_t *my_packed_exp = exp_bits + (size_t)global_warp_id * exp_limbs;

  // 每个 lane 持有一个 limb（lane 0持有limb0，lane 1持有limb1，...，lane
  // 15持有limb15） lane 16~31 持有 0（不参与实际数据，通过 shfl 获取）
  uint64_t my_limb = 0ULL;
  if ((int)lane_id < exp_limbs)
    my_limb = my_packed_exp[lane_id];  // 合并访问：lane 0~15 读连续地址

// ================================================================
// Step 6: y ← x
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++) y_buf[8 * lane_id + j] = A[off + 8 * lane_id + j];
  __syncwarp();

// ================================================================
// Step 7: t ← r₀
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++) t_buf[8 * lane_id + j] = d_r0[8 * lane_id + j];
  __syncwarp();

  // ================================================================
  // Step 8: y ← FMLM(y, r₁)
  // ================================================================
  XYfixWarpROneVector_dev(y_buf, d_r1_ct, d_r1_nct, negmodn, negmodn_shoup,
                          modn, modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                          ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                          NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                          inv, inv_shoup, sample);
  __syncwarp();

  // ================================================================
  // Steps 9–12: for i = 0 to τ-1
  //
  // 取第 i 个 bit：
  //   limb 下标 = i / 64  → 该 limb 在 lane (i/64) 中
  //   bit  位置 = i % 64
  //   通过 __shfl_sync 从 lane(i/64) 广播 my_limb 到所有 lane
  //   取目标 bit，全程零全局内存访问
  // ================================================================
  for (int i = 0; i < tau; i++) {
    // 从持有 limb(i/64) 的 lane 广播到全部 lane
    uint64_t src_limb = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)(i / 64));
    uint64_t the_bit = (src_limb >> (i % 64)) & 1ULL;

    if (the_bit == 1ULL) {
      XYfixWarpVector_dev(t_buf, y_buf, negmodn, negmodn_shoup, modn,
                          modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                          ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                          NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                          inv, inv_shoup, sample);
      __syncwarp();
    }

    XYfixWarpSquareVector_dev(y_buf, negmodn, negmodn_shoup, modn, modn_shoup,
                              n_poly, mod, twiddle, twiddle_shoup, ICTTwiddle,
                              ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
                              InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                              inv_shoup, sample);
    __syncwarp();
  }

  // ================================================================
  // Step 13: t ← FMLM(t, 1)
  // ================================================================
  XYfixWarpIRVector_dev(
      t_buf, negmodn, negmodn_shoup, modn, modn_shoup, n_poly, mod, twiddle,
      twiddle_shoup, ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
      InvNCTtwiddle, InvNCTtwiddle_shoup, inv, inv_shoup, sample);
  __syncwarp();

// ================================================================
// Step 14: 写回全局内存
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++)
    output[off + 8 * lane_id + j] = t_buf[8 * lane_id + j];
}

// ── 参数 ────────────────────────────────────────────────────────
#define TEST_BATCH 1000  // 测试用例数
#define ARR_LEN 256      // 大数 limb 数
#define BASE_BITS 17
#define BASE (1ULL << BASE_BITS)  // 131072
#define TAU 2048                  // 指数 bit 数（对应 2048-bit Paillier λ）
#define EXP_U64_LIMBS (TAU / 64)  // = 32，压缩格式每个指数占 32 个 uint64_t
#define OU_TAU 1408  // OU 明文 bit 上界（= 22*64，覆盖 1363-bit 私钥 p）
#define OU_EXP_LIMBS (OU_TAU / 64)  // = 22，每个 OU 明文占 22 个 uint64_t
#define N2_TOP_IDX 240              // n² 最高非零 limb 索引
#define N2_TOP_VAL 27958ULL         // n² 最高 limb 的值（上界）
#define WARP_PER_BLK 8              // 每 block 的 warp 数
#define NUM_STREAMS 4

__global__ void FMLE_mod2_Kernel(
    const uint64_t *__restrict__ A,         // 输入：c̃₁（蒙哥马利域）
    const uint64_t *__restrict__ exp_bits,  // 指数 m（压缩格式）
    int tau,                                // m 的 bit 长度
    uint64_t *output,                       // 输出：c₁^m · R（蒙哥马利域）
    int m,                                  // 测试用例数量
    const uint64_t *__restrict__ d_r0,      // r₀ = R mod n²（1的蒙哥马利表示）
    // ★ 去掉 d_r1_ct / d_r1_nct：Step8 已跳过，不再需要
    uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n_poly, uint64_t mod,
    const uint64_t *twiddle, const uint64_t *twiddle_shoup,
    const uint64_t *ICTTwiddle, const uint64_t *ICTTwiddle_shoup,
    const uint64_t *NCTtwiddle, const uint64_t *NCTtwiddle_shoup,
    const uint64_t *InvNCTtwiddle, const uint64_t *InvNCTtwiddle_shoup,
    uint64_t inv, uint64_t inv_shoup, const uint64_t *sample) {
  const int warp_in_block = threadIdx.x >> 5;
  const int warps_per_block = blockDim.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;
  const uint32_t lane_id = threadIdx.x & 0x1F;

  if (global_warp_id >= m) return;

  extern __shared__ uint64_t smem[];
  uint64_t *const ws = smem + warp_in_block * 512;
  uint64_t *const y_buf = ws;
  uint64_t *const t_buf = ws + 256;

  const int off = global_warp_id * 256;

  // 压缩格式加载指数（与原版相同）
  const int exp_limbs = tau / 64;
  const uint64_t *my_packed_exp = exp_bits + (size_t)global_warp_id * exp_limbs;

  uint64_t my_limb = 0ULL;
  if ((int)lane_id < exp_limbs) my_limb = my_packed_exp[lane_id];

// ================================================================
// Step 6: y ← c̃₁（直接加载蒙哥马利域输入，与原版相同）
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++) y_buf[8 * lane_id + j] = A[off + 8 * lane_id + j];
  __syncwarp();

// ================================================================
// Step 7: t ← r₀（与原版相同）
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++) t_buf[8 * lane_id + j] = d_r0[8 * lane_id + j];
  __syncwarp();

  // ================================================================
  // ★ Step 8：跳过！
  //
  // 原版：y ← XYfixWarpROneVector_dev(y, r₁)
  //        即 y = y · R²· R⁻¹ = y · R，将普通域转为蒙哥马利域
  //
  // FMLE_mod2：输入 A 已经是 c̃₁ = c₁ · R（蒙哥马利域）
  //            无需转换，y_buf 已正确，直接进入循环
  // ================================================================

  // ================================================================
  // Steps 9-12: 平方-乘循环（与原版完全相同）
  // ================================================================
  for (int i = 0; i < tau; i++) {
    uint64_t src_limb = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)(i / 64));
    uint64_t the_bit = (src_limb >> (i % 64)) & 1ULL;

    if (the_bit == 1ULL) {
      XYfixWarpVector_dev(t_buf, y_buf, negmodn, negmodn_shoup, modn,
                          modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                          ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                          NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                          inv, inv_shoup, sample);
      __syncwarp();
    }

    XYfixWarpSquareVector_dev(y_buf, negmodn, negmodn_shoup, modn, modn_shoup,
                              n_poly, mod, twiddle, twiddle_shoup, ICTTwiddle,
                              ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
                              InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                              inv_shoup, sample);
    __syncwarp();
  }

// ================================================================
// ★ Step 13：跳过！
//
// 原版：t ← XYfixWarpIRVector_dev(t)
//        即 t = t · 1 · R⁻¹，将蒙哥马利域转回普通域
//
// FMLE_mod2：保持蒙哥马利输出 t = c₁^m · R
//            供后续同态运算继续使用，无需转回普通域
// ================================================================

// ================================================================
// Step 14: 写回全局内存（与原版相同）
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++)
    output[off + 8 * lane_id + j] = t_buf[8 * lane_id + j];
}

// =============================================================
// FMLE_mod3_Kernel
//
// 功能：FMLE(x̃, e) → x^e mod n²（蒙哥马利域输入，普通域输出）
//
// 与 FMLMKernel_e 的区别：
//   · 输入 A 已是蒙哥马利域（x̃ = x·R），故跳过 Step8（y←FMLM(y,r₁)）
//   · 去掉参数 d_r1_ct / d_r1_nct（Step8 不再需要）
//   · Step13 保留（t←FMLM(t,1)），将结果还原到普通域后输出
//
// 与 FMLE_mod2_Kernel 的区别：
//   · 保留 Step13，输出是普通域（x^e mod n²），而非蒙哥马利域
//
// 参数：
//   A         [m * ARR_LEN]          输入，蒙哥马利域（x̃ = x·R）
//   exp_bits  [m * (tau/64)]         压缩格式指数，LSB-first，每指数 tau/64 个
//   uint64_t tau                              指数 bit 长度 output    [m *
//   ARR_LEN]          输出，普通域（x^e mod n²） m 用例数量 d_r0      [ARR_LEN]
//   r₀ = R mod n²（1 的蒙哥马利表示） 其余为 NTT 参数（与 FMLMKernel_e
//   完全一致）
// =============================================================
__global__ void FMLE_mod3_Kernel(
    const uint64_t *__restrict__ A,  // 输入：x̃（蒙哥马利域）
    const uint64_t
        *__restrict__ exp_bits,         // 指数（压缩格式，tau/64 个 uint64_t）
    int tau,                            // 指数 bit 长度
    uint64_t *output,                   // 输出：x^e mod n²（普通域）
    int m,                              // 用例数量
    const uint64_t *__restrict__ d_r0,  // r₀ = R mod n²（1 的蒙哥马利表示）
    // ★ 无 d_r1_ct / d_r1_nct：Step8 已跳过
    uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n_poly, uint64_t mod,
    const uint64_t *twiddle, const uint64_t *twiddle_shoup,
    const uint64_t *ICTTwiddle, const uint64_t *ICTTwiddle_shoup,
    const uint64_t *NCTtwiddle, const uint64_t *NCTtwiddle_shoup,
    const uint64_t *InvNCTtwiddle, const uint64_t *InvNCTtwiddle_shoup,
    uint64_t inv, uint64_t inv_shoup, const uint64_t *sample) {
  const int warp_in_block = threadIdx.x >> 5;
  const int warps_per_block = blockDim.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;
  const uint32_t lane_id = threadIdx.x & 0x1F;

  if (global_warp_id >= m) return;

  extern __shared__ uint64_t smem[];
  uint64_t *const ws = smem + warp_in_block * 512;
  uint64_t *const y_buf = ws;        // [256] y
  uint64_t *const t_buf = ws + 256;  // [256] t

  const int off = global_warp_id * 256;

  // 压缩格式加载指数：每 warp 的 lane 0~(exp_limbs-1) 各持有一个 uint64_t limb
  const int exp_limbs = tau / 64;
  const uint64_t *my_packed_exp = exp_bits + (size_t)global_warp_id * exp_limbs;

  uint64_t my_limb = 0ULL;
  if ((int)lane_id < exp_limbs) my_limb = my_packed_exp[lane_id];

// ================================================================
// Step 6: y ← x̃（直接加载蒙哥马利域输入）
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++) y_buf[8 * lane_id + j] = A[off + 8 * lane_id + j];
  __syncwarp();

// ================================================================
// Step 7: t ← r₀
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++) t_buf[8 * lane_id + j] = d_r0[8 * lane_id + j];
  __syncwarp();

  // ================================================================
  // ★ Step 8：跳过！
  //
  // 原算法：y ← FMLM(y, r₁) = y·r²·R⁻¹ = y·R，将普通域转为蒙哥马利域
  // FMLE_mod3：输入 A 已是蒙哥马利域（x̃ = x·R），无需再乘 R，直接进入循环
  // ================================================================

  // ================================================================
  // Steps 9–12: 平方-乘循环（与 FMLMKernel_e 完全相同）
  //
  // 取第 i 个 bit：通过 __shfl_sync 从持有 limb(i/64) 的 lane 广播，
  // 零额外全局内存访问
  // ================================================================
  for (int i = 0; i < tau; i++) {
    uint64_t src_limb = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)(i / 64));
    uint64_t the_bit = (src_limb >> (i % 64)) & 1ULL;

    // Step 10: if e[i]=1 then t ← FMLM(t, y)
    if (the_bit == 1ULL) {
      XYfixWarpVector_dev(t_buf, y_buf, negmodn, negmodn_shoup, modn,
                          modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                          ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                          NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                          inv, inv_shoup, sample);
      __syncwarp();
    }

    // Step 11: y ← FMLM(y, y)
    XYfixWarpSquareVector_dev(y_buf, negmodn, negmodn_shoup, modn, modn_shoup,
                              n_poly, mod, twiddle, twiddle_shoup, ICTTwiddle,
                              ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
                              InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                              inv_shoup, sample);
    __syncwarp();
  }

  // ================================================================
  // Step 13: t ← FMLM(t, 1)
  //
  // 去除蒙哥马利因子 R，将结果还原到普通域：
  //   t = (x^e · R) · 1 · R⁻¹ = x^e mod n²
  // ★ 与 FMLE_mod2_Kernel 的关键区别：此步保留
  // ================================================================
  XYfixWarpIRVector_dev(
      t_buf, negmodn, negmodn_shoup, modn, modn_shoup, n_poly, mod, twiddle,
      twiddle_shoup, ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
      InvNCTtwiddle, InvNCTtwiddle_shoup, inv, inv_shoup, sample);
  __syncwarp();

// ================================================================
// Step 14: 写回全局内存
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++)
    output[off + 8 * lane_id + j] = t_buf[8 * lane_id + j];
}

// =============================================================
// 计时结构体
// =============================================================
struct MulPlainTiming {
  float kernel_ms;    // 各流内核时间的最大值
  float pipeline_ms;  // 流水线端到端时间（含流创建/销毁）
};

// =============================================================
// paillier_mulplain
//
// 功能：批量 MulPlain（同态标量乘法），使用 CUDA 流并行
//
// 要求：
//   · 所有数据已在 GPU 上（设备指针），不做 H2D/D2H
//   · 内部使用 NUM_STREAMS 条流，每流负责约 batch/NUM_STREAMS 个用例
//   · batch 无需是 NUM_STREAMS 的整数倍
//   · 计算过程：FMLE_mod2_Kernel（蒙哥马利域 → 蒙哥马利域）
//
// 流水线示意（NUM_STREAMS=4，batch 不整除时最后一流更少）：
//   Stream0: [Kernel, actual_chunk[0] 个]
//   Stream1: [Kernel, actual_chunk[1] 个]
//   Stream2: [Kernel, actual_chunk[2] 个]
//   Stream3: [Kernel, actual_chunk[3] 个]  ← 可能比其他流少，甚至为 0（跳过）
//
// 参数：
//   d_ciphertexts  [batch * ARR_LEN]       蒙哥马利域密文输入（设备）
//   d_exps         [batch * EXP_U64_LIMBS] 压缩指数（设备）
//   d_output       [batch * ARR_LEN]       蒙哥马利域输出（设备）
//   其余参数为预计算常量（已在 GPU 上）
// =============================================================
MulPlainTiming paillier_mulplain(
    const uint64_t *d_ciphertexts, const uint64_t *d_exps, uint64_t *d_output,
    int batch, int tau, const uint64_t *d_r0, uint64_t *d_negmodn,
    uint64_t *d_negmodn_shoup, uint64_t *d_modn, uint64_t *d_modn_shoup,
    uint64_t mod, const uint64_t *d_twiddle, const uint64_t *d_twiddle_shoup,
    const uint64_t *d_ICTTwiddle, const uint64_t *d_ICTTwiddle_shoup,
    const uint64_t *d_NCTtwiddle, const uint64_t *d_NCTtwiddle_shoup,
    const uint64_t *d_InvNCTtwiddle, const uint64_t *d_InvNCTtwiddle_shoup,
    uint64_t inv_val, uint64_t inv_shoup_val, const uint64_t *d_sample) {
  // ── 向上取整 chunk，无需 batch 整除 NUM_STREAMS ──────────────
  // 改动1：向上取整，保证所有用例被覆盖
  const int chunk = (batch + NUM_STREAMS - 1) / NUM_STREAMS;

  const size_t smem_size = (size_t)WARP_PER_BLK * 512 * sizeof(uint64_t);

  // ── 创建流和事件 ──────────────────────────────────────────────
  cudaStream_t streams[NUM_STREAMS];
  cudaEvent_t ev_ker[NUM_STREAMS][2];

  for (int s = 0; s < NUM_STREAMS; s++) {
    CUDA_CHECK(cudaStreamCreate(&streams[s]));
    CUDA_CHECK(cudaEventCreate(&ev_ker[s][0]));
    CUDA_CHECK(cudaEventCreate(&ev_ker[s][1]));
  }

  cudaEvent_t ev_pipe_start, ev_pipe_end;
  CUDA_CHECK(cudaEventCreate(&ev_pipe_start));
  CUDA_CHECK(cudaEventCreate(&ev_pipe_end));

  // ── 流水线提交 ────────────────────────────────────────────────
  CUDA_CHECK(cudaEventRecord(ev_pipe_start, 0));

  for (int s = 0; s < NUM_STREAMS; s++) {
    // 改动2：计算本流起点，超出 batch 则无任务，跳过
    int offset = s * chunk;
    if (offset >= batch) break;

    // 改动3：本流实际处理量（最后一流可能不足 chunk）
    int actual_chunk = ((offset + chunk) > batch) ? (batch - offset) : chunk;

    // 改动4：按 actual_chunk 计算 blocks，不会启动多余 warp
    const int blocks = (actual_chunk + WARP_PER_BLK - 1) / WARP_PER_BLK;

    // 偏移（元素数）
    size_t ct_off = (size_t)offset * ARR_LEN;
    size_t exp_off = (size_t)offset * EXP_U64_LIMBS;

    CUDA_CHECK(cudaEventRecord(ev_ker[s][0], streams[s]));

    // 改动5：传入 actual_chunk 而非 chunk，内核 guard 不会越界
    FMLE_mod2_Kernel<<<blocks, WARP_PER_BLK * 32, smem_size, streams[s]>>>(
        d_ciphertexts + ct_off, d_exps + exp_off, tau, d_output + ct_off,
        actual_chunk,  // ← 实际用例数
        d_r0, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
        (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
        d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
        d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);

    CUDA_CHECK(cudaEventRecord(ev_ker[s][1], streams[s]));
  }

  CUDA_CHECK(cudaEventRecord(ev_pipe_end, 0));
  CUDA_CHECK(cudaEventSynchronize(ev_pipe_end));
  CUDA_CHECK(cudaGetLastError());

  // ── 计算各流内核时间，取最大值 ───────────────────────────────
  MulPlainTiming t = {0.f, 0.f};
  for (int s = 0; s < NUM_STREAMS; s++) {
    // 未启动的流（offset >= batch 时 break 前已跳过）事件未记录，
    // 只统计实际启动的流
    int offset = s * chunk;
    if (offset >= batch) break;

    float ms = 0.f;
    CUDA_CHECK(cudaEventElapsedTime(&ms, ev_ker[s][0], ev_ker[s][1]));
    if (ms > t.kernel_ms) t.kernel_ms = ms;
  }
  CUDA_CHECK(cudaEventElapsedTime(&t.pipeline_ms, ev_pipe_start, ev_pipe_end));

  // ── 清理流和事件 ──────────────────────────────────────────────
  for (int s = 0; s < NUM_STREAMS; s++) {
    cudaStreamDestroy(streams[s]);
    cudaEventDestroy(ev_ker[s][0]);
    cudaEventDestroy(ev_ker[s][1]);
  }
  cudaEventDestroy(ev_pipe_start);
  cudaEventDestroy(ev_pipe_end);

  return t;
}

// =============================================================
// 写结果到 txt（与原版格式相同）
// =============================================================
static void write_to_txt(const char *filename, int num, const uint64_t *h_bases,
                         const uint64_t *h_exps, const uint64_t *h_results,
                         const uint64_t *modn) {
  FILE *fp = fopen(filename, "w");
  if (!fp) {
    fprintf(stderr, "无法创建 %s\n", filename);
    return;
  }

  fprintf(fp, "%d %d %d %d\n", num, ARR_LEN, BASE_BITS, TAU);

  for (int j = 0; j < ARR_LEN; j++) {
    fprintf(fp, "%llu", (unsigned long long)modn[j]);
    fprintf(fp, j < ARR_LEN - 1 ? " " : "\n");
  }
  for (int i = 0; i < num; i++) {
    const uint64_t *x = h_bases + (size_t)i * ARR_LEN;
    const uint64_t *e = h_exps + (size_t)i * EXP_U64_LIMBS;
    const uint64_t *r = h_results + (size_t)i * ARR_LEN;
    for (int j = 0; j < ARR_LEN; j++) {
      fprintf(fp, "%llu", (unsigned long long)x[j]);
      fprintf(fp, j < ARR_LEN - 1 ? " " : "\n");
    }
    for (int j = 0; j < EXP_U64_LIMBS; j++) {
      fprintf(fp, "%llu", (unsigned long long)e[j]);
      fprintf(fp, j < EXP_U64_LIMBS - 1 ? " " : "\n");
    }
    for (int j = 0; j < ARR_LEN; j++) {
      fprintf(fp, "%llu", (unsigned long long)r[j]);
      fprintf(fp, j < ARR_LEN - 1 ? " " : "\n");
    }
  }
  fclose(fp);
  printf("结果已写入 %s\n", filename);
}

// ================================================================
// paillier_cpowm
//
// 并行计算 batch 对 c_i^m_i mod n^2
//
// 输入：
//   h_ciphertexts  [batch * 256]  密文，每个大数 256 个 17-bit limbs
//   h_plaintexts   [batch * 16]   明文，每个大数 16 个 64-bit
//   limbs（共1024bit） batch                         明密文对数量
//   以下为预计算好的 GPU 参数（均已在 device 端）
// 输出：
//   h_output       [batch * 256]  c^m mod n^2 结果
// ================================================================
void paillier_cpowm(const uint64_t *h_ciphertexts, const uint64_t *h_plaintexts,
                    int batch, uint64_t *d_r0, uint64_t *d_r1_ct,
                    uint64_t *d_r1_nct, uint64_t *d_negModn,
                    uint64_t *d_negModn_shoup, uint64_t *d_Modn,
                    uint64_t *d_Modn_shoup, uint64_t n_poly, uint64_t mod,
                    uint64_t *d_twiddle, uint64_t *d_twiddle_shoup,
                    uint64_t *d_ICTTwiddle, uint64_t *d_ICTTwiddle_shoup,
                    uint64_t *d_NCTtwiddle, uint64_t *d_NCTtwiddle_shoup,
                    uint64_t *d_InvNCTtwiddle, uint64_t *d_InvNCTtwiddle_shoup,
                    uint64_t inv, uint64_t inv_shoup, uint64_t *d_sample,
                    uint64_t *h_output) {
  const int cpowm_tau = 1024;
  const int cpowm_exp_u64_limbs = 16;
  const int cpowm_limbs_per_num = 256;
  const int cpowm_warp_per_blk = 4;
  const int cpowm_threads_per_blk = cpowm_warp_per_blk * 32;

  const size_t cpowm_ct_bytes =
      (size_t)batch * cpowm_limbs_per_num * sizeof(uint64_t);
  const size_t cpowm_expbits_bytes =
      (size_t)batch * cpowm_tau * sizeof(uint64_t);

  // ---- Step 1：明文展开为 LSB-first bit 数组 ----
  uint64_t *exp_bits_host = (uint64_t *)malloc(cpowm_expbits_bytes);
  if (!exp_bits_host) {
    fprintf(stderr, "[paillier_cpowm] malloc exp_bits_host 失败\n");
    return;
  }

  for (int p = 0; p < batch; p++) {
    const uint64_t *e = h_plaintexts + (size_t)p * cpowm_exp_u64_limbs;
    uint64_t *bits = exp_bits_host + (size_t)p * cpowm_tau;
    for (int i = 0; i < cpowm_tau; i++) {
      int limb_idx = i / 64;
      int bit_idx = i % 64;
      bits[i] = (e[limb_idx] >> bit_idx) & 1ULL;
    }
  }

  // ---- Step 2：分配 device 内存并传输 ----
  uint64_t *d_ciphertexts = NULL;
  uint64_t *d_output = NULL;
  uint64_t *d_exp_bits = NULL;

  cudaMalloc(&d_ciphertexts, cpowm_ct_bytes);
  cudaMalloc(&d_output, cpowm_ct_bytes);
  cudaMalloc(&d_exp_bits, cpowm_expbits_bytes);

  cudaMemcpy(d_ciphertexts, h_ciphertexts, cpowm_ct_bytes,
             cudaMemcpyHostToDevice);
  cudaMemcpy(d_exp_bits, exp_bits_host, cpowm_expbits_bytes,
             cudaMemcpyHostToDevice);

  cudaError_t err = cudaGetLastError();
  if (err != cudaSuccess) {
    fprintf(stderr, "[paillier_cpowm] 内存传输失败: %s\n",
            cudaGetErrorString(err));
    goto cpowm_cleanup;
  }

  // ---- Step 3：调用内核 ----
  {
    int n_blocks = (batch + cpowm_warp_per_blk - 1) / cpowm_warp_per_blk;
    size_t smem_size = (size_t)cpowm_warp_per_blk * 512 * sizeof(uint64_t);

    FMLMKernel_e<<<n_blocks, cpowm_threads_per_blk, smem_size>>>(
        d_ciphertexts, d_exp_bits, cpowm_tau, d_output, batch, d_r0, d_r1_ct,
        d_r1_nct, d_negModn, d_negModn_shoup, d_Modn, d_Modn_shoup, n_poly, mod,
        d_twiddle, d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup,
        d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
        d_InvNCTtwiddle_shoup, inv, inv_shoup, d_sample);

    cudaDeviceSynchronize();
    err = cudaGetLastError();
    if (err != cudaSuccess) {
      fprintf(stderr, "[paillier_cpowm] 内核执行失败: %s\n",
              cudaGetErrorString(err));
      goto cpowm_cleanup;
    }
  }

  // ---- Step 4：拷回结果 ----
  cudaMemcpy(h_output, d_output, cpowm_ct_bytes, cudaMemcpyDeviceToHost);

cpowm_cleanup:
  free(exp_bits_host);
  if (d_ciphertexts) cudaFree(d_ciphertexts);
  if (d_output) cudaFree(d_output);
  if (d_exp_bits) cudaFree(d_exp_bits);
}

#define NUM_TESTS 200000
#define ARR_LEN 256
#define BASE_BITS 17
#define BASE (1ULL << BASE_BITS)  // 131072

// n 是 2048-bit，在 base 2^17 下约占 121 个 limb
// 超出部分为 0，无需额外处理（循环自然跳过）
#define N_WORDS 121

#ifndef THREADS_PER_BLOCK
#define THREADS_PER_BLOCK (WARPS_PER_BLOCK * 32)
#endif

#define NUM_STREAMS 4
#define CHUNK (NUM_TESTS / NUM_STREAMS)

static void gen_random_bignum(uint64_t *out, int max_nonzero) {
  for (int i = 0; i < ARR_LEN; i++) {
    if (i < max_nonzero) {
      uint64_t lo = (uint64_t)rand();
      uint64_t hi = (uint64_t)rand();
      out[i] = ((hi << 15) | lo) % BASE;
    } else {
      out[i] = 0;
    }
  }
}

// -------------------------------------------------------------
// 随机大数生成（limb 限制在 n² 有效范围内）
// modn：n² 的 limb 表示，确定有效 limb 上界
// -------------------------------------------------------------
static void generate_random_bignum(uint64_t *out, const uint64_t *modn) {
  // 找 modn 最高非零 limb 的位置
  int max_idx = 0;
  for (int i = ARR_LEN - 1; i >= 0; i--) {
    if (modn[i] != 0) {
      max_idx = i;
      break;
    }
  }
  // 只填充低于 max_idx 的 limb，保证生成值 < n²
  for (int i = 0; i < ARR_LEN; i++) {
    if (i < max_idx) {
      uint64_t lo = (uint64_t)rand();
      uint64_t hi = (uint64_t)rand();
      out[i] = ((hi << 15) | lo) % BASE;
    } else {
      out[i] = 0;
    }
  }
}

// =============================================================
// GPU 端 Step1：批量计算 (1 ± m*n) mod n²
//
// 线程布局：
//   gridDim.x  = NUM_TESTS（每个 block 负责一个测试用例）
//   blockDim.x = ARR_LEN   （每个 block 的线程数 = limb 数量）
//
// 并行策略：
//   ├─ 并行阶段：线程 i 计算 prod[i] = Σ m[j]·n[i-j]（不含进位）
//   │             每项 m[j]·n[k] < 2^34，累加 256 项 < 2^42，不溢出 uint64_t
//   └─ 串行阶段：线程 0 做进位传播 + ±1 调整
//                （各 block 间独立，不影响总并行度）
// =============================================================
__global__ void compute_plain_factor_batch_kernel(
    const uint64_t *__restrict__ d_m_batch,  // [NUM_TESTS * ARR_LEN] 明文批
    const uint64_t *__restrict__ d_n,        // [ARR_LEN]  公钥 n
    const uint64_t *__restrict__ d_n2,       // [ARR_LEN]  模数 n²
    uint64_t *d_factor,                      // [NUM_TESTS * ARR_LEN] 输出
    int sign                                 // +1: AddPlain, -1: SubPlain
) {
  int test_id = blockIdx.x;
  int i = threadIdx.x;  // 当前线程负责第 i 个 limb

  if (test_id >= NUM_TESTS || i >= ARR_LEN) return;

  const uint64_t *m = d_m_batch + (size_t)test_id * ARR_LEN;
  uint64_t *out = d_factor + (size_t)test_id * ARR_LEN;

  // ── 共享内存：m*n 的乘积（不含进位的中间值）──────────────────
  __shared__ uint64_t prod[ARR_LEN];

  // ── 并行阶段：计算第 i 个 limb 的偏积和 ──────────────────────
  // prod[i] = Σ_{j=0}^{i} m[j] * n[i-j]
  // （m[j]=0 for j≥N_WORDS, n[k]=0 for k≥N_WORDS，自动截断）
  uint64_t sum = 0;
  for (int j = 0; j <= i; j++) {
    // j < N_WORDS 且 (i-j) < N_WORDS 才有非零贡献
    sum += m[j] * d_n[i - j];
  }
  prod[i] = sum;

  __syncthreads();

  // ── 串行阶段（仅线程 0）：进位传播 + ±1 ─────────────────────
  if (i == 0) {
    // ① 进位传播（m*n 的 limb 规格化到 [0, BASE)）
    for (int k = 0; k < ARR_LEN - 1; k++) {
      prod[k + 1] += prod[k] >> BASE_BITS;
      prod[k] &= BASE - 1;
    }

    if (sign > 0) {
      // ② AddPlain：prod = mn，加 1 → (1+mn)
      prod[0] += 1;
      for (int k = 0; k < ARR_LEN - 1; k++) {
        if (prod[k] < BASE) break;
        prod[k + 1] += prod[k] >> BASE_BITS;
        prod[k] &= BASE - 1;
      }

    } else {
      // ② SubPlain：(1-mn) mod n² = n² - mn + 1（因 mn > 1）
      //   Step A: n² - mn（大数减法）
      int64_t borrow = 0;
      for (int k = 0; k < ARR_LEN; k++) {
        int64_t diff = (int64_t)d_n2[k] - (int64_t)prod[k] - borrow;
        if (diff < 0) {
          prod[k] = (uint64_t)(diff + (int64_t)BASE);
          borrow = 1;
        } else {
          prod[k] = (uint64_t)diff;
          borrow = 0;
        }
      }
      //   Step B: + 1
      prod[0] += 1;
      for (int k = 0; k < ARR_LEN - 1; k++) {
        if (prod[k] < BASE) break;
        prod[k + 1] += prod[k] >> BASE_BITS;
        prod[k] &= BASE - 1;
      }
    }

    // ③ 写出结果
    for (int k = 0; k < ARR_LEN; k++) out[k] = prod[k];
  }
}

// =============================================================
// 计时结构体
// =============================================================
struct StepTime {
  float step1_ms;  // compute_plain_factor (GPU bignum 乘法)
  float step2_ms;  // XYfixWarpROneVector（转入蒙哥马利域）
  float step3_ms;  // XYfixWarpVector（与 c̃1 相乘）
  float h2d_ms;    // 数据上传
  float d2h_ms;    // 结果下载
};

/*
// =============================================================
// paillier_addplain_subplain_batch
// 完整批量运算：H2D → Step1 → Step2 → Step3 → D2H
// =============================================================
StepTime paillier_addplain_subplain_batch(
    uint64_t *h_c1_tilde,     // [NUM_TESTS*ARR_LEN] 蒙哥马利密文输入 (pinned)
    uint64_t *h_m_batch,      // [NUM_TESTS*ARR_LEN] 明文 m 批          (pinned)
    uint64_t *h_result,       // [NUM_TESTS*ARR_LEN] 输出               (pinned)
    uint64_t *d_n,            // [ARR_LEN] 公钥 n（已在 GPU）
    uint64_t *d_n2,           // [ARR_LEN] 模数 n²（已在 GPU）
    uint64_t *d_r1_ct,        // [ARR_LEN] R² mod n² 的 CT  形式（已在 GPU）
    uint64_t *d_r1_nct,       // [ARR_LEN] R² mod n² 的 NCT 形式（已在 GPU）
    uint64_t *d_negmodn,      uint64_t *d_negmodn_shoup,
    uint64_t *d_modn,         uint64_t *d_modn_shoup,
    uint64_t  mod,
    uint64_t *d_twiddle,      uint64_t *d_twiddle_shoup,
    uint64_t *d_ICTTwiddle,   uint64_t *d_ICTTwiddle_shoup,
    uint64_t *d_NCTtwiddle,   uint64_t *d_NCTtwiddle_shoup,
    uint64_t *d_InvNCTtwiddle,uint64_t *d_InvNCTtwiddle_shoup,
    uint64_t  inv_val,        uint64_t  inv_shoup_val,
    uint64_t *d_sample,
    int       sign             // +1: AddPlain, -1: SubPlain
)
{
    const size_t batch_bytes = (size_t)NUM_TESTS * ARR_LEN * sizeof(uint64_t);
    const int blocks_per_batch =
        (NUM_TESTS + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK;
    dim3 fmlm_grid(blocks_per_batch);
    dim3 fmlm_block(THREADS_PER_BLOCK);

    StepTime t = {0,0,0,0,0};

    // ── 分配 GPU 工作缓冲区 ────────────────────────────────────────
    // d_factor_mont 不再需要：XYfixWarpROneVector 原地写回 d_factor
    // d_R2_batch    不再需要：R² 以 d_r1_ct/d_r1_nct 直接传入
    uint64_t *d_c1, *d_m, *d_factor;
    CUDA_CHECK(cudaMalloc(&d_c1,     batch_bytes));
    CUDA_CHECK(cudaMalloc(&d_m,      batch_bytes));
    CUDA_CHECK(cudaMalloc(&d_factor, batch_bytes));  // (1±mn) → 原地转换为
(1̃±mn)

    cudaEvent_t e0, e1;
    CUDA_CHECK(cudaEventCreate(&e0));
    CUDA_CHECK(cudaEventCreate(&e1));

    // ============================================================
    // H2D：上传 c̃1 和 m 批
    // ============================================================
    CUDA_CHECK(cudaEventRecord(e0));
    CUDA_CHECK(cudaMemcpy(d_c1, h_c1_tilde, batch_bytes,
cudaMemcpyHostToDevice)); CUDA_CHECK(cudaMemcpy(d_m,  h_m_batch,  batch_bytes,
cudaMemcpyHostToDevice)); CUDA_CHECK(cudaEventRecord(e1));
    CUDA_CHECK(cudaEventSynchronize(e1));
    CUDA_CHECK(cudaEventElapsedTime(&t.h2d_ms, e0, e1));

    // ============================================================
    // Step1：计算 (1 ± m*n) mod n²（GPU 大数乘法）
    //
    // 每个 block = 一个测试用例
    // 线程 i 并行计算 prod[i]，线程 0 做进位和±1调整
    // ============================================================
    CUDA_CHECK(cudaEventRecord(e0));
    compute_plain_factor_batch_kernel<<<NUM_TESTS, ARR_LEN>>>(
        d_m, d_n, d_n2, d_factor, sign
    );
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaEventRecord(e1));
    CUDA_CHECK(cudaEventSynchronize(e1));
    CUDA_CHECK(cudaEventElapsedTime(&t.step1_ms, e0, e1));

    // ============================================================
    // Step2：(1±mn) 转入蒙哥马利域
    //   XYfixWarpROneVector(factor, d_r1_ct, d_r1_nct)
    //   等价于 FMLM((1±mn), R²) = (1±mn)·R
    //
    //   R² 以预存的 CT/NCT 形式直接传入，无需 broadcast
    //   结果原地写回 d_factor：普通域 → 蒙哥马利域
    // ============================================================
    CUDA_CHECK(cudaEventRecord(e0));
    XYfixWarpROneVector<<<fmlm_grid, fmlm_block>>>(
        d_factor,                          // inout：(1±mn) → (1̃±mn)，原地写回
        d_r1_ct,                           // inoutAct：R² 的 CT  形式
        d_r1_nct,                          // inoutAnct：R² 的 NCT 形式
        d_negmodn, d_negmodn_shoup,
        d_modn,    d_modn_shoup,
        (uint64_t)ARR_LEN, mod,
        d_twiddle,        d_twiddle_shoup,
        d_ICTTwiddle,     d_ICTTwiddle_shoup,
        d_NCTtwiddle,     d_NCTtwiddle_shoup,
        d_InvNCTtwiddle,  d_InvNCTtwiddle_shoup,
        inv_val, inv_shoup_val, d_sample
    );
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaEventRecord(e1));
    CUDA_CHECK(cudaEventSynchronize(e1));
    CUDA_CHECK(cudaEventElapsedTime(&t.step2_ms, e0, e1));

    // ============================================================
    // Step3：c̃1 与 (1̃±mn) 相乘
    //   FMLM( c̃1, (1̃±mn) ) = c1·R · (1±mn)·R · R⁻¹
    //                        = c1·(1±mn)·R  ✓
    //
    //   d_factor 此时已是蒙哥马利形式（Step2 原地写回）
    //   d_c1 存放 c̃1，结果写回 d_c1
    // ============================================================
    CUDA_CHECK(cudaEventRecord(e0));
    XYfixWarpVector<<<fmlm_grid, fmlm_block>>>(
        d_c1, d_factor,                    // FMLM(c̃1, (1̃±mn))
        d_negmodn, d_negmodn_shoup,
        d_modn,    d_modn_shoup,
        (uint64_t)ARR_LEN, mod,
        d_twiddle,        d_twiddle_shoup,
