    return t;
}
*/

// ============================================================
// 修改后的 paillier_addplain_subplain_batch
//
// 变化：
//   · 不再接收 h_c1_tilde / h_m_batch / h_result（主机指针）
//   · 改为接收 d_c1 / d_m（已在 GPU 上的设备指针）
//   · 内部不做 H2D / D2H，也不 cudaMalloc/cudaFree d_c1 和 d_m
//   · d_c1 同时作为输入（c̃1）和输出（Step3 结果写回）
//   · d_factor 仍在函数内部分配/释放（临时工作缓冲）
//   · h2d_ms / d2h_ms 固定为 0，由外部计时
// ============================================================
StepTime paillier_addplain_subplain_batch(
    uint64_t *d_c1,  // [NUM_TESTS*ARR_LEN] device: 蒙哥马利密文（输入兼输出）
    uint64_t *d_m,   // [NUM_TESTS*ARR_LEN] device: 明文 m 批（已上传）
    uint64_t *d_n,   // [ARR_LEN] 公钥 n（已在 GPU）
    uint64_t *d_n2,  // [ARR_LEN] 模数 n²（已在 GPU）
    uint64_t *d_r1_ct,   // [ARR_LEN] R² mod n² 的 CT  形式（已在 GPU）
    uint64_t *d_r1_nct,  // [ARR_LEN] R² mod n² 的 NCT 形式（已在 GPU）
    uint64_t *d_negmodn, uint64_t *d_negmodn_shoup, uint64_t *d_modn,
    uint64_t *d_modn_shoup, uint64_t mod, uint64_t *d_twiddle,
    uint64_t *d_twiddle_shoup, uint64_t *d_ICTTwiddle,
    uint64_t *d_ICTTwiddle_shoup, uint64_t *d_NCTtwiddle,
    uint64_t *d_NCTtwiddle_shoup, uint64_t *d_InvNCTtwiddle,
    uint64_t *d_InvNCTtwiddle_shoup, uint64_t inv_val, uint64_t inv_shoup_val,
    uint64_t *d_sample,
    int sign  // +1: AddPlain, -1: SubPlain
) {
  const size_t batch_bytes = (size_t)NUM_TESTS * ARR_LEN * sizeof(uint64_t);
  const int blocks_per_batch =
      (NUM_TESTS + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK;
  dim3 fmlm_grid(blocks_per_batch);
  dim3 fmlm_block(THREADS_PER_BLOCK);

  // h2d_ms / d2h_ms 由外部测量，此处置 0
  StepTime t = {0, 0, 0, 0, 0};

  // 只分配内部临时工作缓冲 d_factor（(1±mn) 及其蒙哥马利形式）
  // d_c1、d_m 由调用者传入，不在此处分配或释放
  uint64_t *d_factor;
  CUDA_CHECK(cudaMalloc(&d_factor, batch_bytes));

  cudaEvent_t e0, e1;
  CUDA_CHECK(cudaEventCreate(&e0));
  CUDA_CHECK(cudaEventCreate(&e1));

  // ============================================================
  // Step1：计算 (1 ± m*n) mod n²（GPU 大数乘法）
  //   输入：d_m（明文批）、d_n（公钥 n）、d_n2（模数 n²）
  //   输出：d_factor = (1 ± m*n) mod n²
  // ============================================================
  CUDA_CHECK(cudaEventRecord(e0));
  compute_plain_factor_batch_kernel<<<NUM_TESTS, ARR_LEN>>>(d_m, d_n, d_n2,
                                                            d_factor, sign);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaEventRecord(e1));
  CUDA_CHECK(cudaEventSynchronize(e1));
  CUDA_CHECK(cudaEventElapsedTime(&t.step1_ms, e0, e1));

  // ============================================================
  // Step2：将 (1±mn) 转入蒙哥马利域
  //   XYfixWarpROneVector 等价于 FMLM((1±mn), R²) = (1±mn)·R
  //   结果原地写回 d_factor
  // ============================================================
  CUDA_CHECK(cudaEventRecord(e0));
  XYfixWarpROneVector<<<fmlm_grid, fmlm_block>>>(
      d_factor, d_r1_ct, d_r1_nct, d_negmodn, d_negmodn_shoup, d_modn,
      d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup,
      d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup,
      d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaEventRecord(e1));
  CUDA_CHECK(cudaEventSynchronize(e1));
  CUDA_CHECK(cudaEventElapsedTime(&t.step2_ms, e0, e1));

  // ============================================================
  // Step3：FMLM(d_c1, d_factor) = c1*(1±mn)*R
  //   结果写回 d_c1（同一缓冲区，调用者读取 D2H 后即为最终输出）
  // ============================================================
  CUDA_CHECK(cudaEventRecord(e0));
  XYfixWarpVector<<<fmlm_grid, fmlm_block>>>(
      d_c1, d_factor, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
      (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
      d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
      d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaEventRecord(e1));
  CUDA_CHECK(cudaEventSynchronize(e1));
  CUDA_CHECK(cudaEventElapsedTime(&t.step3_ms, e0, e1));

  cudaEventDestroy(e0);
  cudaEventDestroy(e1);
  CUDA_CHECK(cudaFree(d_factor));
  // d_c1 和 d_m 由调用者负责 cudaFree

  return t;
}

// ============================================================
// 打印计时报告（含外部测量的 H2D / D2H）
// ============================================================
static void print_steptime_ext(const char *label, const StepTime &t,
                               float h2d_ms,  // 外部测量的 H2D 时间
                               float d2h_ms   // 外部测量的 D2H 时间
) {
  float compute_ms = t.step1_ms + t.step2_ms + t.step3_ms;
  float total_ms = h2d_ms + compute_ms + d2h_ms;

  printf("\n======================================================\n");
  printf("  %s 计时报告\n", label);
  printf("======================================================\n");
  printf("  [外部] H2D 上传            : %8.4f ms\n", h2d_ms);
  printf("  Step1  (1+-mn) GPU 大数乘  : %8.4f ms\n", t.step1_ms);
  printf("  Step2  转蒙哥马利域        : %8.4f ms  [XYfixWarpROneVector]\n",
         t.step2_ms);
  printf("  Step3  与密文相乘          : %8.4f ms  [XYfixWarpVector]\n",
         t.step3_ms);
  printf("  [外部] D2H 下载            : %8.4f ms\n", d2h_ms);
  printf("  ──────────────────────────────────────────\n");
  printf("  端到端总时间               : %8.4f ms\n", total_ms);
  printf("  平均单次 Step1+2+3         : %8.4f us/次\n",
         compute_ms * 1000.f / NUM_TESTS);
  printf("  平均单次端到端             : %8.4f us/次\n",
         total_ms * 1000.f / NUM_TESTS);
  printf("======================================================\n");
}

// =============================================================
// 打印计时报告
// =============================================================
static void print_steptime(const char *label, const StepTime &t) {
  float total = t.h2d_ms + t.step1_ms + t.step2_ms + t.step3_ms + t.d2h_ms;
  printf("\n======================================================\n");
  printf("  %s 计时报告\n", label);
  printf("======================================================\n");
  printf("  H2D  上传              : %8.4f ms\n", t.h2d_ms);
  printf("  Step1 (1±mn) GPU大数乘 : %8.4f ms\n", t.step1_ms);
  printf("  Step2 转蒙哥马利域     : %8.4f ms  [XYfixWarpROneVector]\n",
         t.step2_ms);
  printf("  Step3 与密文相乘       : %8.4f ms  [XYfixWarpVector(c̃1, factor)]\n",
         t.step3_ms);
  printf("  D2H  下载              : %8.4f ms\n", t.d2h_ms);
  printf("  ──────────────────────────────────────────────\n");
  printf("  端到端总时间           : %8.4f ms\n", total);
  printf("  平均单次 Step1+2+3     : %8.4f us/次\n",
         (t.step1_ms + t.step2_ms + t.step3_ms) * 1000.f / NUM_TESTS);
  printf("  平均单次端到端         : %8.4f us/次\n",
         total * 1000.f / NUM_TESTS);
  printf("======================================================\n");
}

// =============================================================
// 写 txt 供 Python 验证
// 格式：
//   行1：NUM_TESTS ARR_LEN BASE_BITS
//   行2：Modn (n²) limbs
//   行3：N_arr (n)  limbs  ← 验证需要 n
//   每个测试用例 3 行：m / c1_tilde / result
// =============================================================
static void write_results_to_txt(const char *filename,
                                 const uint64_t *h_m_batch,
                                 const uint64_t *h_c1_tilde,
                                 const uint64_t *h_result, const uint64_t *modn,
                                 const uint64_t *n_arr) {
  FILE *fp = fopen(filename, "w");
  if (!fp) {
    fprintf(stderr, "无法创建 %s\n", filename);
    return;
  }

  fprintf(fp, "%d %d %d\n", NUM_TESTS, ARR_LEN, BASE_BITS);

  // n² limbs
  for (int j = 0; j < ARR_LEN; j++) {
    fprintf(fp, "%llu", (unsigned long long)modn[j]);
    fprintf(fp, j < ARR_LEN - 1 ? " " : "\n");
  }
  // n limbs
  for (int j = 0; j < ARR_LEN; j++) {
    fprintf(fp, "%llu", (unsigned long long)n_arr[j]);
    fprintf(fp, j < ARR_LEN - 1 ? " " : "\n");
  }

  for (int i = 0; i < NUM_TESTS; i++) {
    const uint64_t *m = h_m_batch + (size_t)i * ARR_LEN;
    const uint64_t *c1 = h_c1_tilde + (size_t)i * ARR_LEN;
    const uint64_t *res = h_result + (size_t)i * ARR_LEN;
    for (int j = 0; j < ARR_LEN; j++) {
      fprintf(fp, "%llu", (unsigned long long)m[j]);
      fprintf(fp, j < ARR_LEN - 1 ? " " : "\n");
    }
    for (int j = 0; j < ARR_LEN; j++) {
      fprintf(fp, "%llu", (unsigned long long)c1[j]);
      fprintf(fp, j < ARR_LEN - 1 ? " " : "\n");
    }
    for (int j = 0; j < ARR_LEN; j++) {
      fprintf(fp, "%llu", (unsigned long long)res[j]);
      fprintf(fp, j < ARR_LEN - 1 ? " " : "\n");
    }
  }
  fclose(fp);
  printf("结果已写入 %s\n", filename);
}

// =============================================================
// broadcast_fill_kernel
// 将单个 ARR_LEN 的大数广播到 batch × ARR_LEN 的目标批量数组
// dst[test_id * ARR_LEN + limb] = src[limb]
// =============================================================
__global__ void broadcast_fill_kernel(uint64_t *dst, const uint64_t *src,
                                      int batch) {
  int tid = blockIdx.x * blockDim.x + threadIdx.x;
  if (tid >= batch * ARR_LEN) return;
  dst[tid] = src[tid % ARR_LEN];
}

// =============================================================
// paillier_randomize 计时结构体
// =============================================================
struct RandomizeTiming {
  float step1_ms;     // h_s → h̃_s（XYfixWarpROneVector，1 warp）
  float step2_ms;     // 广播（broadcast_fill_kernel）
  float step3_ms;     // FMLE 阶段耗时（各流并行，取最慢流）
  float step4_ms;     // XY 阶段耗时（各流并行，取最慢流）
  float pipeline_ms;  // Step③+④ 流水线实际墙钟时间（< step3+step4）
};

// =============================================================
// paillier_randomize
//
// 功能：批量 Randomize 同态操作
//   c̃_out[i] = c₁[i] · h_s^{r_i} · R mod n²  （蒙哥马利形式）
//
// 数据流：
//   Step①  XYfixWarpROneVector: h_s → h̃_s = h_s · R        （1 warp）
//   Step②  broadcast_fill_kernel: h̃_s → d_hs_batch[batch]
//   Step③  FMLE_mod2_Kernel:  h̃_s^{r_i}（蒙→蒙，多流）
//   Step④  XYfixWarpVector:   c̃₁[i] · h̃_s^{r_i}（结果→c̃_out）
//
// 注意：
//   · 所有指针均为设备指针，函数内部不做 H2D / D2H
//   · d_hs_single 会被原地覆写为 h̃_s = h_s · R（调用者如需保留原值需自行备份）
//   · d_c1 既是输入也是输出（原地更新）
//   · d_r_batch 格式：batch × (tau/64) 个 uint64_t，压缩存储每个 r_i
// =============================================================
RandomizeTiming paillier_randomize(
    uint64_t *d_c1,         // [batch × ARR_LEN]  蒙哥马利密文（输入兼输出）
    uint64_t *d_hs_single,  // [ARR_LEN]          h_s 普通域（原地改写为 h̃_s）
    const uint64_t *d_r_batch,  // [batch × (tau/64)] 压缩随机指数 r_i
    int batch,
    int tau,                   // 指数 bit 长度
    const uint64_t *d_r0,      // [ARR_LEN]  R mod n²（1 的蒙哥马利形式）
    const uint64_t *d_r1_ct,   // [ARR_LEN]  R² 的 CT 形式
    const uint64_t *d_r1_nct,  // [ARR_LEN]  R² 的 NCT 形式
    uint64_t *d_negmodn, uint64_t *d_negmodn_shoup, uint64_t *d_modn,
    uint64_t *d_modn_shoup, uint64_t mod, const uint64_t *d_twiddle,
    const uint64_t *d_twiddle_shoup, const uint64_t *d_ICTTwiddle,
    const uint64_t *d_ICTTwiddle_shoup, const uint64_t *d_NCTtwiddle,
    const uint64_t *d_NCTtwiddle_shoup, const uint64_t *d_InvNCTtwiddle,
    const uint64_t *d_InvNCTtwiddle_shoup, uint64_t inv_val,
    uint64_t inv_shoup_val, const uint64_t *d_sample) {
  RandomizeTiming t = {0.f, 0.f, 0.f, 0.f, 0.f};
  const size_t batch_bytes = (size_t)batch * ARR_LEN * sizeof(uint64_t);

  cudaEvent_t e0, e1;
  CUDA_CHECK(cudaEventCreate(&e0));
  CUDA_CHECK(cudaEventCreate(&e1));

  // ─────────────────────────────────────────────────────────────
  // Step①：h_s → h̃_s = h_s · R mod n²
  //   1 block × 32 threads（单 warp）覆盖 ARR_LEN=256 个 limb
  //   结果原地写回 d_hs_single
  // ─────────────────────────────────────────────────────────────
  CUDA_CHECK(cudaEventRecord(e0));
  XYfixWarpROneVector<<<1, 32>>>(
      d_hs_single, const_cast<uint64_t *>(d_r1_ct),
      const_cast<uint64_t *>(d_r1_nct), d_negmodn, d_negmodn_shoup, d_modn,
      d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup,
      d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup,
      d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaEventRecord(e1));
  CUDA_CHECK(cudaEventSynchronize(e1));
  CUDA_CHECK(cudaEventElapsedTime(&t.step1_ms, e0, e1));

  // ─────────────────────────────────────────────────────────────
  // Step②：广播 h̃_s[ARR_LEN] → d_hs_batch[batch × ARR_LEN]
  // ─────────────────────────────────────────────────────────────
  uint64_t *d_hs_batch;
  CUDA_CHECK(cudaMalloc(&d_hs_batch, batch_bytes));
  {
    const int total = batch * ARR_LEN;
    const int blk = 256;
    const int grd = (total + blk - 1) / blk;
    CUDA_CHECK(cudaEventRecord(e0));
    broadcast_fill_kernel<<<grd, blk>>>(d_hs_batch, d_hs_single, batch);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaEventRecord(e1));
    CUDA_CHECK(cudaEventSynchronize(e1));
    CUDA_CHECK(cudaEventElapsedTime(&t.step2_ms, e0, e1));
  }

  // ─────────────────────────────────────────────────────────────
  // Step③+④ 流水线：每条流独立处理一个 chunk
  //
  //   旧方案（串行）：
  //     Stream0..3: [FMLE₀][FMLE₁][FMLE₂][FMLE₃] → sync → [XY_all]
  //
  //   新方案（流水线）：
  //     Stream 0: [FMLE₀ ───────────────────][XY₀ ───]
  //     Stream 1:  [FMLE₁ ──────────────────] [XY₁ ──]
  //     Stream 2:   [FMLE₂ ─────────────────]  [XY₂ ─]
  //     Stream 3:    [FMLE₃ ────────────────]   [XY₃ ]
  //
  //   XY₀ 可与 FMLE₁/₂/₃ 并发，节省 (NUM_STREAMS-1)×XY_chunk 时间
  // ─────────────────────────────────────────────────────────────
  uint64_t *d_hs_r;
  CUDA_CHECK(cudaMalloc(&d_hs_r, batch_bytes));
  {
    const int chunk = (batch + NUM_STREAMS - 1) / NUM_STREAMS;
    const int exp_limbs = tau / 64;
    const size_t smem_size = (size_t)WARP_PER_BLK * 512 * sizeof(uint64_t);

    cudaStream_t streams[NUM_STREAMS];
    // ev_fmle_done[s]: 流 s 的 FMLE 完成时刻
    // ev_xy_done[s]  : 流 s 的 XY  完成时刻
    cudaEvent_t ev_fmle_done[NUM_STREAMS];
    cudaEvent_t ev_xy_done[NUM_STREAMS];
    for (int s = 0; s < NUM_STREAMS; s++) {
      CUDA_CHECK(cudaStreamCreate(&streams[s]));
      CUDA_CHECK(cudaEventCreate(&ev_fmle_done[s]));
      CUDA_CHECK(cudaEventCreate(&ev_xy_done[s]));
    }
    cudaEvent_t ev_pipe_start;
    CUDA_CHECK(cudaEventCreate(&ev_pipe_start));
    // 在默认流上打起始时间戳，后续所有流从此刻开始计时
    CUDA_CHECK(cudaEventRecord(ev_pipe_start, 0));

    for (int s = 0; s < NUM_STREAMS; s++) {
      int offset = s * chunk;
      if (offset >= batch) break;
      int actual = (offset + chunk > batch) ? (batch - offset) : chunk;
      int fmle_blks = (actual + WARP_PER_BLK - 1) / WARP_PER_BLK;
      // ★ 注意：XY 使用 actual 个 1-warp 块（32 线程/块）而非 ceil(actual/8) 个
      // 8-warp 块。 原因：若 actual 不能被 WARPS_PER_BLOCK=8 整除，ceil
      // 会多出若干 warp，
      //        这些 warp 会越界读写相邻流的 d_c1/d_hs_r 区域，造成竞争条件。
      // 使用 1-warp/块启动恰好产生 actual 个 warp，不产生越界访问。
      // XYfixWarpVector 使用 lane_id = threadIdx.x & 0x1F 做 warp 内索引，
      // 与 blockDim.x=32 或 256 等价，结果完全正确。

      size_t ct_off = (size_t)offset * ARR_LEN;
      size_t exp_off = (size_t)offset * exp_limbs;

      // ── Step③：FMLE（h̃_s^{r_i}，蒙→蒙） ──
      FMLE_mod2_Kernel<<<fmle_blks, WARP_PER_BLK * 32, smem_size, streams[s]>>>(
          d_hs_batch + ct_off, d_r_batch + exp_off, tau, d_hs_r + ct_off,
          actual, d_r0, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
          (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
          d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
          d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
      // 同一流上记录 FMLE 完成时间（无需额外同步，流内串行保证正确性）
      CUDA_CHECK(cudaEventRecord(ev_fmle_done[s], streams[s]));

      // ── Step④：XY（c̃₁·h̃_s^{r_i}，在同一流上立即接续） ──
      // 同一流内核顺序执行，FMLE 完成后才会执行 XY，无需显式 Event 等待
      // actual 个块 × 32 线程/块 = 恰好 actual 个 warp，无越界
      XYfixWarpVector<<<actual, 32, 0, streams[s]>>>(
          d_c1 + ct_off, d_hs_r + ct_off, d_negmodn, d_negmodn_shoup, d_modn,
          d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup,
          d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup,
          d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val,
          d_sample);
      CUDA_CHECK(cudaEventRecord(ev_xy_done[s], streams[s]));
    }

    // 等待所有流完成
    CUDA_CHECK(cudaDeviceSynchronize());
    CUDA_CHECK(cudaGetLastError());

    // ── 统计各流耗时，取最慢流 ──
    float max_fmle_ms = 0.f;
    float max_xy_ms = 0.f;
    float max_pipe_ms = 0.f;
    for (int s = 0; s < NUM_STREAMS; s++) {
      if (s * chunk >= batch) break;
      float fmle_ms = 0.f, xy_ms = 0.f, total_ms = 0.f;
      // FMLE 耗时：从流水线起点到该流 FMLE 完成
      CUDA_CHECK(
          cudaEventElapsedTime(&fmle_ms, ev_pipe_start, ev_fmle_done[s]));
      // XY 耗时：从该流 FMLE 完成到 XY 完成
      CUDA_CHECK(cudaEventElapsedTime(&xy_ms, ev_fmle_done[s], ev_xy_done[s]));
      // 流水线总耗时：从起点到该流 XY 完成
      CUDA_CHECK(cudaEventElapsedTime(&total_ms, ev_pipe_start, ev_xy_done[s]));
      if (fmle_ms > max_fmle_ms) max_fmle_ms = fmle_ms;
      if (xy_ms > max_xy_ms) max_xy_ms = xy_ms;
      if (total_ms > max_pipe_ms) max_pipe_ms = total_ms;
    }
    t.step3_ms = max_fmle_ms;
    t.step4_ms = max_xy_ms;
    t.pipeline_ms = max_pipe_ms;

    for (int s = 0; s < NUM_STREAMS; s++) {
      cudaStreamDestroy(streams[s]);
      cudaEventDestroy(ev_fmle_done[s]);
      cudaEventDestroy(ev_xy_done[s]);
    }
    cudaEventDestroy(ev_pipe_start);
  }
  CUDA_CHECK(cudaFree(d_hs_batch));
  CUDA_CHECK(cudaFree(d_hs_r));
  CUDA_CHECK(cudaEventDestroy(e0));
  CUDA_CHECK(cudaEventDestroy(e1));

  return t;
}

// =============================================================
// paillier_dec
//
// 功能：GPU 批量 Paillier 解密模幂（非 CRT 路线）
//   output[i] = c[i]^λ mod n²（普通域）
//
// 输入 d_c_tilde 为蒙哥马利域密文 c̃ = c·R mod n²，
// 调用 FMLE_mod3_Kernel：跳过 Step8（输入已是蒙哥马利域），
// 保留 Step13（将结果还原到普通域）。
//
// 参数：
//   d_c_tilde  [batch × ARR_LEN]       输入：c̃（蒙哥马利域）
//   d_exp      [batch × tau/64]         指数 λ（压缩格式：每案例 tau/64 个
//   uint64_t） d_output   [batch × ARR_LEN]       输出：c^λ mod n²（普通域）
//   batch                               批大小
//   tau                                 λ 的 bit 长度
//   d_r0       [ARR_LEN]               R mod n²（1 的蒙哥马利表示）
//   其余为 NTT 参数（与 paillier_mulplain 完全一致）
//
// 返回：GPU 端到端墙钟耗时（ms）
// =============================================================
float paillier_dec(
    const uint64_t *d_c_tilde, const uint64_t *d_exp, uint64_t *d_output,
    int batch, int tau, const uint64_t *d_r0, uint64_t *d_negmodn,
    uint64_t *d_negmodn_shoup, uint64_t *d_modn, uint64_t *d_modn_shoup,
    uint64_t mod, const uint64_t *d_twiddle, const uint64_t *d_twiddle_shoup,
    const uint64_t *d_ICTTwiddle, const uint64_t *d_ICTTwiddle_shoup,
    const uint64_t *d_NCTtwiddle, const uint64_t *d_NCTtwiddle_shoup,
    const uint64_t *d_InvNCTtwiddle, const uint64_t *d_InvNCTtwiddle_shoup,
    uint64_t inv_val, uint64_t inv_shoup_val, const uint64_t *d_sample) {
  const int exp_u64_limbs = tau / 64;
  const int chunk = (batch + NUM_STREAMS - 1) / NUM_STREAMS;
  const size_t smem_size = (size_t)WARP_PER_BLK * 512 * sizeof(uint64_t);

  cudaStream_t streams[NUM_STREAMS];
  for (int s = 0; s < NUM_STREAMS; s++)
    CUDA_CHECK(cudaStreamCreate(&streams[s]));

  cudaEvent_t ev_start, ev_end;
  CUDA_CHECK(cudaEventCreate(&ev_start));
  CUDA_CHECK(cudaEventCreate(&ev_end));
  CUDA_CHECK(cudaEventRecord(ev_start, 0));

  for (int s = 0; s < NUM_STREAMS; s++) {
    int offset = s * chunk;
    if (offset >= batch) break;

    int actual_chunk = ((offset + chunk) > batch) ? (batch - offset) : chunk;
    const int blocks = (actual_chunk + WARP_PER_BLK - 1) / WARP_PER_BLK;

    const size_t ct_off = (size_t)offset * ARR_LEN;
    const size_t exp_off = (size_t)offset * exp_u64_limbs;

    FMLE_mod3_Kernel<<<blocks, WARP_PER_BLK * 32, smem_size, streams[s]>>>(
        d_c_tilde + ct_off, d_exp + exp_off, tau, d_output + ct_off,
        actual_chunk, d_r0, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
        (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
        d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
        d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
    CUDA_CHECK(cudaGetLastError());
  }

  CUDA_CHECK(cudaEventRecord(ev_end, 0));
  CUDA_CHECK(cudaEventSynchronize(ev_end));

  float ms = 0.f;
  CUDA_CHECK(cudaEventElapsedTime(&ms, ev_start, ev_end));

  for (int s = 0; s < NUM_STREAMS; s++)
    CUDA_CHECK(cudaStreamDestroy(streams[s]));
  CUDA_CHECK(cudaEventDestroy(ev_start));
  CUDA_CHECK(cudaEventDestroy(ev_end));

  return ms;
}

// =============================================================
// 打印 Randomize 计时报告
// =============================================================
static void print_randomize_timing(const char *label, const RandomizeTiming &t,
                                   int batch) {
  float serial_ms = t.step3_ms + t.step4_ms;
  float gpu_total = t.step1_ms + t.step2_ms + t.pipeline_ms;
  float speedup = t.pipeline_ms > 0.f ? serial_ms / t.pipeline_ms : 0.f;
  printf("\n======================================================\n");
  printf("  %s 计时报告\n", label);
  printf("======================================================\n");
  printf("  Step1 h_s → h̃_s（1 warp）       : %8.4f ms\n", t.step1_ms);
  printf("  Step2 广播 h̃_s                   : %8.4f ms\n", t.step2_ms);
  printf("  Step3 各流模幂最大耗时            : %8.4f ms  [FMLE_mod2_Kernel]\n",
         t.step3_ms);
  printf("  Step4 各流乘法最大耗时            : %8.4f ms  [XYfixWarpVector]\n",
         t.step4_ms);
  printf("  Step3+4 无流水线参考值            : %8.4f ms\n", serial_ms);
  printf("  Step3+4 流水线实际耗时            : %8.4f ms  (加速 %.2fx)\n",
         t.pipeline_ms, speedup);
  printf("  ──────────────────────────────────────────\n");
  printf("  GPU 计算总时间（Step1+2+pipeline）: %8.4f ms\n", gpu_total);
  printf("  平均每次 Randomize GPU 计算       : %8.4f us/次\n",
         gpu_total * 1000.f / batch);
  printf("======================================================\n");
}

// =============================================================================
// paillier_subhomo2 所需的 GPU 模逆支持代码
// =============================================================================

// ── ① CGBN 批量模逆 kernel（来自 invmod6.cu，使用 inv_ 前缀类型）─────────────
//
// 每个 CGBN Instance 由 INV_TPI=32 个线程协作处理一个 4096-bit 大数的模逆。
// 输入：in_numbers[n]   — 待求逆的大数数组（inv_bn_mem_t 格式，base-2^32）
//        in_modulus      — 共享模数 n²（一份，所有 instance 共用）
// 输出：out_inverses[n]  — 模逆结果数组；若 gcd(x,m)>1 则置 0
// =============================================================================
__global__ void batch_mod_inverse_kernel_sub(cgbn_error_report_t *report,
                                             inv_bn_mem_t *out_inverses,
                                             inv_bn_mem_t *in_numbers,
                                             inv_bn_mem_t *in_modulus, int n) {
  int tid = blockIdx.x * blockDim.x + threadIdx.x;
  int instance_id = tid / INV_TPI;
  if (instance_id >= n) return;

  inv_context_t bn_context(cgbn_report_monitor, report, instance_id);
  inv_env_t env(bn_context.env<inv_env_t>());

  inv_bn_t x, m, r;
  cgbn_load(env, x, in_numbers + instance_id);
  cgbn_load(env, m, in_modulus);  // 所有 instance 共用同一个 n²

  bool ok = cgbn_modular_inverse(env, r, x, m);
  if (!ok) cgbn_set_ui32(env, r, 0);  // gcd(x,m)>1：逆元不存在，填 0

  cgbn_store(env, out_inverses + instance_id, r);
}

// ── ② GPU 格式转换：base-2^17 uint64[] → inv_bn_mem_t（base-2^32
// uint32）──────
//
// 逐实例：256 个 17-bit limbs（小端）→ 128 个 32-bit limbs（小端）
// 对应位段：output limb j 覆盖全局比特 [32j, 32j+31]，最多跨 3 个 17-bit
// limbs。 启动参数：<<<batch, 128>>>（每块 128 线程，每线程处理 1 个 32-bit
// 输出 limb）
// =============================================================================
__global__ void format_to_cgbn_kernel(
    inv_bn_mem_t *out,   // [batch]，CGBN 格式输出
    const uint64_t *in,  // [batch × ARR_LEN]，base-2^17 输入
    int batch) {
  int bid = blockIdx.x;  // 批次下标
  int j = threadIdx.x;   // 32-bit 输出 limb 下标（0..127）
  if (bid >= batch || j >= 128) return;

  const uint64_t *src = in + (size_t)bid * ARR_LEN;
  uint32_t result = 0;

  // 收集从第 start_bit 开始的 32 个比特
  int start_bit = j * 32;
  int out_pos = 0;
  int remaining = 32;
  int s_limb = start_bit / 17;     // 对应的 17-bit 起始 limb
  int s_bit_off = start_bit % 17;  // 在该 limb 内的偏移

  while (remaining > 0 && s_limb < ARR_LEN) {
    int available = 17 - s_bit_off;  // 当前 limb 剩余可用位数
    int take = (available < remaining) ? available : remaining;
    uint32_t piece =
        (uint32_t)((src[s_limb] >> s_bit_off) & ((1u << take) - 1));
    result |= (piece << out_pos);
    out_pos += take;
    remaining -= take;
    s_limb++;
    s_bit_off = 0;
  }

  out[bid]._limbs[j] = result;
}

// ── ③ GPU 格式转换：inv_bn_mem_t（base-2^32 uint32）→ base-2^17 uint64[]──────
//
// 逐实例：128 个 32-bit limbs（小端）→ 256 个 17-bit limbs（小端）
// 对应位段：output limb i 覆盖全局比特 [17i, 17i+16]，最多跨 2 个 32-bit
// limbs。 高于 4095 比特的部分（bits 4096..4351，即 17-bit limbs 241..255
// 的高位） 在合法 Paillier 密文中始终为 0，因此 src_limb≥128 时直接补 0 即可。
// 启动参数：<<<batch, 256>>>（每块 256 线程，每线程处理 1 个 17-bit 输出 limb）
// =============================================================================
__global__ void format_from_cgbn_kernel(
    uint64_t *out,           // [batch × ARR_LEN]，base-2^17 输出
    const inv_bn_mem_t *in,  // [batch]，CGBN 格式输入
    int batch) {
  int bid = blockIdx.x;  // 批次下标
  int i = threadIdx.x;   // 17-bit 输出 limb 下标（0..255）
  if (bid >= batch || i >= ARR_LEN) return;

  const uint32_t *src = in[bid]._limbs;
  uint64_t result = 0;

  int start_bit = i * 17;
  int s_limb = start_bit / 32;     // 对应的 32-bit 起始 limb
  int s_bit_off = start_bit % 32;  // 在该 limb 内的偏移

  int out_pos = 0;
  int remaining = 17;

  while (remaining > 0) {
    if (s_limb >= 128) break;  // 超出 4096-bit 范围，高位恒为 0
    int available = 32 - s_bit_off;
    int take = (available < remaining) ? available : remaining;
    uint32_t piece = (src[s_limb] >> s_bit_off) & ((1u << take) - 1);
    result |= ((uint64_t)piece << out_pos);
    out_pos += take;
    remaining -= take;
    s_limb++;
    s_bit_off = 0;
  }

  out[(size_t)bid * ARR_LEN + i] = result;
}

// ── ④ CPU 辅助：N2_arr（base-2^17 uint64，主机端）→ inv_bn_mem_t（base-2^32）
//
// 用于在 paillier_subhomo2 中将模数 n² 转换为 CGBN 格式后上传到设备。
// =============================================================================
static void bn17_to_cgbn_mem(const uint64_t *src, inv_bn_mem_t *dst) {
  memset(dst->_limbs, 0, sizeof(dst->_limbs));
  for (int j = 0; j < 128; j++) {
    uint32_t result = 0;
    int start_bit = j * 32;
    int out_pos = 0;
    int remaining = 32;
    int s_limb = start_bit / 17;
    int s_bit_off = start_bit % 17;
    while (remaining > 0 && s_limb < ARR_LEN) {
      int available = 17 - s_bit_off;
      int take = (available < remaining) ? available : remaining;
      uint32_t piece =
          (uint32_t)((src[s_limb] >> s_bit_off) & ((1u << take) - 1));
      result |= (piece << out_pos);
      out_pos += take;
      remaining -= take;
      s_limb++;
      s_bit_off = 0;
    }
    dst->_limbs[j] = result;
  }
}

// =============================================================================
// SubHomo 辅助：base-2^17 uint64_t[] ↔ libtommath mp_int
// =============================================================================

// uint64_t[ARR_LEN] base-2^17 小端序 → mp_int
static void bn17_to_mp_u64(const uint64_t *d17, mp_int *out) {
  // ARR_LEN*BASE_BITS = 256*17 = 4352 bit = 544 字节
  uint8_t le_bytes[544];
  memset(le_bytes, 0, sizeof(le_bytes));
  for (int i = 0; i < ARR_LEN; i++) {
    uint32_t val = (uint32_t)(d17[i] & 0x1FFFFu);
    int bit_base = i * BASE_BITS;
    for (int b = 0; b < BASE_BITS; b++) {
      if (val & (1u << b)) {
        int pos = bit_base + b;
        le_bytes[pos >> 3] |= (uint8_t)(1u << (pos & 7));
      }
    }
  }
  int used = 544;
  while (used > 1 && le_bytes[used - 1] == 0) used--;
  uint8_t be_bytes[544];
  for (int i = 0; i < used; i++) be_bytes[i] = le_bytes[used - 1 - i];
  mp_from_ubin(out, be_bytes, (size_t)used);
}

// mp_int → uint64_t[ARR_LEN] base-2^17 小端序
static void mp_to_bn17_u64(const mp_int *src, uint64_t *d17) {
  memset(d17, 0, ARR_LEN * sizeof(uint64_t));
  size_t needed = (size_t)mp_ubin_size(src);
  if (needed == 0) return;
  if (needed > 544) needed = 544;
  uint8_t be_bytes[544];
  memset(be_bytes, 0, sizeof(be_bytes));
  // mp_to_ubin 输出大端序，写入 be_bytes 末尾 needed 字节
  mp_to_ubin(src, be_bytes + (544 - needed), needed, NULL);
  // 翻转为小端序字节数组
  uint8_t le_bytes[544];
  for (int i = 0; i < 544; i++) le_bytes[i] = be_bytes[543 - i];
  // 提取 17-bit limbs
  for (int i = 0; i < ARR_LEN; i++) {
    int bit_base = i * BASE_BITS;
    uint32_t val = 0;
    for (int b = 0; b < BASE_BITS; b++) {
      int pos = bit_base + b;
      if (le_bytes[pos >> 3] & (1u << (pos & 7))) val |= (1u << b);
    }
    d17[i] = (uint64_t)val;
  }
}

// =============================================================================
// paillier_subhomo：密文同态减法  c̃ = c̃₁ · c₂⁻¹·R  (mod n²)
//
// SubHomo(c̃₁, c̃₂) 四步流程：
//   ① GPU  XYfixWarpIRVector <<<batch,32>>>: c̃₂ → c₂        蒙哥马利 → 普通域
//   ← D2H
//   ② CPU  mp_invmod(c₂, n²) → c₂⁻¹                         逐元素 CPU 求逆
//   → H2D
//   ③ GPU  XYfixWarpROneVector<<<batch,32>>>: c₂⁻¹ → c̃₂⁻¹   普通域 → 蒙哥马利
//   ④ GPU  XYfixWarpVector    <<<batch,32>>>: c̃₁·c̃₂⁻¹ → c̃   蒙哥马利乘法
//
// 注：XYfixWarpROneVector 按 i=blockIdx.x*32+threadIdx.x 同时索引 inoutAct，
//     故 d_r1_ct / d_r1_nct 必须先 broadcast 成 batch×ARR_LEN 份再传入。
// =============================================================================
void paillier_subhomo(
    int batch,
    const uint64_t *d_c1_tilde,  // [batch×ARR_LEN]  输入 c̃₁（只读）
    const uint64_t *d_c2_tilde,  // [batch×ARR_LEN]  输入 c̃₂（只读）
    uint64_t *d_result,          // [batch×ARR_LEN]  输出 c̃₁·c̃₂⁻¹
    uint64_t *d_negmodn, uint64_t *d_negmodn_shoup, uint64_t *d_modn,
    uint64_t *d_modn_shoup, uint64_t mod, const uint64_t *d_twiddle,
    const uint64_t *d_twiddle_shoup, const uint64_t *d_ICTTwiddle,
    const uint64_t *d_ICTTwiddle_shoup, const uint64_t *d_NCTtwiddle,
    const uint64_t *d_NCTtwiddle_shoup, const uint64_t *d_InvNCTtwiddle,
    const uint64_t *d_InvNCTtwiddle_shoup, uint64_t inv_val,
    uint64_t inv_shoup_val, const uint64_t *d_sample,
    const uint64_t *d_r1_ct,   // [ARR_LEN]  R² mod n² 的 CT 形式
    const uint64_t *d_r1_nct,  // [ARR_LEN]  R² mod n² 的 NCT 形式
    const uint64_t *N2_arr     // [ARR_LEN]  n²（主机端，base-2^17 小端序）
) {
  const size_t batch_bytes = (size_t)batch * ARR_LEN * sizeof(uint64_t);

  // ── 设备工作缓冲区 ─────────────────────────────────────────────────────────
  uint64_t *d_c2_work = NULL;     // c̃₂ 可写副本；Step① 原地改为普通域 c₂
  uint64_t *d_inv_dev = NULL;     // Step②→③→④ 的 c₂⁻¹ / c̃₂⁻¹
  uint64_t *d_r1_ct_bat = NULL;   // R² CT  广播后的 batch 份
  uint64_t *d_r1_nct_bat = NULL;  // R² NCT 广播后的 batch 份
  // 主机 pinned 缓冲区
  uint64_t *h_c2 = NULL;   // D2H：普通域 c₂
  uint64_t *h_inv = NULL;  // CPU 计算的 c₂⁻¹，待 H2D

  CUDA_CHECK(cudaMalloc(&d_c2_work, batch_bytes));
  CUDA_CHECK(cudaMalloc(&d_inv_dev, batch_bytes));
  CUDA_CHECK(cudaMalloc(&d_r1_ct_bat, batch_bytes));
  CUDA_CHECK(cudaMalloc(&d_r1_nct_bat, batch_bytes));
  CUDA_CHECK(cudaMallocHost(&h_c2, batch_bytes));
  CUDA_CHECK(cudaMallocHost(&h_inv, batch_bytes));

  // 将 c̃₁ 复制到 d_result（Step④ 将原地用乘积覆盖）
  CUDA_CHECK(
      cudaMemcpy(d_result, d_c1_tilde, batch_bytes, cudaMemcpyDeviceToDevice));
  // 将 c̃₂ 复制到工作区（Step① 将原地改为普通域）
  CUDA_CHECK(
      cudaMemcpy(d_c2_work, d_c2_tilde, batch_bytes, cudaMemcpyDeviceToDevice));

  // 将单份 R² CT/NCT 广播为 batch×ARR_LEN（供 Step③ 使用）
  {
    const int total = batch * ARR_LEN;
    const int blk = 256;
    const int grd = (total + blk - 1) / blk;
    broadcast_fill_kernel<<<grd, blk>>>(d_r1_ct_bat, d_r1_ct, batch);
    CUDA_CHECK(cudaGetLastError());
    broadcast_fill_kernel<<<grd, blk>>>(d_r1_nct_bat, d_r1_nct, batch);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
  }

  // ── Step①：GPU  c̃₂ → c₂ = FMLM(c̃₂, 1)  蒙哥马利 → 普通域 ───────────────
  printf("[SubHomo] Step① GPU c̃₂→c₂，batch=%d\n", batch);
  XYfixWarpIRVector<<<batch, 32>>>(
      d_c2_work, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
      (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
      d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
      d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaDeviceSynchronize());

  // ── D2H：普通域 c₂ 传回主机 ────────────────────────────────────────────────
  printf("[SubHomo] D2H c₂...\n");
  CUDA_CHECK(cudaMemcpy(h_c2, d_c2_work, batch_bytes, cudaMemcpyDeviceToHost));

  // ── Step②：CPU  c₂⁻¹ = mp_invmod(c₂, n²) ──────────────────────────────────
  printf("[SubHomo] Step② CPU mp_invmod ×%d...\n", batch);
  {
    mp_int n2;
    mp_init(&n2);
    bn17_to_mp_u64(N2_arr, &n2);

    int ok = 0, skip = 0;
    for (int k = 0; k < batch; k++) {
      const uint64_t *c2_limbs = h_c2 + (size_t)k * ARR_LEN;
      uint64_t *iv_limbs = h_inv + (size_t)k * ARR_LEN;
      mp_int c2, inv_c2;
      mp_init(&c2);
      mp_init(&inv_c2);
      bn17_to_mp_u64(c2_limbs, &c2);
      if (mp_invmod(&c2, &n2, &inv_c2) == MP_OKAY) {
        mp_to_bn17_u64(&inv_c2, iv_limbs);
        ok++;
      } else {
        // gcd(c₂, n²) > 1：逆元不存在，填零（该 case result 无意义）
        memset(iv_limbs, 0, ARR_LEN * sizeof(uint64_t));
        skip++;
      }
      mp_clear(&c2);
      mp_clear(&inv_c2);
    }
    mp_clear(&n2);
    printf("[SubHomo] Step② 完成：ok=%d, skip(gcd>1)=%d\n", ok, skip);
  }

  // ── H2D：c₂⁻¹ 上传至设备
  // ────────────────────────────────────────────────────
  printf("[SubHomo] H2D c₂⁻¹...\n");
  CUDA_CHECK(cudaMemcpy(d_inv_dev, h_inv, batch_bytes, cudaMemcpyHostToDevice));

  // ── Step③：GPU  c₂⁻¹ → c̃₂⁻¹ = FMLM(c₂⁻¹, R²)  普通域 → 蒙哥马利 ─────────
  printf("[SubHomo] Step③ GPU c₂⁻¹→c̃₂⁻¹，batch=%d\n", batch);
  XYfixWarpROneVector<<<batch, 32>>>(
      d_inv_dev, d_r1_ct_bat, d_r1_nct_bat, d_negmodn, d_negmodn_shoup, d_modn,
      d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup,
      d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup,
      d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaDeviceSynchronize());

  // ── Step④：GPU  c̃ = FMLM(c̃₁, c̃₂⁻¹)  蒙哥马利乘法 ──────────────────────────
  printf("[SubHomo] Step④ GPU c̃₁·c̃₂⁻¹→c̃，batch=%d\n", batch);
  XYfixWarpVector<<<batch, 32>>>(
      d_result,   // inout  = c̃₁（Step 前已复制，结果原地覆盖）
      d_inv_dev,  // inoutA = c̃₂⁻¹
      d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup, (uint64_t)ARR_LEN, mod,
      d_twiddle, d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup,
      d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle, d_InvNCTtwiddle_shoup,
      inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaDeviceSynchronize());

  // ── 释放工作缓冲区 ─────────────────────────────────────────────────────────
  cudaFree(d_c2_work);
  cudaFree(d_inv_dev);
  cudaFree(d_r1_ct_bat);
  cudaFree(d_r1_nct_bat);
  cudaFreeHost(h_c2);
  cudaFreeHost(h_inv);
}

// =============================================================================
// paillier_subhomo2：密文同态减法（全 GPU，无 D2H/H2D 传输）
//
// 与 paillier_subhomo 接口完全相同，但将：
//   D2H → CPU mp_invmod（串行）→ H2D
// 替换为：
//   GPU format_to_cgbn → GPU batch_mod_inverse_kernel_sub（CGBN 并行）
//                       → GPU format_from_cgbn
// 从而消除主机-设备数据传输，所有步骤在 GPU 上连续完成。
//
// SubHomo2(c̃₁, c̃₂) 完整流程：
//   ① GPU  XYfixWarpIRVector <<<batch,32>>>  : c̃₂ → c₂       (蒙哥马利→普通域)
//   ②a GPU format_to_cgbn_kernel<<<batch,128>>>  : c₂ → c₂_cgbn
//   (base-2^17→CGBN) ②b GPU batch_mod_inverse_kernel_sub       : c₂_cgbn →
//   inv_cgbn (CGBN 并行模逆) ②c GPU format_from_cgbn_kernel<<<batch,256>>>:
//   inv_cgbn → c₂⁻¹ (CGBN→base-2^17) ③  GPU  XYfixWarpROneVector<<<batch,32>>>:
//   c₂⁻¹ → c̃₂⁻¹   (普通域→蒙哥马利) ④  GPU  XYfixWarpVector    <<<batch,32>>>:
//   c̃₁·c̃₂⁻¹ → c̃   (蒙哥马利乘法)
// =============================================================================
void paillier_subhomo2(
    int batch,
    const uint64_t *d_c1_tilde,  // [batch×ARR_LEN]  输入 c̃₁（只读）
    const uint64_t *d_c2_tilde,  // [batch×ARR_LEN]  输入 c̃₂（只读）
    uint64_t *d_result,          // [batch×ARR_LEN]  输出 c̃₁·c̃₂⁻¹
    uint64_t *d_negmodn, uint64_t *d_negmodn_shoup, uint64_t *d_modn,
    uint64_t *d_modn_shoup, uint64_t mod, const uint64_t *d_twiddle,
    const uint64_t *d_twiddle_shoup, const uint64_t *d_ICTTwiddle,
    const uint64_t *d_ICTTwiddle_shoup, const uint64_t *d_NCTtwiddle,
    const uint64_t *d_NCTtwiddle_shoup, const uint64_t *d_InvNCTtwiddle,
    const uint64_t *d_InvNCTtwiddle_shoup, uint64_t inv_val,
    uint64_t inv_shoup_val, const uint64_t *d_sample,
    const uint64_t *d_r1_ct,   // [ARR_LEN]  R² mod n² 的 CT 形式
    const uint64_t *d_r1_nct,  // [ARR_LEN]  R² mod n² 的 NCT 形式
    const uint64_t *N2_arr,    // [ARR_LEN]  n²（主机端，base-2^17 小端序）
    bool verbose               // 是否打印进度
) {
  const size_t batch_bytes = (size_t)batch * ARR_LEN * sizeof(uint64_t);

  // ── 设备工作缓冲区 ─────────────────────────────────────────────────────────
  uint64_t *d_c2_work = NULL;       // c̃₂ 可写副本；Step① 后变为普通域 c₂
  inv_bn_mem_t *d_c2_cgbn = NULL;   // c₂ 的 CGBN (base-2^32) 格式
  inv_bn_mem_t *d_inv_cgbn = NULL;  // 模逆结果的 CGBN 格式
  uint64_t *d_inv_dev = NULL;       // 模逆结果转回 base-2^17 格式：c₂⁻¹
  uint64_t *d_r1_ct_bat = NULL;     // R² CT  广播后的 batch 份
  uint64_t *d_r1_nct_bat = NULL;    // R² NCT 广播后的 batch 份
  inv_bn_mem_t *d_n2_cgbn = NULL;   // n² 的 CGBN 格式（模数，单份共享）

  CUDA_CHECK(cudaMalloc(&d_c2_work, batch_bytes));
  CUDA_CHECK(cudaMalloc(&d_c2_cgbn, (size_t)batch * sizeof(inv_bn_mem_t)));
  CUDA_CHECK(cudaMalloc(&d_inv_cgbn, (size_t)batch * sizeof(inv_bn_mem_t)));
  CUDA_CHECK(cudaMalloc(&d_inv_dev, batch_bytes));
  CUDA_CHECK(cudaMalloc(&d_r1_ct_bat, batch_bytes));
  CUDA_CHECK(cudaMalloc(&d_r1_nct_bat, batch_bytes));
  CUDA_CHECK(cudaMalloc(&d_n2_cgbn, sizeof(inv_bn_mem_t)));

  // ── 将 n²（host, base-2^17）转换为 CGBN 格式并上传设备 ───────────────────
  {
    inv_bn_mem_t h_n2_cgbn;
    bn17_to_cgbn_mem(N2_arr, &h_n2_cgbn);
    CUDA_CHECK(cudaMemcpy(d_n2_cgbn, &h_n2_cgbn, sizeof(inv_bn_mem_t),
                          cudaMemcpyHostToDevice));
  }

  // 将 c̃₁ 复制到 d_result（Step④ 原地覆盖为乘积）
  CUDA_CHECK(
      cudaMemcpy(d_result, d_c1_tilde, batch_bytes, cudaMemcpyDeviceToDevice));
  // 将 c̃₂ 复制到工作区（Step① 原地改为普通域）
  CUDA_CHECK(
      cudaMemcpy(d_c2_work, d_c2_tilde, batch_bytes, cudaMemcpyDeviceToDevice));

  // 将单份 R² CT/NCT 广播为 batch×ARR_LEN（供 Step③ 使用）
  {
    const int total = batch * ARR_LEN;
    const int blk = 256;
    const int grd = (total + blk - 1) / blk;
    broadcast_fill_kernel<<<grd, blk>>>(d_r1_ct_bat, d_r1_ct, batch);
    CUDA_CHECK(cudaGetLastError());
    broadcast_fill_kernel<<<grd, blk>>>(d_r1_nct_bat, d_r1_nct, batch);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
  }

  // ── Step①：GPU  c̃₂ → c₂ = FMLM(c̃₂, 1)  蒙哥马利 → 普通域 ───────────────
  if (verbose) printf("[SubHomo2] Step① GPU c̃₂→c₂，batch=%d\n", batch);
  XYfixWarpIRVector<<<batch, 32>>>(
      d_c2_work, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
      (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
      d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
      d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaDeviceSynchronize());

  // ── Step②a：GPU  c₂（base-2^17 uint64）→ c₂_cgbn（CGBN base-2^32）─────────
  // 每个 batch item 对应一个 block（128 线程，各处理一个 32-bit 输出 limb）
  if (verbose) printf("[SubHomo2] Step②a 格式转换 base-2^17 → CGBN\n");
  format_to_cgbn_kernel<<<batch, 128>>>(d_c2_cgbn, d_c2_work, batch);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaDeviceSynchronize());

  // ── Step②b：GPU  CGBN 批量模逆  c₂_cgbn → inv_cgbn ─────────────────────────
  // TPI=32 线程/instance；threads_per_block=256 → 8 instances/block
  if (verbose) printf("[SubHomo2] Step②b GPU CGBN 批量模逆，batch=%d\n", batch);
  {
    cgbn_error_report_t *report;
    cgbn_error_report_alloc(&report);

    const int threads_per_block = 256;  // 256 / INV_TPI = 8 instances/block
    const int blocks =
        (batch * INV_TPI + threads_per_block - 1) / threads_per_block;
    batch_mod_inverse_kernel_sub<<<blocks, threads_per_block>>>(
        report, d_inv_cgbn, d_c2_cgbn, d_n2_cgbn, batch);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());

    if (cgbn_error_report_check(report))
      fprintf(stderr, "[SubHomo2] CGBN 内部错误: %s\n",
              cgbn_error_string(report));
    cgbn_error_report_free(report);
  }

  // ── Step②c：GPU  inv_cgbn（CGBN）→ c₂⁻¹（base-2^17 uint64）──────────────
  // 每个 batch item 一个 block（256 线程，各处理一个 17-bit 输出 limb）
  if (verbose) printf("[SubHomo2] Step②c 格式转换 CGBN → base-2^17\n");
  format_from_cgbn_kernel<<<batch, 256>>>(d_inv_dev, d_inv_cgbn, batch);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaDeviceSynchronize());

  // ── Step③：GPU  c₂⁻¹ → c̃₂⁻¹ = FMLM(c₂⁻¹, R²)  普通域 → 蒙哥马利 ─────────
  if (verbose) printf("[SubHomo2] Step③ GPU c₂⁻¹→c̃₂⁻¹，batch=%d\n", batch);
  XYfixWarpROneVector<<<batch, 32>>>(
      d_inv_dev, d_r1_ct_bat, d_r1_nct_bat, d_negmodn, d_negmodn_shoup, d_modn,
      d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup,
      d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup,
      d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaDeviceSynchronize());

  // ── Step④：GPU  c̃ = FMLM(c̃₁, c̃₂⁻¹)  蒙哥马利乘法 ──────────────────────────
  if (verbose) printf("[SubHomo2] Step④ GPU c̃₁·c̃₂⁻¹→c̃，batch=%d\n", batch);
  XYfixWarpVector<<<batch, 32>>>(
      d_result,   // inout  = c̃₁（Step 前已复制，结果原地覆盖）
      d_inv_dev,  // inoutA = c̃₂⁻¹
      d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup, (uint64_t)ARR_LEN, mod,
      d_twiddle, d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup,
      d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle, d_InvNCTtwiddle_shoup,
      inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaDeviceSynchronize());

  // ── 释放工作缓冲区 ─────────────────────────────────────────────────────────
  cudaFree(d_c2_work);
  cudaFree(d_c2_cgbn);
  cudaFree(d_inv_cgbn);
  cudaFree(d_inv_dev);
  cudaFree(d_r1_ct_bat);
  cudaFree(d_r1_nct_bat);
  cudaFree(d_n2_cgbn);
}

// ─────────────────────────────────────────────────────────────────────────────
#define WINDOW_BITS 15
#define TABLE_SIZE (1 << WINDOW_BITS)  // 2048 个表项，对应 11-bit 窗口

// ─────────────────────────────────────────────────────────────────────────────

// =============================================================================
// generate_hs_table
//
// 随机生成一个约 4096-bit 的底数 hs（满足 0 < hs < n²），
// 建立 WINDOW_BITS=10 bit 窗口的模幂预计算表（FMLM 域，CPU 端）：
//   h_table[i × ARR_LEN] = hs^i · r mod n²，  i = 0, 1, …, TABLE_SIZE-1
//
// 其中 r = 2^(ARR_LEN × BASE_BITS) - 1 = 2^4352 - 1，是 FMLM 算法（Algorithm
// 1） 的参数，与 XYfixWarpVector 实现的乘法一致。 FMLM 域恒等元为 r mod
// n²（即标准域中 1 的 FMLM 表示）。
//
// 递推关系（在标准大整数乘法意义下，非 FMLM 乘法）：
//   table[0] = r mod n²
//   table[i] = table[i-1] × hs mod n²  →  = hs^i · r mod n²  ✓
//
// 参数：
//   N2_arr  [ARR_LEN]               n²（base-2^17 小端序，主机端只读）
//   h_hs    [ARR_LEN]               输出：随机底数 hs（base-2^17，标准域）
//   h_table [TABLE_SIZE × ARR_LEN]  输出：预计算表（FMLM 域，base-2^17）
// =============================================================================
void generate_hs_table(
    const uint64_t *N2_arr,  // [ARR_LEN]               n²（只读）
    uint64_t *h_hs,          // [ARR_LEN]               输出：底数 hs
    uint64_t *h_table  // [TABLE_SIZE × ARR_LEN]  输出：预计算表（FMLM 域）
) {
  // ── 1. 随机生成 hs ∈ (0, n²)
  // ──────────────────────────────────────────────── n² 最高非零 limb 在索引
  // 240，值为 27958（约 4095 bit） 策略：
  //   limb[0..239]  ← 随机 17-bit 值（均小于 BASE=131072，满足 < n²）
  //   limb[240]     ← rand() % n2_top_val（保证 hs < n²），重试到非零
  //   limb[241..]   ← 0
  const int n2_top_idx = 240;
  const uint64_t n2_top_val = 27958ULL;
  const uint64_t mask17 = (1ULL << BASE_BITS) - 1;

  do {
    for (int j = 0; j < ARR_LEN; j++) {
      if (j < n2_top_idx) {
        h_hs[j] =
            ((uint64_t)(uint32_t)rand() ^ ((uint64_t)(uint32_t)rand() << 15)) &
            mask17;
      } else if (j == n2_top_idx) {
        h_hs[j] = (uint64_t)(rand() % (int)n2_top_val);
      } else {
        h_hs[j] = 0ULL;
      }
    }
  } while (h_hs[n2_top_idx] == 0);  // 极小概率（< 1/27958）需要重试

  printf(
      "[generate_hs_table] 随机底数 hs 生成完成"
      "（limb[%d] = %llu，约 %d bit）\n",
      n2_top_idx, (unsigned long long)h_hs[n2_top_idx],
      n2_top_idx * BASE_BITS + 14);  // 14 ≈ floor(log2(27958))

  // ── 2. 转换 n² 和 hs 为 mp_int
  // ──────────────────────────────────────────────
  mp_int n2_mp, base_mp, cur_mp, r_mp;
  mp_init(&n2_mp);
  mp_init(&base_mp);
  mp_init(&cur_mp);
  mp_init(&r_mp);

  bn17_to_mp_u64(N2_arr, &n2_mp);
  bn17_to_mp_u64(h_hs, &base_mp);

  // ── 3. 计算 FMLM 参数 r = 2^(ARR_LEN×BASE_BITS) - 1 = 2^4352 - 1，再对 n²
  // 取模 r mod n² 是 FMLM 域中 1 的表示（恒等元），将作为预计算表的第 0 项
  mp_2expt(&r_mp, (int)ARR_LEN * BASE_BITS);  // r_mp = 2^4352
  mp_sub_d(&r_mp, 1, &r_mp);                  // r_mp = 2^4352 - 1
  mp_mod(&r_mp, &n2_mp, &r_mp);               // r_mp = (2^4352 - 1) mod n²

  printf(
      "[generate_hs_table] FMLM 参数 r = 2^4352 - 1，"
      "r mod n²  bit 长度 = %d\n",
      mp_count_bits(&r_mp));

  // ── 4. 建立预计算表：table[i] = hs^i · r mod n²（FMLM 域）──────────────────
  printf(
      "[generate_hs_table] 开始建立预计算表"
      "（WINDOW=%d bit，TABLE_SIZE=%d 项）...\n",
      WINDOW_BITS, TABLE_SIZE);

  struct timespec ts0, ts1;
  clock_gettime(CLOCK_MONOTONIC, &ts0);

  // table[0] = r mod n²（FMLM 域恒等元，即 hs^0 · r mod n²）
  mp_copy(&r_mp, &cur_mp);
  mp_to_bn17_u64(&cur_mp, h_table + (size_t)0 * ARR_LEN);

  // table[i] = table[i-1] × hs mod n²（普通乘法，递推得 hs^i · r mod n²）
  // mp_mulmod 支持输出与输入别名（内部创建临时数），故原地更新 cur_mp 安全
  for (int i = 1; i < TABLE_SIZE; i++) {
    mp_mulmod(&cur_mp, &base_mp, &n2_mp, &cur_mp);
    mp_to_bn17_u64(&cur_mp, h_table + (size_t)i * ARR_LEN);
  }

  clock_gettime(CLOCK_MONOTONIC, &ts1);
  double elapsed_ms = (double)(ts1.tv_sec - ts0.tv_sec) * 1.0e3 +
                      (double)(ts1.tv_nsec - ts0.tv_nsec) * 1.0e-6;

  printf(
      "[generate_hs_table] 预计算表构建完成"
      "（%d 次 mp_mulmod，耗时 %.1f ms，平均 %.3f ms/次）\n",
      TABLE_SIZE - 1, elapsed_ms, elapsed_ms / (TABLE_SIZE - 1));

  // ── 5. 清理
  // ──────────────────────────────────────────────────────────────────
  mp_clear(&n2_mp);
  mp_clear(&base_mp);
  mp_clear(&cur_mp);
  mp_clear(&r_mp);
}

// =============================================================================
// Getrn
//
// GPU 内核：对一批密文，各自计算 hs^{r_i} mod n²，输出蒙哥马利域（FMLM
// 域）结果。
//
// 算法：左到右 WINDOW_BITS-bit 窗口模幂（Left-to-Right Windowed
// Exponentiation）
//
//   每个 warp 独立处理一个密文，执行：
//     t = table[0]                    ← FMLM 域恒等元（r mod n²）
//     for k = num_windows-1 downto 0:
//         t = Square^{WINDOW_BITS}(t) ← WINDOW_BITS 次 FMLM 平方
//         w = r 的第 [k·W, (k+1)·W-1] 位组成的 WINDOW_BITS-bit 窗口值
//         t = FMLM(t, table[w])       ← 查表乘法
//     output = t                      ← hs^r · r^{-1} · r = hs^r·r mod n²（FMLM
//     域）
//
// 正确性说明：
//   table[i] = hs^i · r mod n²（generate_hs_table 建立，FMLM 域）
//   table[0] = r mod n²（FMLM 恒等元，FMLM(identity, X) = X）
//   对平方：FMLM(ã, ã) = a²·r mod n²，即 a² 的 FMLM 表示 ✓
//   对乘法：FMLM(ã, table[w]) = a·hs^w·r mod n²，即 (a·hs^w) 的 FMLM 表示 ✓
//   最终 t = hs^r · r mod n² ∈ FMLM 域 ✓
//
// 参数：
//   d_table    [TABLE_SIZE × ARR_LEN]  generate_hs_table 输出的 FMLM 域预计算表
//   d_r_batch  [batch × exp_limbs]     随机指数 r，压缩格式（小端序 uint64
//   limbs） tau                                r 的 bit 长度（须为 64
//   的整数倍） d_output   [batch × ARR_LEN]       输出 hs^r（FMLM
//   域，base-2^17） batch                              密文数量（每个 warp
//   处理一个）
//
// 共享内存布局（每个 warp 512 个 uint64）：
//   ws[0..255]   = t_buf     （FMLM 域累加器）
//   ws[256..511] = entry_buf （从全局内存加载的当前表项）
//
// 启动参数（示例，WARP_PER_BLK=8）：
//   smem_size = WARP_PER_BLK * 512 * sizeof(uint64_t)
//   Getrn<<<(batch+WARP_PER_BLK-1)/WARP_PER_BLK, WARP_PER_BLK*32,
//   smem_size>>>(...)
// =============================================================================
__global__ void Getrn(
    const uint64_t
        *__restrict__ d_table,  // [TABLE_SIZE × ARR_LEN]  FMLM 域预计算表
    const uint64_t
        *__restrict__ d_r_batch,  // [batch × exp_limbs] 随机指数（压缩格式）
    int tau,                      // r 的 bit 长度
    uint64_t *d_output,  // [batch × ARR_LEN]       输出 hs^r（FMLM 域）
    int batch,           // 密文数量
    uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n_poly, uint64_t mod,
    const uint64_t *twiddle, const uint64_t *twiddle_shoup,
    const uint64_t *ICTTwiddle, const uint64_t *ICTTwiddle_shoup,
    const uint64_t *NCTtwiddle, const uint64_t *NCTtwiddle_shoup,
    const uint64_t *InvNCTtwiddle, const uint64_t *InvNCTtwiddle_shoup,
    uint64_t inv, uint64_t inv_shoup, const uint64_t *sample) {
  const int warp_in_block = threadIdx.x >> 5;
  const int warps_per_block = blockDim.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;
  const uint32_t lane_id = threadIdx.x & 0x1F;

  if (global_warp_id >= batch) return;

  extern __shared__ uint64_t smem[];
  uint64_t *const ws = smem + warp_in_block * 512;
  uint64_t *const t_buf = ws;            // [256] FMLM 域累加器
  uint64_t *const entry_buf = ws + 256;  // [256] 当前查表项

  const int off = global_warp_id * ARR_LEN;

  // ── 加载本 warp 的指数 r（压缩格式：exp_limbs 个 uint64，小端序）──
  const int exp_limbs = tau / 64;
  const uint64_t *my_exp = d_r_batch + (size_t)global_warp_id * exp_limbs;
  uint64_t my_limb = 0ULL;
  if ((int)lane_id < exp_limbs) my_limb = my_exp[lane_id];

// ── 初始化 t = table[0]（FMLM 域恒等元 = r mod n²，即 hs^0 的 FMLM 表示）──
#pragma unroll
  for (int j = 0; j < 8; j++) t_buf[8 * lane_id + j] = d_table[8 * lane_id + j];
  __syncwarp();

  // ── 左到右 WINDOW_BITS-bit 窗口模幂
  // ──────────────────────────────────────────
  //
  // num_windows = ceil(tau / WINDOW_BITS)
  // 窗口 k（k = num_windows-1 .. 0）覆盖指数 bit [k*W .. (k+1)*W-1]（LSB 编号）
  // 第一个窗口（最高位）对 identity 做 WINDOW_BITS 次平方仍得 identity，
  // 随后乘以 table[top_window_val]，自然进入正确递推，无需特判。
  //
  const int num_windows = (tau + WINDOW_BITS - 1) / WINDOW_BITS;

  for (int k = num_windows - 1; k >= 0; k--) {
// ① WINDOW_BITS 次 FMLM 平方：t ← t^{2^WINDOW_BITS}（FMLM 域）
//    展开 WINDOW_BITS=10 次，避免循环开销；每次平方后同步 warp
#pragma unroll
    for (int sq = 0; sq < WINDOW_BITS; sq++) {
      XYfixWarpSquareVector_dev(t_buf, negmodn, negmodn_shoup, modn, modn_shoup,
                                n_poly, mod, twiddle, twiddle_shoup, ICTTwiddle,
                                ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
                                InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                                inv_shoup, sample);
      __syncwarp();
    }

    // ② 提取 10-bit 窗口值
    //    bit_pos = k * WINDOW_BITS：窗口起始位（LSB 编号）
    //    每个 lane 通过 __shfl 读取覆盖该窗口的一或两个 uint64 limb，
    //    warp 内所有 lane 计算出相同的 window_val（无分歧）
    const int bit_pos = k * WINDOW_BITS;
    const int limb_idx = bit_pos / 64;
    const int bit_off = bit_pos % 64;

    uint64_t lo = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)limb_idx);
    uint64_t window_val = (lo >> bit_off) & ((1ULL << WINDOW_BITS) - 1ULL);

    // 窗口跨 limb 边界：从相邻高位 limb 补充剩余位
    if (bit_off + WINDOW_BITS > 64 && limb_idx + 1 < exp_limbs) {
      uint64_t hi = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)(limb_idx + 1));
      window_val |= (hi << (64 - bit_off)) & ((1ULL << WINDOW_BITS) - 1ULL);
    }

    // ③ 加载 table[window_val] 到 entry_buf（全 warp 协作，coalesced 读取）
    //    window_val 对全 warp 统一，d_table 偏移确定，无 bank conflict
    const uint64_t *entry = d_table + window_val * (uint64_t)ARR_LEN;
#pragma unroll
    for (int j = 0; j < 8; j++)
      entry_buf[8 * lane_id + j] = entry[8 * lane_id + j];
    __syncwarp();

    // ④ FMLM 乘法：t ← FMLM(t, table[window_val])（结果写回 t_buf）
    XYfixWarpVector_dev(t_buf, entry_buf, negmodn, negmodn_shoup, modn,
                        modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                        ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                        NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                        inv, inv_shoup, sample);
    __syncwarp();
  }

// ── 写回全局内存（t_buf 即 hs^r 的 FMLM 域表示）──
#pragma unroll
  for (int j = 0; j < 8; j++)
    d_output[off + 8 * lane_id + j] = t_buf[8 * lane_id + j];
}

// =============================================================
// paillier_randomize2
//
// 功能：批量随机化密文，执行 Randomize(c̃₁) = c̃₁ · h̃_s^{r_i} mod n²（FMLM域）
//
// 流程：
//   Step① Getrn 内核：利用 10-bit 窗口预计算表计算 h̃_s^{r_i}（FMLM域输出）
//   Step② XYfixWarpVector：c̃_out[i] = FMLM(c̃₁[i], h̃_s^{r_i})
//
// 参数：
//   d_c1       [batch × ARR_LEN]          输入 c̃₁（FMLM域），结果原地覆写
//   d_table    [TABLE_SIZE × ARR_LEN]     hs 预计算表（FMLM域，由
//   generate_hs_table 建立） d_r_batch  [batch × tau_r/64]         随机指数
//   r_i（压缩格式，小端序 uint64） tau_r                                 r 的
//   bit 长度（Paillier 加密随机数为 k/2 = 1024 bit） batch 密文数量 其余为 NTT
//   参数（与 Getrn / XYfixWarpVector 完全一致）
//
// 返回：Step①+② GPU 总耗时（ms，cudaEvent 精度）
// =============================================================
float paillier_randomize2(
    uint64_t *d_c1,             // [batch × ARR_LEN]  输入兼输出（FMLM域）
    const uint64_t *d_table,    // [TABLE_SIZE × ARR_LEN]  hs 预计算表（FMLM域）
    const uint64_t *d_r_batch,  // [batch × tau_r/64]  随机指数 r_i
    int tau_r,                  // r 的 bit 长度（= 1024）
    int batch, uint64_t *d_negmodn, uint64_t *d_negmodn_shoup, uint64_t *d_modn,
    uint64_t *d_modn_shoup, uint64_t mod, const uint64_t *d_twiddle,
    const uint64_t *d_twiddle_shoup, const uint64_t *d_ICTTwiddle,
    const uint64_t *d_ICTTwiddle_shoup, const uint64_t *d_NCTtwiddle,
    const uint64_t *d_NCTtwiddle_shoup, const uint64_t *d_InvNCTtwiddle,
    const uint64_t *d_InvNCTtwiddle_shoup, uint64_t inv_val,
    uint64_t inv_shoup_val, const uint64_t *d_sample) {
  // 分配临时 buffer 存储 Getrn 输出 h̃_s^{r_i}（FMLM域）
  uint64_t *d_hs_r_tilde = nullptr;
  CUDA_CHECK(
      cudaMalloc(&d_hs_r_tilde, (size_t)batch * ARR_LEN * sizeof(uint64_t)));

  // Getrn 启动参数：每 warp 处理一条密文，WARP_PER_BLK 个 warp 一个 block
  const int g_wpb = WARP_PER_BLK;
  const int g_blks = (batch + g_wpb - 1) / g_wpb;
  const size_t g_smem = (size_t)g_wpb * 512 * sizeof(uint64_t);

  cudaEvent_t e0, e1;
  CUDA_CHECK(cudaEventCreate(&e0));
  CUDA_CHECK(cudaEventCreate(&e1));
  CUDA_CHECK(cudaEventRecord(e0));

  // Step①：Getrn 计算 h̃_s^{r_i}（FMLM域），结果写入 d_hs_r_tilde
  Getrn<<<g_blks, g_wpb * 32, g_smem>>>(
      d_table, d_r_batch, tau_r, d_hs_r_tilde, batch, d_negmodn,
      d_negmodn_shoup, d_modn, d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle,
      d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle,
      d_NCTtwiddle_shoup, d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val,
      inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());

  // Step②：c̃₁[i] · h̃_s^{r_i} → 结果原地写回 d_c1（FMLM域）
  XYfixWarpVector<<<batch, 32>>>(
      d_c1, d_hs_r_tilde, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
      (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
      d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
      d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());

  CUDA_CHECK(cudaEventRecord(e1));
  CUDA_CHECK(cudaEventSynchronize(e1));

  float ms = 0.f;
  CUDA_CHECK(cudaEventElapsedTime(&ms, e0, e1));
  CUDA_CHECK(cudaEventDestroy(e0));
  CUDA_CHECK(cudaEventDestroy(e1));
  cudaFree(d_hs_r_tilde);
  return ms;
}

// =============================================================
// paillier_encryptionhs
//
// 功能：批量 Paillier 加密
//   c̃_out[i] = FMLM( (1+m_i·n), h̃_s^{r_i} )  mod n²（FMLM 域）
//
// 流程：
//   Step① Getrn：10-bit 窗口查表计算 h̃_s^{r_i}（FMLM域输出）
//   Step② compute_plain_factor_batch_kernel：(1+m·n) mod n²（标准域）
//   Step③ XYfixWarpROneVector：(1+m·n) → FMLM 域，即 (1+m·n)·R mod n²
//   Step④ XYfixWarpVector：c̃ = FMLM((1̃+m·n), h̃_s^{r_i})
//
// 正确性验证：
//   c̃ = (1+m·n)·h_s^r·R mod n²  （FMLM 表示）
//   还原：c_std = c̃ · R⁻¹ mod n² = (1+m·n)·h_s^r mod n²
//
// 参数：
//   d_m_batch  [batch × ARR_LEN]          明文 m（base-2^BASE_BITS，标准域）
//   d_ct_out   [batch × ARR_LEN]          输出密文（FMLM域）
//   d_n        [ARR_LEN]                  公钥 n（标准域）
//   d_n2       [ARR_LEN]                  模数 n²（标准域）
//   d_table    [TABLE_SIZE × ARR_LEN]     hs 预计算表（FMLM域）
//   d_r_batch  [batch × tau_r/64]         随机指数 r_i（小端序 uint64）
//   tau_r                                 r 的 bit 长度（Paillier 中 = 1024）
//   batch                                 明文数量
//   d_r1_ct    [ARR_LEN]                  R² mod n² 的 CT  形式（所有 warp
//   共享） d_r1_nct   [ARR_LEN]                  R² mod n² 的 NCT 形式（所有
//   warp 共享） 其余为 NTT 参数（与 Getrn / XYfixWarpVector 一致）
//
// 返回：Step①~④ GPU 总耗时（ms，cudaEvent 精度）
// =============================================================
float paillier_encryptionhs(
    const uint64_t *d_m_batch,  // [batch × ARR_LEN]  明文（标准域）
    uint64_t *d_ct_out,         // [batch × ARR_LEN]  输出密文（FMLM域）
    const uint64_t *d_n,        // [ARR_LEN]  公钥 n（标准域）
    const uint64_t *d_n2,       // [ARR_LEN]  模数 n²（标准域）
    const uint64_t *d_table,    // [TABLE_SIZE × ARR_LEN]  hs 预计算表（FMLM域）
    const uint64_t *d_r_batch,  // [batch × tau_r/64]  随机指数 r_i
    int tau_r,                  // r 的 bit 长度（= 1024）
    int batch,
    const uint64_t
        *d_r1_ct,  // [ARR_LEN]  R² CT  形式（XYfixWarpROneVector 用）
    const uint64_t
        *d_r1_nct,  // [ARR_LEN]  R² NCT 形式（XYfixWarpROneVector 用）
    uint64_t *d_negmodn, uint64_t *d_negmodn_shoup, uint64_t *d_modn,
    uint64_t *d_modn_shoup, uint64_t mod, const uint64_t *d_twiddle,
    const uint64_t *d_twiddle_shoup, const uint64_t *d_ICTTwiddle,
    const uint64_t *d_ICTTwiddle_shoup, const uint64_t *d_NCTtwiddle,
    const uint64_t *d_NCTtwiddle_shoup, const uint64_t *d_InvNCTtwiddle,
    const uint64_t *d_InvNCTtwiddle_shoup, uint64_t inv_val,
    uint64_t inv_shoup_val, const uint64_t *d_sample) {
  // 分配临时 buffer 存储 Getrn 输出 h̃_s^{r_i}（FMLM域）
  uint64_t *d_hs_r_tilde = nullptr;
  CUDA_CHECK(
      cudaMalloc(&d_hs_r_tilde, (size_t)batch * ARR_LEN * sizeof(uint64_t)));

  // Getrn 启动参数：每 warp 处理一条加密，WARP_PER_BLK warp 一个 block
  const int g_wpb = WARP_PER_BLK;
  const int g_blks = (batch + g_wpb - 1) / g_wpb;
  const size_t g_smem = (size_t)g_wpb * 512 * sizeof(uint64_t);

  cudaEvent_t e0, e1;
  CUDA_CHECK(cudaEventCreate(&e0));
  CUDA_CHECK(cudaEventCreate(&e1));
  CUDA_CHECK(cudaEventRecord(e0));

  // Step①：Getrn 计算 h̃_s^{r_i}（FMLM域），结果写入 d_hs_r_tilde
  Getrn<<<g_blks, g_wpb * 32, g_smem>>>(
      d_table, d_r_batch, tau_r, d_hs_r_tilde, batch, d_negmodn,
      d_negmodn_shoup, d_modn, d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle,
      d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle,
      d_NCTtwiddle_shoup, d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val,
      inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());

  // Step②：计算 (1 + m·n) mod n²（标准域），结果写入 d_ct_out
  //   每个 block 处理一个明文，blockDim.x = ARR_LEN 线程各负责一个 limb
  compute_plain_factor_batch_kernel<<<batch, ARR_LEN>>>(
      d_m_batch, d_n, d_n2,
      d_ct_out,  // 复用输出缓冲区暂存 (1+m·n)（标准域）
      +1         // sign = +1：(1 + m·n)
  );
  CUDA_CHECK(cudaGetLastError());

  // Step③：(1 + m·n) 转入 FMLM 域
  //   XYfixWarpROneVector 计算 FMLM(factor, R²) = factor·R mod n²
  //   注意：XYfixWarpROneVector 用 lane_id（而非 blockIdx.x）索引
  //   inoutAct/inoutAnct，
  //         故 d_r1_ct / d_r1_nct 只需单份 ARR_LEN 数组，所有 warp 共享
  XYfixWarpROneVector<<<batch, 32>>>(
      d_ct_out, const_cast<uint64_t *>(d_r1_ct),
      const_cast<uint64_t *>(d_r1_nct), d_negmodn, d_negmodn_shoup, d_modn,
      d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup,
      d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup,
      d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());

  // Step④：FMLM((1̃+m·n), h̃_s^{r_i}) → 密文 c̃（FMLM域），原地写回 d_ct_out
  //   FMLM(A, B) = A·B·R⁻¹ mod n²
  //   = (1+m·n)·R · h_s^r·R · R⁻¹ = (1+m·n)·h_s^r·R mod n²  ✓
  XYfixWarpVector<<<batch, 32>>>(
      d_ct_out, d_hs_r_tilde, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
      (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
      d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
      d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());

  CUDA_CHECK(cudaEventRecord(e1));
  CUDA_CHECK(cudaEventSynchronize(e1));

  float ms = 0.f;
  CUDA_CHECK(cudaEventElapsedTime(&ms, e0, e1));
  CUDA_CHECK(cudaEventDestroy(e0));
  CUDA_CHECK(cudaEventDestroy(e1));
  cudaFree(d_hs_r_tilde);
  return ms;
}

// =============================================================================
// ou_addhomo：OU 批量密文同态加法（原地版）
//
// 数学依据：
//   OU 加密：C = G^m * H^r mod n
//   蒙哥马利（FMLM）域表示：C̃ = C * R mod n
//
//   同态加法利用密文乘法实现：
//     Enc(a + b) = Enc(a) * Enc(b) mod n
//   在 FMLM 域中等价于：
//     FMLM(C̃₁, C̃₂) = (C₁*R) * (C₂*R) * R⁻¹ mod n
//                    = C₁ * C₂ * R mod n
//                    = (C₁*C₂) 的 FMLM 域表示 = Enc(a+b) 的 FMLM 域表示  ✓
//
// 设计：原地操作
//   XYfixWarpVector 的 inout 参数既是第一操作数的读取位置，
//   也是结果的写回位置，两者必须是同一块内存。
//   因此本函数直接将 d_c1_tilde 作为 inout 传入，结果原地覆写 d_c1_tilde，
//   无需额外的 d_result 缓冲区，也无需任何 D2D 内存复制。
//
//   若调用方需要保留原始 c1，应在调用前自行完成备份。
//
// 输入/输出：
//   batch          密文对数量
//   d_c1_tilde     [batch × ARR_LEN]  输入 C̃₁（FMLM域）；调用后被结果 C̃₁₊₂ 覆写
//   d_c2_tilde     [batch × ARR_LEN]  输入 C̃₂（FMLM域，只读，不会被修改）
//
// 返回值：GPU 核函数耗时（ms，cudaEvent 精度）
// =============================================================================
float ou_addhomo(
    int batch,
    uint64_t *d_c1_tilde,        // [batch×ARR_LEN]  输入兼输出：C̃₁ → C̃₁₊₂
    const uint64_t *d_c2_tilde,  // [batch×ARR_LEN]  输入 C̃₂（只读）
    uint64_t *d_negmodn, uint64_t *d_negmodn_shoup, uint64_t *d_modn,
    uint64_t *d_modn_shoup, uint64_t mod, const uint64_t *d_twiddle,
    const uint64_t *d_twiddle_shoup, const uint64_t *d_ICTTwiddle,
    const uint64_t *d_ICTTwiddle_shoup, const uint64_t *d_NCTtwiddle,
    const uint64_t *d_NCTtwiddle_shoup, const uint64_t *d_InvNCTtwiddle,
    const uint64_t *d_InvNCTtwiddle_shoup, uint64_t inv_val,
    uint64_t inv_shoup_val, const uint64_t *d_sample) {
  cudaEvent_t ev_start, ev_stop;
  CUDA_CHECK(cudaEventCreate(&ev_start));
  CUDA_CHECK(cudaEventCreate(&ev_stop));
  CUDA_CHECK(cudaEventRecord(ev_start));

  // 每个 block = 1 个 warp（32 线程），处理一对 256-limb 密文。
  // FMLM(C̃₁, C̃₂) 的结果原地写回 d_c1_tilde。
  XYfixWarpVector<<<batch, 32>>>(
      d_c1_tilde, const_cast<uint64_t *>(d_c2_tilde), d_negmodn,
      d_negmodn_shoup, d_modn, d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle,
      d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle,
      d_NCTtwiddle_shoup, d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val,
      inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());

  CUDA_CHECK(cudaEventRecord(ev_stop));
  CUDA_CHECK(cudaEventSynchronize(ev_stop));

  float ms = 0.f;
  CUDA_CHECK(cudaEventElapsedTime(&ms, ev_start, ev_stop));
  CUDA_CHECK(cudaEventDestroy(ev_start));
  CUDA_CHECK(cudaEventDestroy(ev_stop));
  return ms;
}

// =============================================================
// ou_mulplain
//
// 功能：OU 批量密文乘明文（c̃^k → c^k·R mod n），使用 CUDA 流并行
//
// 公式：
//   c^p mod n = (G^m · H^r)^p mod n     ← OU 密文乘明文 p（明文标量）
//   蒙哥马利域：FMLE(c̃, k) = c^k · R mod n  （输入/输出均在蒙哥马利域）
//
// 与 paillier_mulplain 的唯一差异：
//   · tau = OU_TAU = 1408（= 22×64，覆盖 1363-bit 明文，高位补零）
//   · 指数内存步长 = OU_EXP_LIMBS = 22（不是 EXP_U64_LIMBS = 32）
//   · 传入 d_modn 应为 OU 的 n（而非 Paillier 的 n²）
//
// 参数：
//   d_ciphertexts  [batch * ARR_LEN]       蒙哥马利域密文（设备）
//   d_exps         [batch * OU_EXP_LIMBS]  明文 k：22 个 uint64_t/个，
//                                           LSB-first，base-2^64，高位补零
//   d_output       [batch * ARR_LEN]       输出，蒙哥马利域 c^k·R mod n（设备）
//   d_r0           [ARR_LEN]               R mod n（Montgomery 域中"1"的表示）
//   其余 NTT 参数与 paillier_mulplain 完全一致
// =============================================================
MulPlainTiming ou_mulplain(
    const uint64_t *d_ciphertexts, const uint64_t *d_exps, uint64_t *d_output,
    int batch, const uint64_t *d_r0, uint64_t *d_negmodn,
    uint64_t *d_negmodn_shoup, uint64_t *d_modn, uint64_t *d_modn_shoup,
    uint64_t mod, const uint64_t *d_twiddle, const uint64_t *d_twiddle_shoup,
    const uint64_t *d_ICTTwiddle, const uint64_t *d_ICTTwiddle_shoup,
    const uint64_t *d_NCTtwiddle, const uint64_t *d_NCTtwiddle_shoup,
    const uint64_t *d_InvNCTtwiddle, const uint64_t *d_InvNCTtwiddle_shoup,
    uint64_t inv_val, uint64_t inv_shoup_val, const uint64_t *d_sample) {
  const int chunk = (batch + NUM_STREAMS - 1) / NUM_STREAMS;
  const size_t smem_size = (size_t)WARP_PER_BLK * 512 * sizeof(uint64_t);

  cudaStream_t streams[NUM_STREAMS];
  cudaEvent_t ev_ker[NUM_STREAMS][2];

  for (int s = 0; s < NUM_STREAMS; s++) {
    CUDA_CHECK(cudaStreamCreate(&streams[s]));
    CUDA_CHECK(cudaEventCreate(&ev_ker[s][0]));
    CUDA_CHECK(cudaEventCreate(&ev_ker[s][1]));
  }

  cudaEvent_t ev_pipe_start, ev_pipe_end;
  CUDA_CHECK(cudaEventCreate(&ev_pipe_start));
  CUDA_CHECK(cudaEventCreate(&ev_pipe_end));

  CUDA_CHECK(cudaEventRecord(ev_pipe_start, 0));

  for (int s = 0; s < NUM_STREAMS; s++) {
    int offset = s * chunk;
    if (offset >= batch) break;

    int actual_chunk = ((offset + chunk) > batch) ? (batch - offset) : chunk;
    const int blocks = (actual_chunk + WARP_PER_BLK - 1) / WARP_PER_BLK;

    size_t ct_off = (size_t)offset * ARR_LEN;
    size_t exp_off = (size_t)offset * OU_EXP_LIMBS;  // ← 22 个 uint64_t/明文

    CUDA_CHECK(cudaEventRecord(ev_ker[s][0], streams[s]));

    FMLE_mod2_Kernel<<<blocks, WARP_PER_BLK * 32, smem_size, streams[s]>>>(
        d_ciphertexts + ct_off, d_exps + exp_off,
        OU_TAU,  // ← 1408 bit，覆盖 1363-bit 明文
        d_output + ct_off, actual_chunk, d_r0, d_negmodn, d_negmodn_shoup,
        d_modn, d_modn_shoup, (uint64_t)ARR_LEN, mod, d_twiddle,
        d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup, d_NCTtwiddle,
        d_NCTtwiddle_shoup, d_InvNCTtwiddle, d_InvNCTtwiddle_shoup, inv_val,
        inv_shoup_val, d_sample);

    CUDA_CHECK(cudaEventRecord(ev_ker[s][1], streams[s]));
  }

  CUDA_CHECK(cudaEventRecord(ev_pipe_end, 0));
  CUDA_CHECK(cudaEventSynchronize(ev_pipe_end));
  CUDA_CHECK(cudaGetLastError());

  MulPlainTiming t = {0.f, 0.f};
  for (int s = 0; s < NUM_STREAMS; s++) {
    int offset = s * chunk;
    if (offset >= batch) break;
    float ms = 0.f;
    CUDA_CHECK(cudaEventElapsedTime(&ms, ev_ker[s][0], ev_ker[s][1]));
    if (ms > t.kernel_ms) t.kernel_ms = ms;
  }
  CUDA_CHECK(cudaEventElapsedTime(&t.pipeline_ms, ev_pipe_start, ev_pipe_end));

  for (int s = 0; s < NUM_STREAMS; s++) {
    cudaStreamDestroy(streams[s]);
    cudaEventDestroy(ev_ker[s][0]);
    cudaEventDestroy(ev_ker[s][1]);
  }
  cudaEventDestroy(ev_pipe_start);
  cudaEventDestroy(ev_pipe_end);

  return t;
}

// =============================================================================
// ou_build_base_table（内部辅助）
//
// 以给定底数 h_base 建立 WINDOW_BITS-bit 窗口模幂预计算表（FMLM 域，CPU 端）：
//   h_table[i × ARR_LEN] = base^i · r mod n，  i = 0, 1, …, TABLE_SIZE-1
//
// 其中 r = 2^(ARR_LEN×BASE_BITS) - 1 mod n（FMLM 域恒等元）。
//
// 递推关系（普通大整数乘法，非 FMLM 乘法）：
//   table[0] = r mod n
//   table[i] = table[i-1] × base mod n  →  = base^i · r mod n  ✓
// =============================================================================
static void ou_build_base_table(
    const char *tag,  // 日志前缀，如 "[generate_G_table]"
    const uint64_t
        *Modn,  // [ARR_LEN]               OU 模数 n（base-2^17 小端序，只读）
    const uint64_t *h_base,  // [ARR_LEN]               底数（base-2^17
                             // 小端序，标准域，只读）
    uint64_t *
        h_table  // [TABLE_SIZE × ARR_LEN]  输出：预计算表（FMLM 域，base-2^17）
) {
  // ── 1. 转换 n 和 base 为 mp_int
  // ──────────────────────────────────────────────
  mp_int n_mp, base_mp, cur_mp, r_mp;
  mp_init(&n_mp);
  mp_init(&base_mp);
  mp_init(&cur_mp);
  mp_init(&r_mp);

  bn17_to_mp_u64(Modn, &n_mp);
  bn17_to_mp_u64(h_base, &base_mp);

  // ── 2. 计算 FMLM 参数 r = 2^(ARR_LEN×BASE_BITS) - 1，再对 n 取模
  // ──────────── r mod n 是 FMLM 域中 1 的表示（恒等元），将作为预计算表的第 0
  // 项
  mp_2expt(&r_mp, (int)ARR_LEN * BASE_BITS);  // r_mp = 2^4352
  mp_sub_d(&r_mp, 1, &r_mp);                  // r_mp = 2^4352 - 1
  mp_mod(&r_mp, &n_mp, &r_mp);                // r_mp = (2^4352 - 1) mod n

  printf("%s FMLM 参数 r mod n bit 长度 = %d\n", tag, mp_count_bits(&r_mp));

  // ── 3. 建立预计算表：table[i] = base^i · r mod n（FMLM 域）─────────────────
  printf("%s 开始建立预计算表（WINDOW=%d bit，TABLE_SIZE=%d 项）...\n", tag,
         WINDOW_BITS, TABLE_SIZE);

  struct timespec ts0, ts1;
  clock_gettime(CLOCK_MONOTONIC, &ts0);

  // table[0] = r mod n（FMLM 域恒等元，即 base^0 · r mod n）
  mp_copy(&r_mp, &cur_mp);
  mp_to_bn17_u64(&cur_mp, h_table + (size_t)0 * ARR_LEN);

  // table[i] = table[i-1] × base mod n（递推得 base^i · r mod n）
  // mp_mulmod 支持输出与输入别名（内部创建临时数），原地更新 cur_mp 安全
  for (int i = 1; i < TABLE_SIZE; i++) {
    mp_mulmod(&cur_mp, &base_mp, &n_mp, &cur_mp);
    mp_to_bn17_u64(&cur_mp, h_table + (size_t)i * ARR_LEN);
  }

  clock_gettime(CLOCK_MONOTONIC, &ts1);
  double elapsed_ms = (double)(ts1.tv_sec - ts0.tv_sec) * 1.0e3 +
                      (double)(ts1.tv_nsec - ts0.tv_nsec) * 1.0e-6;

  printf(
      "%s 预计算表构建完成（%d 次 mp_mulmod，耗时 %.1f ms，平均 %.3f ms/次）\n",
      tag, TABLE_SIZE - 1, elapsed_ms, elapsed_ms / (TABLE_SIZE - 1));

  // ── 4. 清理
  // ──────────────────────────────────────────────────────────────────
  mp_clear(&n_mp);
  mp_clear(&base_mp);
  mp_clear(&cur_mp);
  mp_clear(&r_mp);
}

// =============================================================================
// generate_G_table
//
// 以 OU 公钥 G 为底数，建立 WINDOW_BITS=10 bit 窗口的模幂预计算表（FMLM 域，CPU
// 端）：
//   h_table[i × ARR_LEN] = G^i · r mod n，  i = 0, 1, …, TABLE_SIZE-1
//
// 其中 r = 2^(ARR_LEN×BASE_BITS) - 1 mod n（FMLM 域恒等元）。
//
// 参数：
//   Modn    [ARR_LEN]               OU 模数 n（base-2^17 小端序，只读）
//   h_G     [ARR_LEN]               OU 公钥 G（base-2^17 小端序，标准域，只读）
//   h_table [TABLE_SIZE × ARR_LEN]  输出：预计算表（FMLM 域，base-2^17）
// =============================================================================
void generate_G_table(
    const uint64_t *Modn,  // [ARR_LEN]               OU 模数 n（只读）
    const uint64_t *h_G,   // [ARR_LEN]               OU 公钥 G（只读，标准域）
    uint64_t *h_table      // [TABLE_SIZE × ARR_LEN]  输出：预计算表（FMLM 域）
) {
  ou_build_base_table("[generate_G_table]", Modn, h_G, h_table);
}

// =============================================================================
// generate_invG_table
//
// 以 OU 公钥 G 的逆元 invG 为底数，建立 WINDOW_BITS=10 bit 窗口的模幂预计算表
// （FMLM 域，CPU 端）：
//   h_table[i × ARR_LEN] = invG^i · r mod n，  i = 0, 1, …, TABLE_SIZE-1
//
// 用途：密文减明文 p 时，计算 c · invG^p mod n = c · G^{-p} mod n。
//
// 参数：
//   Modn      [ARR_LEN]               OU 模数 n（base-2^17 小端序，只读）
//   h_invG    [ARR_LEN]               OU 公钥 invG（base-2^17
//   小端序，标准域，只读） h_table   [TABLE_SIZE × ARR_LEN]
//   输出：预计算表（FMLM 域，base-2^17）
// =============================================================================
void generate_invG_table(
    const uint64_t *Modn,  // [ARR_LEN]               OU 模数 n（只读）
    const uint64_t
        *h_invG,  // [ARR_LEN]               OU 公钥 invG（只读，标准域）
    uint64_t *
        h_table  // [TABLE_SIZE × ARR_LEN]  输出：预计算表（FMLM 域，base-2^17）
) {
  ou_build_base_table("[generate_invG_table]", Modn, h_invG, h_table);
}

// =============================================================================
// Getgp
//
// GPU 内核：对一批 OU 明文 p_i，计算 G^{p_i} mod n，输出 FMLM 域结果。
//
// 算法与 Getrn 完全相同（左到右 WINDOW_BITS-bit 窗口模幂）；区别在于：
//   · d_G_table 由 generate_G_table 建立：table[i] = G^i · r mod n
//   · tau = OU_TAU = 1408（覆盖 1363-bit 私钥 p，对齐到 22×64 bit）
//   · 模数 n（OU modulus）通过 NTT 参数隐式传入
//
// 正确性：
//   table[i] = G^i · r mod n（FMLM 域），table[0] = r mod n（FMLM 恒等元）
//   最终 t = G^p · r mod n ∈ FMLM 域 ✓
//
// 参数：
//   d_G_table  [TABLE_SIZE × ARR_LEN]  generate_G_table 输出的 FMLM 域预计算表
//   d_p_batch  [batch × OU_EXP_LIMBS]  明文指数 p（小端序 uint64，每条 22 个
//   limb） tau                                p 的 bit 长度（传入 OU_TAU =
//   1408） d_output   [batch × ARR_LEN]       输出 G^p（FMLM 域，base-2^17）
//   batch                              明文数量（每个 warp 处理一条）
//
// 共享内存、启动参数与 Getrn 相同：
//   smem_size = WARP_PER_BLK * 512 * sizeof(uint64_t)
//   Getgp<<<(batch+WARP_PER_BLK-1)/WARP_PER_BLK, WARP_PER_BLK*32,
//   smem_size>>>(...)
// =============================================================================
__global__ void Getgp(
    const uint64_t *__restrict__ d_G_table,  // [TABLE_SIZE × ARR_LEN]  G
                                             // 预计算表（FMLM 域）
    const uint64_t
        *__restrict__ d_p_batch,  // [batch × OU_EXP_LIMBS]  明文指数（小端序）
    int tau,                      // p 的 bit 长度（= OU_TAU = 1408）
    uint64_t *d_output,  // [batch × ARR_LEN]        输出 G^p（FMLM 域）
    int batch, uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n_poly, uint64_t mod,
    const uint64_t *twiddle, const uint64_t *twiddle_shoup,
    const uint64_t *ICTTwiddle, const uint64_t *ICTTwiddle_shoup,
    const uint64_t *NCTtwiddle, const uint64_t *NCTtwiddle_shoup,
    const uint64_t *InvNCTtwiddle, const uint64_t *InvNCTtwiddle_shoup,
    uint64_t inv, uint64_t inv_shoup, const uint64_t *sample) {
  const int warp_in_block = threadIdx.x >> 5;
  const int warps_per_block = blockDim.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;
  const uint32_t lane_id = threadIdx.x & 0x1F;

  if (global_warp_id >= batch) return;

  extern __shared__ uint64_t smem[];
  uint64_t *const ws = smem + warp_in_block * 512;
  uint64_t *const t_buf = ws;            // [256] FMLM 域累加器
  uint64_t *const entry_buf = ws + 256;  // [256] 当前查表项

  const int off = global_warp_id * ARR_LEN;

  // 加载本 warp 的明文指数 p（压缩格式：tau/64 个 uint64，小端序）
  const int exp_limbs = tau / 64;
  const uint64_t *my_exp = d_p_batch + (size_t)global_warp_id * exp_limbs;
  uint64_t my_limb = 0ULL;
  if ((int)lane_id < exp_limbs) my_limb = my_exp[lane_id];

  const int num_windows = (tau + WINDOW_BITS - 1) / WINDOW_BITS;

  // ── 优化①：扫描最高非零窗口，跳过前导零的冗余迭代 ──────────────────────────
  // window_val 由 __shfl_sync 推导，对 warp 内所有 lane 完全一致，
  // 因此下面的 if/break 不产生 warp 分支分歧。
  int k_start = -1;
  uint64_t first_wval = 0;
  for (int k = num_windows - 1; k >= 0; k--) {
    const int bit_pos = k * WINDOW_BITS;
    const int limb_idx = bit_pos / 64;
    const int bit_off = bit_pos % 64;
    uint64_t lo = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)limb_idx);
    uint64_t wv = (lo >> bit_off) & ((1ULL << WINDOW_BITS) - 1ULL);
    if (bit_off + WINDOW_BITS > 64 && limb_idx + 1 < exp_limbs) {
      uint64_t hi = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)(limb_idx + 1));
      wv |= (hi << (64 - bit_off)) & ((1ULL << WINDOW_BITS) - 1ULL);
    }
    if (wv != 0) {
      k_start = k;
      first_wval = wv;
      break;
    }
  }

  // p == 0：直接输出 FMLM 恒等元 table[0]，无需任何模幂运算
  if (k_start < 0) {
#pragma unroll
    for (int j = 0; j < 8; j++)
      d_output[off + 8 * lane_id + j] = __ldg(d_G_table + 8 * lane_id + j);
    return;
  }

  // 用最高非零窗口直接初始化累加器，跳过对恒等元的冗余平方
  const uint64_t *init_entry = d_G_table + first_wval * (uint64_t)ARR_LEN;
#pragma unroll
  for (int j = 0; j < 8; j++)
    t_buf[8 * lane_id + j] = __ldg(init_entry + 8 * lane_id + j);
  __syncwarp();

  // ── 主循环：从 k_start-1 向下，只处理有效窗口 ────────────────────────────
  for (int k = k_start - 1; k >= 0; k--) {
// ① WINDOW_BITS 次 FMLM 平方
#pragma unroll
    for (int sq = 0; sq < WINDOW_BITS; sq++) {
      XYfixWarpSquareVector_dev(t_buf, negmodn, negmodn_shoup, modn, modn_shoup,
                                n_poly, mod, twiddle, twiddle_shoup, ICTTwiddle,
                                ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
                                InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                                inv_shoup, sample);
      __syncwarp();
    }

    // ② 提取 WINDOW_BITS-bit 窗口值
    const int bit_pos = k * WINDOW_BITS;
    const int limb_idx = bit_pos / 64;
    const int bit_off = bit_pos % 64;

    uint64_t lo = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)limb_idx);
    uint64_t window_val = (lo >> bit_off) & ((1ULL << WINDOW_BITS) - 1ULL);

    if (bit_off + WINDOW_BITS > 64 && limb_idx + 1 < exp_limbs) {
      uint64_t hi = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)(limb_idx + 1));
      window_val |= (hi << (64 - bit_off)) & ((1ULL << WINDOW_BITS) - 1ULL);
    }

    // ── 优化②：window_val == 0 时乘以恒等元结果不变，直接跳过 ──────────
    // window_val 对整个 warp 一致，if 不产生分支分歧
    if (window_val != 0) {
      // ③ 加载 table[window_val] 到 entry_buf
      const uint64_t *entry = d_G_table + window_val * (uint64_t)ARR_LEN;
#pragma unroll
      for (int j = 0; j < 8; j++)
        entry_buf[8 * lane_id + j] = __ldg(entry + 8 * lane_id + j);
      __syncwarp();

      // ④ FMLM 乘法：t ← FMLM(t, table[window_val])
      XYfixWarpVector_dev(t_buf, entry_buf, negmodn, negmodn_shoup, modn,
                          modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                          ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                          NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                          inv, inv_shoup, sample);
      __syncwarp();
    }
  }

// 写回全局内存（t_buf 即 G^p 的 FMLM 域表示）
#pragma unroll
  for (int j = 0; j < 8; j++)
    d_output[off + 8 * lane_id + j] = t_buf[8 * lane_id + j];
}

// =============================================================================
// Getinvgp
//
// GPU 内核：对一批 OU 明文 p_i，计算 invG^{p_i} mod n，输出 FMLM 域结果。
//
// 与 Getgp 完全对称，区别仅在于使用 invG 预计算表：
//   d_invG_table 由 generate_invG_table 建立：table[i] = invG^i · r mod n
//
// 用途：密文减明文 p 时，先用本内核得到 invG^p 的 FMLM 表示，
//       再与密文做一次 FMLM（XYfixWarpVector），即得 c · invG^p mod n。
//
// 正确性：
//   table[i] = invG^i · r mod n，table[0] = r mod n（FMLM 恒等元）
//   最终 t = invG^p · r mod n ∈ FMLM 域 ✓
//
// 参数：（同 Getgp，d_invG_table 替换 d_G_table）
//   d_invG_table [TABLE_SIZE × ARR_LEN]  generate_invG_table 输出的 FMLM
//   域预计算表 d_p_batch    [batch × OU_EXP_LIMBS]  明文指数 p（小端序
//   uint64，每条 22 个 limb） tau                                  p 的 bit
//   长度（传入 OU_TAU = 1408） d_output     [batch × ARR_LEN]       输出
//   invG^p（FMLM 域，base-2^17） batch                                明文数量
// =============================================================================
__global__ void Getinvgp(
    const uint64_t *__restrict__ d_invG_table,  // [TABLE_SIZE × ARR_LEN]  invG
                                                // 预计算表（FMLM 域）
    const uint64_t
        *__restrict__ d_p_batch,  // [batch × OU_EXP_LIMBS]  明文指数（小端序）
    int tau,                      // p 的 bit 长度（= OU_TAU = 1408）
    uint64_t *d_output,  // [batch × ARR_LEN]        输出 invG^p（FMLM 域）
    int batch, uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n_poly, uint64_t mod,
    const uint64_t *twiddle, const uint64_t *twiddle_shoup,
    const uint64_t *ICTTwiddle, const uint64_t *ICTTwiddle_shoup,
    const uint64_t *NCTtwiddle, const uint64_t *NCTtwiddle_shoup,
    const uint64_t *InvNCTtwiddle, const uint64_t *InvNCTtwiddle_shoup,
    uint64_t inv, uint64_t inv_shoup, const uint64_t *sample) {
  const int warp_in_block = threadIdx.x >> 5;
  const int warps_per_block = blockDim.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;
  const uint32_t lane_id = threadIdx.x & 0x1F;

  if (global_warp_id >= batch) return;

  extern __shared__ uint64_t smem[];
  uint64_t *const ws = smem + warp_in_block * 512;
  uint64_t *const t_buf = ws;            // [256] FMLM 域累加器
  uint64_t *const entry_buf = ws + 256;  // [256] 当前查表项

  const int off = global_warp_id * ARR_LEN;

  // 加载本 warp 的明文指数 p
  const int exp_limbs = tau / 64;
  const uint64_t *my_exp = d_p_batch + (size_t)global_warp_id * exp_limbs;
  uint64_t my_limb = 0ULL;
  if ((int)lane_id < exp_limbs) my_limb = my_exp[lane_id];

  const int num_windows = (tau + WINDOW_BITS - 1) / WINDOW_BITS;

  // ── 优化①：扫描最高非零窗口，跳过前导零的冗余迭代 ──────────────────────────
  int k_start = -1;
  uint64_t first_wval = 0;
  for (int k = num_windows - 1; k >= 0; k--) {
    const int bit_pos = k * WINDOW_BITS;
    const int limb_idx = bit_pos / 64;
    const int bit_off = bit_pos % 64;
    uint64_t lo = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)limb_idx);
    uint64_t wv = (lo >> bit_off) & ((1ULL << WINDOW_BITS) - 1ULL);
    if (bit_off + WINDOW_BITS > 64 && limb_idx + 1 < exp_limbs) {
      uint64_t hi = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)(limb_idx + 1));
      wv |= (hi << (64 - bit_off)) & ((1ULL << WINDOW_BITS) - 1ULL);
    }
    if (wv != 0) {
      k_start = k;
      first_wval = wv;
      break;
    }
  }

  // p == 0：直接输出 FMLM 恒等元 table[0]，无需任何模幂运算
  if (k_start < 0) {
#pragma unroll
    for (int j = 0; j < 8; j++)
      d_output[off + 8 * lane_id + j] = __ldg(d_invG_table + 8 * lane_id + j);
    return;
  }

  // 用最高非零窗口直接初始化累加器，跳过对恒等元的冗余平方
  const uint64_t *init_entry = d_invG_table + first_wval * (uint64_t)ARR_LEN;
#pragma unroll
  for (int j = 0; j < 8; j++)
    t_buf[8 * lane_id + j] = __ldg(init_entry + 8 * lane_id + j);
  __syncwarp();

  // ── 主循环：从 k_start-1 向下，只处理有效窗口 ────────────────────────────
  for (int k = k_start - 1; k >= 0; k--) {
// ① WINDOW_BITS 次 FMLM 平方
#pragma unroll
    for (int sq = 0; sq < WINDOW_BITS; sq++) {
      XYfixWarpSquareVector_dev(t_buf, negmodn, negmodn_shoup, modn, modn_shoup,
                                n_poly, mod, twiddle, twiddle_shoup, ICTTwiddle,
                                ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
                                InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                                inv_shoup, sample);
      __syncwarp();
    }

    // ② 提取 WINDOW_BITS-bit 窗口值
    const int bit_pos = k * WINDOW_BITS;
    const int limb_idx = bit_pos / 64;
    const int bit_off = bit_pos % 64;

    uint64_t lo = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)limb_idx);
    uint64_t window_val = (lo >> bit_off) & ((1ULL << WINDOW_BITS) - 1ULL);

    if (bit_off + WINDOW_BITS > 64 && limb_idx + 1 < exp_limbs) {
      uint64_t hi = __shfl_sync(0xFFFFFFFF, my_limb, (uint32_t)(limb_idx + 1));
      window_val |= (hi << (64 - bit_off)) & ((1ULL << WINDOW_BITS) - 1ULL);
    }

    // ── 优化②：window_val == 0 时乘以恒等元结果不变，直接跳过 ──────────
    if (window_val != 0) {
      // ③ 加载 table[window_val] 到 entry_buf
      const uint64_t *entry = d_invG_table + window_val * (uint64_t)ARR_LEN;
#pragma unroll
      for (int j = 0; j < 8; j++)
        entry_buf[8 * lane_id + j] = __ldg(entry + 8 * lane_id + j);
      __syncwarp();

      // ④ FMLM 乘法：t ← FMLM(t, table[window_val])
      XYfixWarpVector_dev(t_buf, entry_buf, negmodn, negmodn_shoup, modn,
                          modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                          ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                          NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                          inv, inv_shoup, sample);
      __syncwarp();
    }
  }

// 写回全局内存（t_buf 即 invG^p 的 FMLM 域表示）
#pragma unroll
  for (int j = 0; j < 8; j++)
    d_output[off + 8 * lane_id + j] = t_buf[8 * lane_id + j];
}

// =============================================================================
// AddSubpTiming
// =============================================================================
struct AddSubpTiming {
  float getxp_ms;  // Getgp / Getinvgp 内核耗时（ms）
  float fmlm_ms;   // XYfixWarpVector 内核耗时（ms）
  float total_ms;  // 端到端耗时（含 cudaMalloc/Free，ms）
};

// =============================================================================
// ou_addAndsubp
//
// 功能：OU 批量密文加/减明文
//
//   密文加明文（is_add=true）：
//     c̃_out[i] = FMLM(c̃[i], G^{p_i} · r mod n)
//             = c[i] · G^{p_i} · r mod n      ← FMLM 域中 c[i]·G^{p_i} mod n
//             的表示 ✓
//
//   密文减明文（is_add=false）：
//     c̃_out[i] = FMLM(c̃[i], invG^{p_i} · r mod n)
//             = c[i] · invG^{p_i} · r mod n   ← FMLM 域中 c[i]·G^{-p_i} mod n
//             的表示 ✓
//
// 流程：
//   Step① Getgp / Getinvgp：
//         窗口模幂查表，计算 G^{p_i}（或 invG^{p_i}）的 FMLM 域表示
//         → 写入临时 buffer d_gp_tilde
//   Step② XYfixWarpVector：
//         FMLM(c̃[i], d_gp_tilde[i])，结果原地覆写 d_ct[i]
//
// 参数：
//   is_add        true  → 密文加明文（使用 d_G_table）
//                 false → 密文减明文（使用 d_invG_table）
//   batch         密文/明文对数量
//   d_ct          [batch × ARR_LEN]          输入兼输出密文（FMLM
//   域，原地覆写） d_p_batch     [batch × OU_EXP_LIMBS]     明文指数 p（小端序
//   uint64，每条 22 limb） d_G_table     [TABLE_SIZE × ARR_LEN]
//   generate_G_table 输出的预计算表（FMLM 域） d_invG_table  [TABLE_SIZE ×
//   ARR_LEN]     generate_invG_table 输出的预计算表（FMLM 域） 其余为 NTT
//   参数（与 ou_addhomo / Getgp 完全一致）
//
// 返回：AddSubpTiming（Getxp 耗时、FMLM 耗时、端到端耗时，单位 ms）
// =============================================================================
AddSubpTiming ou_addAndsubp(
    bool is_add, int batch,
    uint64_t *d_ct,  // [batch × ARR_LEN]         输入/输出（FMLM 域，原地）
    const uint64_t
        *d_p_batch,  // [batch × OU_EXP_LIMBS]    明文指数（小端序 uint64）
    const uint64_t
        *d_G_table,  // [TABLE_SIZE × ARR_LEN]    G 预计算表（FMLM 域）
    const uint64_t
        *d_invG_table,  // [TABLE_SIZE × ARR_LEN]    invG 预计算表（FMLM 域）
    uint64_t *d_negmodn, uint64_t *d_negmodn_shoup, uint64_t *d_modn,
    uint64_t *d_modn_shoup, uint64_t mod, const uint64_t *d_twiddle,
    const uint64_t *d_twiddle_shoup, const uint64_t *d_ICTTwiddle,
    const uint64_t *d_ICTTwiddle_shoup, const uint64_t *d_NCTtwiddle,
    const uint64_t *d_NCTtwiddle_shoup, const uint64_t *d_InvNCTtwiddle,
    const uint64_t *d_InvNCTtwiddle_shoup, uint64_t inv_val,
    uint64_t inv_shoup_val, const uint64_t *d_sample) {
  AddSubpTiming t = {0.f, 0.f, 0.f};

  // ── 分配临时 buffer：存储 G^p（或 invG^p）的 FMLM 域表示
  // ──────────────────────
  uint64_t *d_gp_tilde = nullptr;
  CUDA_CHECK(
      cudaMalloc(&d_gp_tilde, (size_t)batch * ARR_LEN * sizeof(uint64_t)));

  // ── 内核启动参数
  // ──────────────────────────────────────────────────────────────
  const int wpb = WARP_PER_BLK;
  const int blks = (batch + wpb - 1) / wpb;
  const size_t smem = (size_t)wpb * 512 * sizeof(uint64_t);

  // ── cudaEvent 计时
  // ────────────────────────────────────────────────────────────
  cudaEvent_t ev_total_start, ev_total_end;
  cudaEvent_t ev_getxp_start, ev_getxp_end;
  cudaEvent_t ev_fmlm_start, ev_fmlm_end;
  CUDA_CHECK(cudaEventCreate(&ev_total_start));
  CUDA_CHECK(cudaEventCreate(&ev_total_end));
  CUDA_CHECK(cudaEventCreate(&ev_getxp_start));
  CUDA_CHECK(cudaEventCreate(&ev_getxp_end));
  CUDA_CHECK(cudaEventCreate(&ev_fmlm_start));
  CUDA_CHECK(cudaEventCreate(&ev_fmlm_end));

  CUDA_CHECK(cudaEventRecord(ev_total_start));

  // ── Step①：计算 G^p 或 invG^p，写入 d_gp_tilde
  // ───────────────────────────────
  CUDA_CHECK(cudaEventRecord(ev_getxp_start));

  if (is_add) {
    Getgp<<<blks, wpb * 32, smem>>>(
        d_G_table, d_p_batch, OU_TAU, d_gp_tilde, batch, d_negmodn,
        d_negmodn_shoup, d_modn, d_modn_shoup, (uint64_t)ARR_LEN, mod,
        d_twiddle, d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup,
        d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
        d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  } else {
    Getinvgp<<<blks, wpb * 32, smem>>>(
        d_invG_table, d_p_batch, OU_TAU, d_gp_tilde, batch, d_negmodn,
        d_negmodn_shoup, d_modn, d_modn_shoup, (uint64_t)ARR_LEN, mod,
        d_twiddle, d_twiddle_shoup, d_ICTTwiddle, d_ICTTwiddle_shoup,
        d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
        d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  }
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaEventRecord(ev_getxp_end));

  // ── Step②：FMLM(c̃, G^p̃) → 结果原地写回 d_ct
  // ───────────────────────────────── 每个 block = 1 个 warp（32
  // 线程），处理一对密文 XYfixWarpVector(inout=d_ct[i], in=d_gp_tilde[i]) →
  // d_ct[i] = c·G^p·r mod n
  CUDA_CHECK(cudaEventRecord(ev_fmlm_start));
  XYfixWarpVector<<<batch, 32>>>(
      d_ct, d_gp_tilde, d_negmodn, d_negmodn_shoup, d_modn, d_modn_shoup,
      (uint64_t)ARR_LEN, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
      d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
      d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample);
  CUDA_CHECK(cudaGetLastError());
  CUDA_CHECK(cudaEventRecord(ev_fmlm_end));

  CUDA_CHECK(cudaEventRecord(ev_total_end));
  CUDA_CHECK(cudaEventSynchronize(ev_total_end));

  // ── 收集耗时
  // ──────────────────────────────────────────────────────────────────
  CUDA_CHECK(cudaEventElapsedTime(&t.getxp_ms, ev_getxp_start, ev_getxp_end));
  CUDA_CHECK(cudaEventElapsedTime(&t.fmlm_ms, ev_fmlm_start, ev_fmlm_end));
  CUDA_CHECK(cudaEventElapsedTime(&t.total_ms, ev_total_start, ev_total_end));

  // ── 清理
  // ──────────────────────────────────────────────────────────────────────
  CUDA_CHECK(cudaEventDestroy(ev_total_start));
  CUDA_CHECK(cudaEventDestroy(ev_total_end));
  CUDA_CHECK(cudaEventDestroy(ev_getxp_start));
  CUDA_CHECK(cudaEventDestroy(ev_getxp_end));
  CUDA_CHECK(cudaEventDestroy(ev_fmlm_start));
  CUDA_CHECK(cudaEventDestroy(ev_fmlm_end));
  cudaFree(d_gp_tilde);

  return t;
}

// =============================================================================
// ou_subhomo：OU 密文同态减法（c̃₁ · c̃₂⁻¹ mod n，全 GPU）
//
// 直接复用 paillier_subhomo2 的四步流程，将模数从 Paillier 的 n²
// 替换为 OU 的 n（OU 的 n ≈ 4088 bit < INV_BITS=4096，CGBN 配置兼容）：
//
//   ①  GPU  XYfixWarpIRVector  : c̃₂    → c₂      (FMLM⁻¹, mod n)
//   ②abc GPU CGBN 批量模逆     : c₂    → c₂⁻¹    (mod n)
//   ③  GPU  XYfixWarpROneVector: c₂⁻¹  → c̃₂⁻¹   (FMLM × R²modn, mod n)
//   ④  GPU  XYfixWarpVector    : c̃₁·c̃₂⁻¹ → c̃    (FMLM, mod n)
//
// 参数：
//   d_c1_tilde    [batch×ARR_LEN]  被减数密文（蒙哥马利域，只读）
//   d_c2_tilde    [batch×ARR_LEN]  减数密文  （蒙哥马利域，只读）
//   d_result      [batch×ARR_LEN]  输出 c̃₁·c̃₂⁻¹ mod n（蒙哥马利域）
//   d_negmodn / d_negmodn_shoup    NTT 域 -n（CT 形式）及其 Shoup 值
//   d_modn  / d_modn_shoup         NTT 域  n（NCT 形式）及其 Shoup 值
//   mod                            NTT 素模数（25-bit，即 MOD）
//   d_twiddle…/d_ICTTwiddle…/
//   d_NCTtwiddle…/d_InvNCTtwiddle… 四组旋转因子及 Shoup 值
//   inv_val / inv_shoup_val        INTT 缩放因子 N^{-1} mod MOD 及其 Shoup 值
//   d_sample                       [ARR_LEN] FMLM 采样辅助数组
//   d_r2modn_ct   [ARR_LEN]        R² mod n 的 CT-NTT 形式
//                                  （对应 main 中的 d_ctR，由 Testctsample
//                                  生成）
//   d_r2modn_nct  [ARR_LEN]        R² mod n 的 NCT-NTT 形式
//                                  （对应 main 中的 d_nctR，由 Testnctsample
//                                  生成）
//   Nn_arr        [ARR_LEN]        OU 模数 n（主机端，base-2^17 小端序）
//   verbose                        是否打印各步进度
// =============================================================================
void ou_subhomo(
    int batch, const uint64_t *d_c1_tilde, const uint64_t *d_c2_tilde,
    uint64_t *d_result, uint64_t *d_negmodn, uint64_t *d_negmodn_shoup,
    uint64_t *d_modn, uint64_t *d_modn_shoup, uint64_t mod,
    const uint64_t *d_twiddle, const uint64_t *d_twiddle_shoup,
    const uint64_t *d_ICTTwiddle, const uint64_t *d_ICTTwiddle_shoup,
    const uint64_t *d_NCTtwiddle, const uint64_t *d_NCTtwiddle_shoup,
    const uint64_t *d_InvNCTtwiddle, const uint64_t *d_InvNCTtwiddle_shoup,
    uint64_t inv_val, uint64_t inv_shoup_val, const uint64_t *d_sample,
    const uint64_t *d_r2modn_ct,   // R² mod n，CT-NTT 形式  (main 中的 d_ctR)
    const uint64_t *d_r2modn_nct,  // R² mod n，NCT-NTT 形式 (main 中的 d_nctR)
    const uint64_t *Nn_arr,        // OU 模数 n，主机端 base-2^17（非 n²）
    bool verbose) {
  paillier_subhomo2(
      batch, d_c1_tilde, d_c2_tilde, d_result, d_negmodn, d_negmodn_shoup,
      d_modn, d_modn_shoup, mod, d_twiddle, d_twiddle_shoup, d_ICTTwiddle,
      d_ICTTwiddle_shoup, d_NCTtwiddle, d_NCTtwiddle_shoup, d_InvNCTtwiddle,
      d_InvNCTtwiddle_shoup, inv_val, inv_shoup_val, d_sample,
      d_r2modn_ct,  // paillier_subhomo2 此处期望 R² mod n²；OU 传 R² mod n
      d_r2modn_nct,
      Nn_arr,  // paillier_subhomo2 此处期望 n²；OU 传 n
      verbose);
}

