  //  =========================================================================
  //  ou_addAndsubp 正确性测试
  //
  //  密文加明文：c̃_out = FMLM(c̃, G^p·r mod n)  = c·G^p·r mod n（FMLM 域）
  //  密文减明文：c̃_out = FMLM(c̃, invG^p·r mod n) = c·invG^p·r mod n（FMLM 域）
  //
  //  流程：
  //    1. 定义公钥 ou_G / ou_invG，CPU 端建立预计算表，上传 GPU
  //    2. 随机生成 BATCH 个密文（< n，接近 4096 bit）
  //       和明文（< p，接近 1363 bit）
  //    3. H2D 传输密文×2（ADD/SUB 各一份）+ 明文，计时
  //    4. GPU：ou_addAndsubp(is_add=true)  → d_ct_add 原地覆写
  //    5. GPU：ou_addAndsubp(is_add=false) → d_ct_sub 原地覆写
  //    6. D2H 传输两份结果，计时
  //    7. 写入 ou_addAndsubp_test.txt 供 Python 验证
  //  =========================================================================
  {
    const int BATCH = 1000000;

    // OU 公钥 G（base-2^17，小端序，256 limb）
    static const uint64_t ou_G[ARR_LEN] = {
