    // OU 公钥 invG（base-2^17，小端序，256 limb）
    static const uint64_t ou_invG[ARR_LEN] = {
        75015,  51305,  11174,  79166,  10654,  117345, 79575,  125483, 192,
        111361, 15109,  37776,  85584,  122681, 15179,  105154, 25327,  22587,
